    (WORLD_BORDER_HEADER_BYTES + WORLD_MAX_BORDER_QUADS * WORLD_BORDER_QUAD_BYTES) as u64;
const WORLD_MATERIAL_HEADER_BYTES: usize = 144;
// Four copied lightmap coordinate pairs retain the source UV2 semantic for
// material families such as weather.  Keeping this in the shared explicit
// quad ABI avoids a Java-side lighting policy while allowing only the
// material programs which declare a lightmap contract to consume it.
const WORLD_MATERIAL_QUAD_BYTES: usize = 192;
const WORLD_MATERIAL_UNIFORM_BYTES: u64 = (WORLD_MATERIAL_HEADER_BYTES
    + WORLD_MAX_MATERIAL_QUADS_PER_BATCH * WORLD_MATERIAL_QUAD_BYTES)
    as u64;
const WORLD_MATERIAL_INDEX_BYTES: u64 = 6 * 4;
const WORLD_MESH_GPU_VERTEX_BYTES: usize = 5 * 4 * 4;
const WORLD_MESH_BATCH_HEADER_BYTES: usize = 16 * 4 + 16 * 4 + 16 * 4 + 4 * 4 + 4 * 4 + 4 * 4;
const WORLD_MESH_INSTANCE_BYTES: usize = 16 * 4 + 5 * 4 * 4;
const WORLD_MESH_INSTANCE_BUFFER_BYTES: u64 =
    (WORLD_MESH_BATCH_HEADER_BYTES + WORLD_MAX_MESH_INSTANCES * WORLD_MESH_INSTANCE_BYTES) as u64;
const WORLD_MESH_INSTANCE_STREAM_ALIGNMENT: usize = 256;
const WORLD_MESH_INSTANCE_STREAM_BINDING_RANGE_BYTES: u64 = WORLD_MESH_INSTANCE_BUFFER_BYTES;
/// Immutable streamed mesh generations share explicitly range-addressed GAL
/// buffers.  This bounds native buffer-object churn without asking a backend
/// to infer ownership or reconstruct a hidden mesh heap.
const WORLD_MESH_GEOMETRY_PAGE_BYTES: u64 = 16 * 1024 * 1024;
const WORLD_MESH_GEOMETRY_ALIGNMENT: u64 = 256;
const SOURCE_TERRAIN_FRAME_STREAM_SLOT_COUNT: usize = 3;
const SOURCE_TERRAIN_FRAME_STREAM_MIN_BYTES: u64 = 64 * 1024;
/// Hard cap for one completion-gated lowered-source frame stream.  A source
/// frame may contain several writers, but it must never be allowed to turn a
/// reusable slot into an unbounded native allocation.  The slot count above
/// therefore bounds aggregate residency to three times this value.
pub const LOWERED_SOURCE_FRAME_STREAM_MAX_BYTES: u64 = 256 * 1024 * 1024;
const WORLD_SHADER_COMPOSITE_UNIFORM_BYTES: u64 = TERRAIN_RUNTIME_COMPOSITE_UNIFORM_BYTES;
/// Two matrices plus the copied ARGB sky colour.  The top sky fan is static
/// Rust geometry; only these semantic frame values vary.
const WORLD_SKY_DISC_UNIFORM_BYTES: u64 = 44 * 4;

const CRACK_STAGE_COUNT: u32 = 10;
const CRACK_STAGE_SIZE: u32 = 16;
/// Capture at most once for one exact Java-selected submission.  A selected
/// source sequence deliberately uses a new frame/correlation pair per pose,
/// so a process-wide one-shot would force later poses onto an unrelated
/// external-window capture path.
static GAMEPLAY_ATTACHMENT_CAPTURE_REQUEST: Mutex<Option<(u64, u64)>> = Mutex::new(None);
/// The uncorrelated attachment probe is strictly one real submission per
/// process. Unlike the normal selector it has no Java screenshot identity, so
/// allowing it to repeat would turn a bounded diagnostic into unbounded I/O.
static GAMEPLAY_ATTACHMENT_DIAGNOSTIC_ONCE_CAPTURED: AtomicBool = AtomicBool::new(false);
static SELECTED_SOURCE_OUTPUT_CAPTURE_WRITTEN: AtomicBool = AtomicBool::new(false);
static STATIC_TERRAIN_APPEARANCE_TRACE_WRITTEN: AtomicBool = AtomicBool::new(false);
static STATIC_TERRAIN_APPEARANCE_TRACE_RECEIPTS: AtomicUsize = AtomicUsize::new(0);
static STATIC_TERRAIN_APPEARANCE_TRACE_DETAILS: AtomicUsize = AtomicUsize::new(0);
static STATIC_TERRAIN_ATLAS_TRACE_WRITTEN: AtomicBool = AtomicBool::new(false);

const WORLD_LINE_VERTEX_SHADER_VULKAN: &[u8] = br#"#version 450
struct LineSegment {
    vec4 start;
    vec4 end;
    vec4 color;
};
layout(set = 0, binding = 0, std140) uniform WorldLineBatch {
    mat4 view;
    mat4 projection;
    vec4 viewport;
    LineSegment segments[512];
};
layout(location = 0) flat out vec4 v_color;
void main() {
    int segment = gl_VertexIndex / 6;
    int corner = gl_VertexIndex - segment * 6;
    int endpoint = (corner == 0 || corner == 3 || corner == 5) ? 0 : 1;
    float side = (corner == 0 || corner == 1 || corner == 5) ? -1.0 : 1.0;
    vec3 start = segments[segment].start.xyz * (1.0 - (1.0 / 256.0));
    vec3 end = segments[segment].end.xyz * (1.0 - (1.0 / 256.0));
    vec4 start_clip = projection * view * vec4(start, 1.0);
    vec4 end_clip = projection * view * vec4(end, 1.0);
    vec2 start_ndc = start_clip.xy / start_clip.w;
    vec2 end_ndc = end_clip.xy / end_clip.w;
    vec2 screen_delta = (end_ndc - start_ndc) * viewport.xy;
    float length_px = max(length(screen_delta), 0.0001);
    vec2 normal = vec2(-screen_delta.y, screen_delta.x) / length_px;
    float width_px = max(segments[segment].start.w, 1.0);
    vec2 offset_ndc = normal * (width_px / viewport.xy) * side;
    vec4 clip = endpoint == 0 ? start_clip : end_clip;
    clip.xy += offset_ndc * clip.w;
#ifdef VULKANIC_GAL_ZERO_TO_ONE_CLIP_DEPTH
    clip.z = clip.z * 0.5 + clip.w * 0.5;
#endif
    gl_Position = clip;
    v_color = segments[segment].color;
}
"#;

const WORLD_LINE_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(location = 0) flat in vec4 v_color;
layout(location = 0) out vec4 out_color;
void main() {
    out_color = v_color;
}
"#;

// Matches Frozen's `SkyRenderer.buildSkyDisc(16.0F)`: one centre vertex and
// nine perimeter vertices from -180 through 180 degrees in 45 degree steps.
// Keeping the geometry in the shader makes it immutable backend-private data,
// while Java supplies only copied sky/camera semantics.
const WORLD_SKY_DISC_VERTEX_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 0, std140) uniform WorldSkyDisc {
    mat4 view;
    mat4 projection;
    vec4 color;
    vec4 fog_color;
    vec4 sky_end_padding;
};
const vec3 FAN[10] = vec3[](
    vec3(0.0, 16.0, 0.0),
    vec3(-512.0, 16.0, 0.0),
    vec3(-362.03867, 16.0, -362.03867),
    vec3(0.0, 16.0, -512.0),
    vec3(362.03867, 16.0, -362.03867),
    vec3(512.0, 16.0, 0.0),
    vec3(362.03867, 16.0, 362.03867),
    vec3(0.0, 16.0, 512.0),
    vec3(-362.03867, 16.0, 362.03867),
    vec3(-512.0, 16.0, 0.0)
);
layout(location = 0) out vec4 v_color;
// Frozen's core/sky.vsh leaves these as ordinary smooth varyings.  In
// particular, clipping this camera-relative fan retains GLSL's normal
// perspective-correct interpolation; do not substitute a backend-specific
// window-linear rule here.
layout(location = 1) out float v_spherical_distance;
layout(location = 2) out float v_cylindrical_distance;
void main() {
    vec3 position = FAN[gl_VertexIndex];
    // SkyRenderer builds the disc around the camera and uses Minecraft's
    // rotational ModelViewMat for it.  The semantic world view also carries
    // the camera translation for terrain, which must not move this
    // camera-relative primitive through its own fan.
    mat4 sky_view = view;
    sky_view[3].xyz = vec3(0.0);
    // GameRenderer supplies Minecraft's ordinary OpenGL clip-space
    // Matrix4f.perspective projection. VulkanicGAL owns the backend boundary,
    // so Vulkan lowers its -1..1 clip depth to 0..1 here; Java does not supply
    // a Vulkan-specific matrix or a native handle.
    vec4 clip = projection * sky_view * vec4(position, 1.0);
#ifdef VULKANIC_GAL_ZERO_TO_ONE_CLIP_DEPTH
    clip.z = clip.z * 0.5 + clip.w * 0.5;
#endif
    gl_Position = clip;
    v_color = color;
    v_spherical_distance = length(position);
    v_cylindrical_distance = max(length(position.xz), abs(position.y));
}
"#;

const WORLD_SKY_DISC_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 0, std140) uniform WorldSkyDisc {
    mat4 view;
    mat4 projection;
    vec4 color;
    vec4 fog_color;
    vec4 sky_end_padding;
};
layout(location = 0) in vec4 v_color;
layout(location = 1) in float v_spherical_distance;
layout(location = 2) in float v_cylindrical_distance;
layout(location = 0) out vec4 out_albedo;
layout(location = 1) out vec4 out_normal;
layout(location = 2) out vec4 out_material_light;
layout(location = 3) out vec4 out_world_position;
void main() {
    // Exact Frozen core/sky.fsh call: apply_fog(ColorModulator, spherical,
    // cylindrical, 0, FogSkyEnd, FogSkyEnd, FogSkyEnd, FogColor).
    float sky_end = sky_end_padding.x;
    float spherical_fog = clamp(v_spherical_distance / max(sky_end, 0.0001), 0.0, 1.0);
    float cylindrical_fog = clamp(v_cylindrical_distance / max(sky_end, 0.0001), 0.0, 1.0);
    float fog = max(spherical_fog, cylindrical_fog);
    out_albedo = vec4(mix(v_color.rgb, fog_color.rgb, fog * fog_color.a), 1.0);
    // Deferred lighting treats material alpha below 0.5 as background and
    // forwards albedo unchanged. Normal alpha is the later terrain-fog
    // factor, however: this sky writer has already applied Frozen's sky-fog
    // equation above, so it must explicitly opt out of that separate terrain
    // fog composite instead of letting it replace the fan with clear fog.
    out_normal = vec4(0.5, 0.5, 1.0, 0.0);
    out_material_light = vec4(0.0, 1.0, 1.0, 0.0);
    out_world_position = vec4(0.5, 0.5, 0.5, 0.0);
}
"#;

// The direct vanilla route writes straight to the acquired presentation
// target, rather than the source-execution G-buffer.  It uses the identical
// semantic sky/fog calculation above, with the single attachment required by
// that explicit direct pass.
const WORLD_SKY_DISC_FORWARD_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 0, std140) uniform WorldSkyDisc {
    mat4 view;
    mat4 projection;
    vec4 color;
    vec4 fog_color;
    vec4 sky_end_padding;
};
layout(location = 0) in vec4 v_color;
layout(location = 1) in float v_spherical_distance;
layout(location = 2) in float v_cylindrical_distance;
layout(location = 0) out vec4 out_color;
void main() {
    float sky_end = sky_end_padding.x;
    float spherical_fog = clamp(v_spherical_distance / max(sky_end, 0.0001), 0.0, 1.0);
    float cylindrical_fog = clamp(v_cylindrical_distance / max(sky_end, 0.0001), 0.0, 1.0);
    float fog = max(spherical_fog, cylindrical_fog);
    out_color = vec4(mix(v_color.rgb, fog_color.rgb, fog * fog_color.a), 1.0);
}
"#;

const WORLD_CRACK_VERTEX_SHADER_VULKAN: &[u8] = br#"#version 450
struct CrackQuad {
    vec4 p0;
    vec4 p1;
    vec4 p2;
    vec4 p3;
    vec4 uv_region;
    vec4 color;
};
layout(set = 0, binding = 0, std140) uniform CrackQuadBatch {
    mat4 view;
    mat4 projection;
    vec4 viewport;
    CrackQuad quads[512];
};
layout(location = 0) out vec2 v_uv;
layout(location = 1) out vec4 v_color;
const vec2 corner[6] = vec2[6](
    vec2(0.0, 0.0),
    vec2(1.0, 0.0),
    vec2(1.0, 1.0),
    vec2(1.0, 1.0),
    vec2(0.0, 1.0),
    vec2(0.0, 0.0)
);
void main() {
    int vertex = gl_VertexIndex;
    CrackQuad quad = quads[gl_InstanceIndex];
    vec2 c = corner[vertex];
    vec3 top = mix(quad.p0.xyz, quad.p1.xyz, c.x);
    vec3 bottom = mix(quad.p3.xyz, quad.p2.xyz, c.x);
    vec3 position = mix(top, bottom, c.y);
    vec4 clip = projection * view * vec4(position, 1.0);
#ifdef VULKANIC_GAL_ZERO_TO_ONE_CLIP_DEPTH
    clip.z = clip.z * 0.5 + clip.w * 0.5;
#endif
    gl_Position = clip;
    v_uv = vec2(
        quad.uv_region.x + c.x * quad.uv_region.z,
        quad.uv_region.y + c.y * quad.uv_region.w
    );
    v_color = quad.color;
}
"#;

const WORLD_CRACK_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 1) uniform texture2D Tex0;
layout(set = 0, binding = 2) uniform sampler Samp0;
layout(location = 0) in vec2 v_uv;
layout(location = 1) in vec4 v_color;
layout(location = 0) out vec4 out_color;
void main() {
    vec4 color = texture(sampler2D(Tex0, Samp0), v_uv) * v_color;
    if (color.a <= 0.0) {
        discard;
    }
    out_color = color;
}
"#;

const WORLD_BORDER_VERTEX_SHADER_VULKAN: &[u8] = br#"#version 450
struct BorderQuad {
    vec4 p0;
    vec4 p1;
    vec4 p2;
    vec4 p3;
    vec4 uv_region;
    vec4 scroll_border_distance;
    vec4 color;
};
layout(set = 0, binding = 0, std140) uniform WorldBorderBatch {
    mat4 view;
    mat4 projection;
    vec4 viewport;
    BorderQuad quads[64];
};
layout(location = 0) out vec2 v_uv;
layout(location = 1) out vec4 v_color;
const vec2 corner[6] = vec2[6](
    vec2(0.0, 0.0),
    vec2(1.0, 0.0),
    vec2(1.0, 1.0),
    vec2(1.0, 1.0),
    vec2(0.0, 1.0),
    vec2(0.0, 0.0)
);
void main() {
    int vertex = gl_VertexIndex;
    BorderQuad quad = quads[gl_InstanceIndex];
    vec2 c = corner[vertex];
    vec3 top = mix(quad.p0.xyz, quad.p1.xyz, c.x);
    vec3 bottom = mix(quad.p3.xyz, quad.p2.xyz, c.x);
    vec3 position = mix(top, bottom, c.y);
    vec4 clip = projection * view * vec4(position, 1.0);
#ifdef VULKANIC_GAL_ZERO_TO_ONE_CLIP_DEPTH
    clip.z = clip.z * 0.5 + clip.w * 0.5;
#endif
    gl_Position = clip;
    v_uv = vec2(
        quad.uv_region.x + c.x * quad.uv_region.z + quad.scroll_border_distance.x,
        quad.uv_region.y + c.y * quad.uv_region.w + quad.scroll_border_distance.y
    );
    v_color = quad.color;
}
"#;

const WORLD_BORDER_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 1) uniform texture2D Tex0;
layout(set = 0, binding = 2) uniform sampler Samp0;
layout(location = 0) in vec2 v_uv;
layout(location = 1) in vec4 v_color;
layout(location = 0) out vec4 out_color;
void main() {
    vec4 color = texture(sampler2D(Tex0, Samp0), v_uv) * v_color;
    if (color.a <= 0.0) {
        discard;
    }
    out_color = color;
}
"#;

const WORLD_MATERIAL_VERTEX_SHADER_VULKAN: &[u8] = br#"#version 450
#ifdef VULKANIC_GAL_PARTICLE_LIGHTMAP
layout(set = 1, binding = 0) uniform texture2D LightmapTex;
layout(set = 1, binding = 1) uniform sampler LightmapSamp;
#endif
struct MaterialQuad {
    vec4 p0;
    vec4 p1;
    vec4 p2;
    vec4 p3;
    vec4 uv0_uv1;
    vec4 uv2_uv3;
    vec4 color0;
    vec4 color1;
    vec4 color2;
    vec4 color3;
    vec4 light0_light1;
    vec4 light2_light3;
};
layout(set = 0, binding = 0, std430) readonly buffer WorldMaterialBatch {
    mat4 view;
    mat4 projection;
    vec4 viewport_cutout;
    MaterialQuad quads[4096];
};
layout(location = 0) out vec2 v_uv;
layout(location = 1) out vec4 v_color;
layout(location = 2) flat out vec4 v_material;
layout(location = 3) out float v_camera_distance;
layout(location = 4) out vec2 v_lightmap_uv;
const vec2 corner[4] = vec2[4](
    vec2(0.0, 0.0),
    vec2(1.0, 0.0),
    vec2(1.0, 1.0),
    vec2(0.0, 1.0)
);
void main() {
    MaterialQuad quad = quads[gl_InstanceIndex];
    int vertex = gl_VertexIndex;
    vec2 c = corner[vertex];
    vec3 top = mix(quad.p0.xyz, quad.p1.xyz, c.x);
    vec3 bottom = mix(quad.p3.xyz, quad.p2.xyz, c.x);
    vec3 position = mix(top, bottom, c.y);
    vec2 uv_top = mix(quad.uv0_uv1.xy, quad.uv0_uv1.zw, c.x);
    vec2 uv_bottom = mix(quad.uv2_uv3.zw, quad.uv2_uv3.xy, c.x);
    // Cloud callsites provide camera-relative positions, mirroring Frozen's
    // CloudInfo offset contract. All other material producers provide world
    // positions. Remove translation only for the cloud-family range so a
    // moving camera cannot apply its translation twice to cloud geometry.
    mat4 material_view = view;
    if (viewport_cutout.w > 0.0) {
        material_view[3].xyz = vec3(0.0);
    }
    vec4 camera_position = material_view * vec4(position, 1.0);
    vec4 clip = projection * camera_position;
#ifdef VULKANIC_GAL_ZERO_TO_ONE_CLIP_DEPTH
    clip.z = clip.z * 0.5 + clip.w * 0.5;
#endif
    gl_Position = clip;
    v_uv = mix(uv_top, uv_bottom, c.y);
    vec4 color_top = mix(quad.color0, quad.color1, c.x);
    vec4 color_bottom = mix(quad.color3, quad.color2, c.x);
    v_color = mix(color_top, color_bottom, c.y);
    vec2 light_top = mix(quad.light0_light1.xy, quad.light0_light1.zw, c.x);
    vec2 light_bottom = mix(quad.light2_light3.xy, quad.light2_light3.zw, c.x);
    v_lightmap_uv = mix(light_top, light_bottom, c.y);
#ifdef VULKANIC_GAL_PARTICLE_LIGHTMAP
    // Frozen's particle/weather vertex program fetches UV2 here, before the
    // rasterizer interpolates vertexColor across a rain quad. Sampling this
    // in the fragment stage is observably different at light boundaries.
    v_color *= texelFetch(sampler2D(LightmapTex, LightmapSamp), ivec2(v_lightmap_uv) / 16, 0);
#endif
    // `viewport_cutout.w` is a cloud-only semantic range. Zero means this
    // ordinary material is not a vanilla cloud face. The distance is taken
    // after the copied camera transform, matching Frozen's
    // `fog_spherical_distance` input rather than a world-origin distance.
    v_material = vec4(viewport_cutout.z, viewport_cutout.w, 0.0, 0.0);
    v_camera_distance = length(camera_position.xyz);
}
"#;

const WORLD_MATERIAL_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 1) uniform texture2D Tex0;
layout(set = 0, binding = 2) uniform sampler Samp0;
layout(location = 0) in vec2 v_uv;
layout(location = 1) in vec4 v_color;
layout(location = 2) flat in vec4 v_material;
layout(location = 3) in float v_camera_distance;
layout(location = 0) out vec4 out_color;
void main() {
    vec4 color = texture(sampler2D(Tex0, Samp0), v_uv) * v_color;
    if (v_material.x > 0.0 && color.a < v_material.x) {
        discard;
    }
    // Vanilla's `rendertype_clouds.fsh` fades the already-modulated cloud
    // alpha by linear spherical fog from zero to `FogCloudsEnd`. This stays
    // a cloud-family semantic; weather and generic translucent materials do
    // not inherit it merely because they use the same private quad stream.
    if (v_material.y > 0.0) {
        color.a *= 1.0 - clamp(v_camera_distance / v_material.y, 0.0, 1.0);
    }
    out_color = color;
}
"#;

// Frozen's weather and particle streams use the particle vertex contract: their
// copied UV2 is converted to a 16x16 integer lightmap coordinate and fetched
// without filtering.  This is a distinct source-family pipeline, so ordinary
// material producers never acquire a lightmap dependency just because they
// share the compact quad stream.
const WORLD_PARTICLE_MATERIAL_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 1) uniform texture2D Tex0;
layout(set = 0, binding = 2) uniform sampler Samp0;
layout(location = 0) in vec2 v_uv;
layout(location = 1) in vec4 v_color;
layout(location = 0) out vec4 out_color;
void main() {
    vec4 color = texture(sampler2D(Tex0, Samp0), v_uv) * v_color;
    // Frozen's particle fragment program treats alpha as a
    // cutout predicate after lightmap modulation, not blend coverage.
    if (color.a < 0.1) {
        discard;
    }
    out_color = vec4(color.rgb, 1.0);
}
"#;

// Frozen core/position_tex discards a zero-alpha texture sample before
// modulation. A generic zero-threshold material would instead replace target
// alpha with zero under Overlay blending, violating the celestial contract.
const WORLD_CELESTIAL_MATERIAL_FRAGMENT_SHADER_VULKAN: &[u8] = br#"#version 450
layout(set = 0, binding = 1) uniform texture2D Tex0;
layout(set = 0, binding = 2) uniform sampler Samp0;
layout(location = 0) in vec2 v_uv;
layout(location = 1) in vec4 v_color;
layout(location = 0) out vec4 out_color;
void main() {
    vec4 color = texture(sampler2D(Tex0, Samp0), v_uv);
    if (color.a == 0.0) { discard; }
    out_color = color * v_color;
}
"#;

#[derive(Clone, Copy, Debug)]
pub struct WorldLineSegmentRequest {
    pub stratum: u32,
    pub style: u32,
    pub depth_policy: u32,
    pub color_argb: u32,
    pub line_width: f32,
    pub start: [f32; 3],
    pub end: [f32; 3],
    pub viewport_width: u32,
    pub viewport_height: u32,
}

#[derive(Clone, Debug)]
pub struct WorldCrackQuadRequest {
    pub stratum: u32,
    pub stage: u32,
    pub depth_policy: u32,
    pub color_argb: u32,
    pub vertices: [[f32; 3]; 4],
    pub viewport_width: u32,
    pub viewport_height: u32,
}

#[derive(Clone, Debug)]
pub struct WorldBorderQuadRequest {
    pub stratum: u32,
    pub texture_id: u32,
    pub depth_policy: u32,
    pub blend_policy: u32,
    pub cull_policy: u32,
    pub color_argb: u32,
    pub border_size: f32,
    pub distance_to_border: f32,
    pub scroll: [f32; 2],
    pub uv_region: [f32; 4],
    pub vertices: [[f32; 3]; 4],
    pub viewport_width: u32,
    pub viewport_height: u32,
}

#[derive(Clone, Debug)]
pub struct WorldMaterialQuadRequest {
    pub stratum: u32,
    pub material_id: u32,
    pub texture_id: u32,
    pub material_mode: u32,
    pub depth_policy: u32,
    pub cull_policy: u32,
    pub topology: u32,
    pub winding: u32,
    pub color_argb: u32,
    pub vertices: [[f32; 3]; 4],
    pub uvs: [[f32; 2]; 4],
    pub viewport_width: u32,
    pub viewport_height: u32,
    pub source_program: u32,
    pub source_uv_space: u32,
    pub source_color_argb: u32,
    pub packed_light: u32,
    /// Optional per-vertex modulation for dynamic world primitives. Ordinary
    /// material quads retain a compact uniform value in every lane; producers
    /// such as a leash can preserve vanilla's endpoint light interpolation
    /// without introducing a producer-specific command family.
    pub vertex_color_argb: [u32; 4],
    pub vertex_packed_light: [u32; 4],
    pub block_entity_id: i32,
}

