/// The exact CPU vertex semantics that a source-pack route may need after the
/// ordinary mesh has been packed for its own Rust-owned GPU ABI.  This is
/// deliberately narrower than `WorldMeshAsset`: indices, sections, and the
/// entity identity already have one authoritative retained copy in
/// `MeshAssetStore` and must not be cloned again for deferred source lowering.
#[derive(Clone, Copy, Debug)]
struct SourceEntitySemanticVertex {
    position: [f32; 3],
    uv: [f32; 2],
    color_argb: u32,
    normal_packed: u32,
    light: u32,
}

#[derive(Clone, Debug)]
enum SourceMeshSemanticInput {
    Terrain(Vec<WorldMeshVertex>),
    Entity(Vec<SourceEntitySemanticVertex>),
}

trait NormalSourceVertex: Copy {
    fn position(self) -> [f32; 3];
    fn normal_packed(self) -> u32;
}

trait TerrainSourceVertex: NormalSourceVertex {
    fn uv(self) -> [f32; 2];
    fn shader_atlas_uv(self) -> [f32; 2];
    fn shader_block_id(self) -> i32;
    fn shader_material_type(self) -> i32;
    fn mid_block_packed(self) -> u32;
    fn color_argb(self) -> u32;
    fn light(self) -> u32;
}

impl NormalSourceVertex for WorldMeshVertex {
    fn position(self) -> [f32; 3] {
        self.position
    }
    fn normal_packed(self) -> u32 {
        self.normal_packed
    }
}

impl TerrainSourceVertex for WorldMeshVertex {
    fn uv(self) -> [f32; 2] {
        self.uv
    }
    fn shader_atlas_uv(self) -> [f32; 2] {
        self.shader_atlas_uv
    }
    fn shader_block_id(self) -> i32 {
        self.shader_block_id
    }
    fn shader_material_type(self) -> i32 {
        self.shader_material_type
    }
    fn mid_block_packed(self) -> u32 {
        self.mid_block_packed
    }
    fn color_argb(self) -> u32 {
        self.color_argb
    }
    fn light(self) -> u32 {
        self.light
    }
}

trait EntitySourceVertex: NormalSourceVertex {
    fn uv(self) -> [f32; 2];
    fn color_argb(self) -> u32;
    fn light(self) -> u32;
}

impl EntitySourceVertex for WorldMeshVertex {
    fn uv(self) -> [f32; 2] {
        self.uv
    }
    fn color_argb(self) -> u32 {
        self.color_argb
    }
    fn light(self) -> u32 {
        self.light
    }
}

impl NormalSourceVertex for SourceEntitySemanticVertex {
    fn position(self) -> [f32; 3] {
        self.position
    }
    fn normal_packed(self) -> u32 {
        self.normal_packed
    }
}

impl EntitySourceVertex for SourceEntitySemanticVertex {
    fn uv(self) -> [f32; 2] {
        self.uv
    }
    fn color_argb(self) -> u32 {
        self.color_argb
    }
    fn light(self) -> u32 {
        self.light
    }
}

/// Borrowed complete source-lowering view assembled from the one authoritative
/// mesh metadata copy plus the semantic sidecar above.  It has no Java or Iris
/// ownership and creates no transient duplicate of an asset while a selected
/// Rust source pass is being prepared.
struct SourceMeshAssetView<'a, V> {
    mesh_key: u64,
    mesh_generation: u64,
    vertices: &'a [V],
    index_bytes: &'a [u8],
    index_type: IndexType,
    sections: &'a [WorldMeshSection],
    entity_identity: &'a str,
}

#[cfg(test)]
impl WorldMeshAsset {
    fn source_terrain_view(&self) -> SourceMeshAssetView<'_, WorldMeshVertex> {
        SourceMeshAssetView {
            mesh_key: self.mesh_key,
            mesh_generation: self.mesh_generation,
            vertices: &self.vertices,
            index_bytes: &self.index_bytes,
            index_type: self.index_type,
            sections: &self.sections,
            entity_identity: &self.entity_identity,
        }
    }

    fn source_entity_view(&self) -> SourceMeshAssetView<'_, WorldMeshVertex> {
        self.source_terrain_view()
    }
}

/// Stable semantic layout decoded from Distant Horizons' CPU LOD builder.
/// This is intentionally separate from `WorldMeshVertex`: DH has vertex
/// color/material/light semantics but no Minecraft atlas UV ownership.
pub const WORLD_LOD_VERTEX_LAYOUT_V1: u32 = 1;
pub const WORLD_LOD_MAX_SEGMENTS_PER_COLUMN: usize = 512;
/// Maximum retained DH columns in one Rust-owned semantic generation. This
/// matches the Java collector's residency contract and bounds all derived LOD
/// CPU/GPU maps before packing or upload work begins.
pub const WORLD_LOD_MAX_COLUMNS: usize = 512;
/// Maximum visible DH segment instances retained in one semantic frame.
pub const WORLD_LOD_MAX_VISIBLE_SEGMENTS: usize = 16_384;
/// Maximum derived DH voxel source meshes retained across frames. The cache
/// is CPU semantic geometry (not a GPU handle registry); when full it is
/// rebuilt from the bounded column/segment inputs rather than growing without
/// limit.
pub const WORLD_LOD_MAX_SOURCE_MESH_CACHE: usize = 16_384;
pub const WORLD_LOD_MAX_VERTICES_PER_SEGMENT: usize = 2_097_152;
pub const WORLD_LOD_MAX_MATERIAL_IDENTITIES_PER_COLUMN: usize = 4_096;
pub const WORLD_LOD_MATERIAL_UNAVAILABLE: u32 = 0;
pub const WORLD_LOD_MATERIAL_MIXED: u32 = u32::MAX;
pub const WORLD_LOD_VARIANT_UNAVAILABLE: u8 = 0;
pub const WORLD_LOD_VARIANT_EXACT: u8 = 1;
pub const WORLD_LOD_VARIANT_MIXED: u8 = 2;
/// Distant Horizons' public semantic block-material table currently spans
/// `UNKNOWN` through `ILLUMINATED` inclusive. This is a material category,
/// never a texture or backend resource identifier.
pub const WORLD_LOD_MAX_MATERIAL_ID: u8 = 15;
pub const WORLD_LOD_MAX_NORMAL_INDEX: u8 = 5;

pub const WORLD_LOD_LAYER_OPAQUE: u32 = 1;
pub const WORLD_LOD_LAYER_TRANSPARENT_SIDE: u32 = 2;
pub const WORLD_LOD_LAYER_TRANSPARENT_UP: u32 = 3;
pub const WORLD_LOD_LAYER_TRANSPARENT_WATER_UP: u32 = 4;
/// The Java-side DH preflight selected this exact non-water frame for the Rust
/// whole-frame route. Capture-only LOD semantics deliberately leave this clear,
/// so observing Java/DH geometry cannot accidentally create a second renderer.
pub const WORLD_LOD_FLAG_RUST_ROUTE_SELECTED: u32 = 1 << 4;
/// Compatibility name for existing semantic transport users. The bit and ABI
/// are unchanged; it now admits opaque plus explicitly ordered non-water
/// transparent DH work.
pub const WORLD_LOD_FLAG_RUST_OPAQUE_ROUTE_SELECTED: u32 = WORLD_LOD_FLAG_RUST_ROUTE_SELECTED;

/// One backend-neutral DH LOD vertex. Positions are unsigned column-local
/// coordinates. `packed_light_and_micro_offset` retains the producer's
/// semantic bit fields without treating them as an OpenGL attribute format.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WorldLodVertex {
    pub local_position: [u16; 3],
    pub packed_light_and_micro_offset: u16,
    pub color_rgba: [u8; 4],
    pub material_id: u8,
    pub normal_index: u8,
}

