/// The fixed source vertex record is shared only by writers that agree on
/// every semantic lane. Shader program selection is deliberately absent:
/// it affects pipeline and descriptor state, never immutable geometry bytes.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
enum SourceGeometryAbi {
    Terrain,
    LocalTextured,
}

/// Stable binding identity for a program's frame-varying set-zero resources.
/// Keep it separate from `geometry`: the same terrain bytes can be consumed
/// by multiple source programs, while their descriptor layouts cannot.
#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredSourceTerrainFrameDataKey {
    geometry: LoweredSourceTerrainDataKey,
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    stream_buffer: Handle,
    instance_bytes: u64,
}

/// Stable frontend key for set-one semantic source resources. The signature
/// contains role/generation pairs rather than GAL handles so resource
/// replacement cannot accidentally retain stale bindings.
#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredSourceTerrainPackKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    world_generation: u64,
    resource_generations: Vec<(TerrainSourceResourceRole, u64)>,
}

/// Source-material set-one bindings need one extra semantic discriminator:
/// a local texture can replace the selected program's base-color sampler for
/// its own ordered batch while terrain continues to use the copied atlas.
/// The discriminator contains stable material identity/generation facts, not
/// a GAL or native texture handle.
#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredTexturedMaterialSourcePackKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    world_generation: u64,
    resource_generations: Vec<(TerrainSourceResourceRole, u64)>,
    local_texture: Option<(u32, u64)>,
}

/// Set-one identity for the separate `gbuffers_entities` contract. Entity
/// local material is explicit because it is not interchangeable with the
/// terrain atlas role, even when the underlying decoded bytes happen to be
/// identical.
#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredEntitySourcePackKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    world_generation: u64,
    resource_generations: Vec<(TerrainSourceResourceRole, u64)>,
    local_texture: (u32, u64),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredTexturedMaterialSourceLocalTextureKey {
    shader_pack_generation: u64,
    world_generation: u64,
    texture_id: u32,
    texture_generation: u64,
}

struct LoweredTexturedMaterialSourceLocalTextureResources {
    combined_sampler: Handle,
}

#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredSourceTerrainProgramKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
}

#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredSourceTerrainPipelineKey {
    program: LoweredSourceTerrainProgramKey,
    material_mode: u32,
    cull_policy: u32,
    winding: u32,
    /// Source fragment output locations are part of pipeline compatibility.
    /// Keeping their exact formats in the key prevents an earlier private
    /// fixture target from being reused for a later source-derived target
    /// with a different semantic output schema.
    color_formats: Vec<TextureFormat>,
}

/// Private set-zero identity for a compact source-material payload. The
/// stream buffer is completion-gated by frame ownership; payload bytes vary
/// only through dynamic offsets and never become a native/backend identity.
#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredTexturedMaterialSourceFrameDataKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    stream_buffer: Handle,
    vertex_bytes: u64,
}

#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredTexturedMaterialSourcePipelineKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    material_mode: u32,
    depth_policy: u32,
    cull_policy: u32,
    winding: u32,
    color_formats: Vec<TextureFormat>,
}

#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
struct LoweredEntitySourcePipelineKey {
    shader_program_identity: ProgramIdentity,
    shader_pack_generation: u64,
    material_mode: u32,
    depth_policy: u32,
    cull_policy: u32,
    winding: u32,
    /// The hand adapter uses D24S8 for optical stencil roles while ordinary
    /// entities use D32.  Keep the attachment format in the identity: Vulkan
    /// pipeline compatibility includes the depth/stencil attachment format,
    /// so sharing only shader/material state can bind an invalid pipeline.
    depth_format: TextureFormat,
    color_formats: Vec<TextureFormat>,
}

struct MeshAssetStore {
    translucent_order: std::cell::RefCell<Option<translucent_order::CachedOrder>>,
    mesh_generation: u64,
    index_generation: u64,
    vertex_layout_version: u32,
    vertex_bytes: Vec<u8>,
    /// Immutable copied source input retained until an admitted source frame
    /// actually selects this exact mesh generation. World streaming can add
    /// hundreds of off-screen sections in one update; eagerly expanding each
    /// into the shader-pack ABI turns ordinary asset registration into source
    /// rendering work on the render thread.
    source_input: Option<SourceMeshSemanticInput>,
    /// Canonical entity identity stored once alongside the ordinary mesh
    /// metadata. Source entity lowering borrows it through `source_view`;
    /// retaining it inside a second cloned asset used to duplicate both this
    /// string and the complete index/section payload.
    entity_identity: String,
    terrain_voxel_vertices: Option<Arc<Vec<TerrainVoxelSourceVertex>>>,
    terrain_voxel_indices: Option<Arc<Vec<u32>>>,
    index_bytes: Vec<u8>,
    index_type: IndexType,
    sections: Vec<WorldMeshSection>,
}

#[cfg(test)]
impl Default for MeshAssetStore {
    fn default() -> Self {
        Self {
            translucent_order: Default::default(),
            mesh_generation: 0,
            index_generation: 0,
            vertex_layout_version: 0,
            vertex_bytes: Vec::new(),
            source_input: None,
            entity_identity: String::new(),
            terrain_voxel_vertices: None,
            terrain_voxel_indices: None,
            index_bytes: Vec::new(),
            index_type: IndexType::U16,
            sections: Vec::new(),
        }
    }
}

impl MeshAssetStore {
    fn source_terrain_view(
        &self,
        mesh_key: u64,
    ) -> Option<SourceMeshAssetView<'_, WorldMeshVertex>> {
        let SourceMeshSemanticInput::Terrain(vertices) = self.source_input.as_ref()? else {
            return None;
        };
        Some(SourceMeshAssetView {
            mesh_key,
            mesh_generation: self.mesh_generation,
            vertices,
            index_bytes: &self.index_bytes,
            index_type: self.index_type,
            sections: &self.sections,
            entity_identity: &self.entity_identity,
        })
    }

    fn source_entity_view(
        &self,
        mesh_key: u64,
    ) -> Option<SourceMeshAssetView<'_, SourceEntitySemanticVertex>> {
        let SourceMeshSemanticInput::Entity(vertices) = self.source_input.as_ref()? else {
            return None;
        };
        Some(SourceMeshAssetView {
            mesh_key,
            mesh_generation: self.mesh_generation,
            vertices,
            index_bytes: &self.index_bytes,
            index_type: self.index_type,
            sections: &self.sections,
            entity_identity: &self.entity_identity,
        })
    }
}

