    fn source_terrain_frame_upload_ops(
        &self,
        stream: SourceTerrainFrameStreamAllocation,
        prepared: &PreparedSourceTerrainFrame,
    ) -> Vec<CommandOp> {
        self.source_terrain_frame_upload_ops_for_parts(
            stream,
            prepared.legacy_texture_transforms.clone(),
            prepared.scalar_uniforms.clone(),
            prepared.instance_transforms.clone(),
        )
    }

    /// Serializes one owned frame-local source payload into the shared
    /// completion-gated stream. Terrain uses the final lane for instances;
    /// `gbuffers_textured` uses it for compact vertices. The transaction and
    /// barriers are intentionally identical, while the set-zero layouts keep
    /// the two source ABIs distinct.
    fn source_terrain_frame_upload_ops_for_parts(
        &self,
        stream: SourceTerrainFrameStreamAllocation,
        legacy_texture_transforms: Vec<u8>,
        scalar_uniforms: Vec<u8>,
        payload: Vec<u8>,
    ) -> Vec<CommandOp> {
        let mut operations = vec![CommandOp::Barrier(buffer_barrier(
            stream.buffer,
            TextureUsageState::ShaderRead,
            TextureUsageState::TransferDst,
        ))];
        let mut write_dynamic = |offset: u64, data: Vec<u8>| {
            operations.push(CommandOp::HostWriteBuffer {
                buffer: stream.buffer,
                offset,
                data,
            });
        };
        write_dynamic(stream.legacy_transform_offset, legacy_texture_transforms);
        if let Some(offset) = stream.scalar_uniform_offset {
            write_dynamic(offset, scalar_uniforms);
        }
        write_dynamic(stream.instance_offset, payload);
        operations.push(CommandOp::Barrier(buffer_barrier(
            stream.buffer,
            TextureUsageState::TransferDst,
            TextureUsageState::ShaderRead,
        )));
        operations
    }

    /// Transfers a prepared source frame's uploads to its single combined
    /// submission. This remains private until selected-source execution is
    /// admitted, but its lifetime is now identical to the production path.
    fn take_source_terrain_frame_transaction(
        &mut self,
        frame_id: u64,
    ) -> GalResult<SourceTerrainFrameTransaction> {
        self.pending_source_terrain_frame_transactions
            .remove(&frame_id)
            .ok_or_else(|| {
                GalError::invalid_argument("source terrain frame has no pending upload transaction")
            })
    }

    /// Aborts private source-frame preparation before it reaches a GAL
    /// submission. Persistent geometry stays cached by generation, while the
    /// mutable frame data and its unsubmitted stream reservation are released
    /// so a malformed source frame cannot starve later valid frames.
    fn discard_source_terrain_frame_transaction(&mut self, gal: &mut VulkanicGal, frame_id: u64) {
        let mut source_material_texture_ids = self
            .pending_source_material_texture_uploads
            .remove(&frame_id)
            .unwrap_or_default()
            .into_iter()
            .map(|pending| pending.texture_id)
            .collect::<BTreeSet<_>>();
        if let Some(transaction) = self
            .pending_source_terrain_frame_transactions
            .remove(&frame_id)
        {
            source_material_texture_ids.extend(transaction.source_material_texture_ids);
        }
        self.discard_unsubmitted_source_material_textures(gal, &source_material_texture_ids);
        if let Some(slot) = self
            .source_terrain_frame_stream_slots
            .iter_mut()
            .find(|slot| slot.frame_id == Some(frame_id) && slot.submission.is_none())
        {
            slot.frame_id = None;
            slot.cursor = 0;
        }
    }

    /// Moves local-material uploads requested by source fullscreen consumers
    /// (for example source-defined celestial writers) into the already opened
    /// exact-frame transaction. These consumers do not own a separate submit;
    /// their copied texture payloads must precede their draws in the same
    /// source submission just like entity and hand material uploads.
    fn absorb_pending_source_material_texture_uploads(&mut self, frame_id: u64) -> GalResult<()> {
        let pending = self
            .pending_source_material_texture_uploads
            .remove(&frame_id)
            .unwrap_or_default();
        if pending.is_empty() {
            return Ok(());
        }
        let transaction = self
            .pending_source_terrain_frame_transactions
            .get_mut(&frame_id)
            .ok_or_else(|| {
                GalError::backend(
                    "source local-material upload has no exact-frame source transaction",
                )
            })?;
        for upload in pending {
            transaction
                .source_material_texture_ids
                .insert(upload.texture_id);
            transaction.operations.extend(upload.operations);
        }
        Ok(())
    }

    fn discard_unsubmitted_source_material_textures(
        &mut self,
        gal: &mut VulkanicGal,
        texture_ids: &BTreeSet<u32>,
    ) {
        if texture_ids.is_empty() {
            return;
        }
        let pack_keys = self
            .lowered_textured_material_source_pack_resources
            .keys()
            .filter(|key| {
                key.local_texture
                    .is_some_and(|(texture_id, _)| texture_ids.contains(&texture_id))
            })
            .cloned()
            .collect::<Vec<_>>();
        self.destroy_lowered_textured_material_source_pack_resources_for_keys(gal, pack_keys);
        let entity_pack_keys = self
            .lowered_entity_source_pack_resources
            .keys()
            .filter(|key| texture_ids.contains(&key.local_texture.0))
            .cloned()
            .collect::<Vec<_>>();
        self.destroy_lowered_entity_source_pack_resources_for_keys(gal, entity_pack_keys);
        let binding_keys = self
            .lowered_textured_material_source_local_texture_resources
            .keys()
            .filter(|key| texture_ids.contains(&key.texture_id))
            .cloned()
            .collect::<Vec<_>>();
        for key in binding_keys {
            if let Some(resources) = self
                .lowered_textured_material_source_local_texture_resources
                .remove(&key)
            {
                let _ = gal.destroy(resources.combined_sampler);
            }
        }
        for texture_id in texture_ids {
            self.source_material_texture_resident.remove(texture_id);
            self.source_material_texture_upload_confirmed
                .remove(texture_id);
            self.source_material_texture_staged.remove(texture_id);
            self.source_material_texture_upload_operations
                .remove(texture_id);
            if let Some(resources) = self.source_material_texture_resources.remove(texture_id) {
                for handle in resources.handles_in_destroy_order() {
                    let _ = gal.destroy(handle);
                }
            }
        }
    }

    fn discard_pending_lowered_source_terrain_submission(&mut self, gal: &mut VulkanicGal) {
        if let Some(submission) = self.pending_lowered_source_terrain_submission.take() {
            self.discard_source_terrain_frame_submission(gal, submission);
        }
    }

    /// Cancels all private source-frame work that has not reached the owning
    /// combined submission. Asset generations are atomic: no staged upload or
    /// resource binding may survive into a newer material generation.
    fn discard_all_unsubmitted_source_terrain_frames(&mut self, gal: &mut VulkanicGal) {
        self.discard_pending_lowered_source_terrain_submission(gal);
        let mut frame_ids = self
            .pending_source_terrain_frame_transactions
            .keys()
            .copied()
            .collect::<BTreeSet<_>>();
        frame_ids.extend(self.pending_source_material_texture_uploads.keys().copied());
        for frame_id in frame_ids {
            self.discard_source_terrain_frame_transaction(gal, frame_id);
        }
    }

    /// Returns whether the discovered source contract declares either
    /// temporal main-depth role and Rust has explicitly opted into preparing
    /// the source contract. Preparation is distinct from route selection:
    /// the ordinary Rust graph continues to execute until a later frame has
    /// confirmed every named source resource and armed the complete plan.
    fn source_main_depth_history_required(&self) -> bool {
        self.runtime_source_execution_requested()
            && self.shader_runtime.as_ref().is_some_and(|runtime| {
                runtime.candidate_source_requires_resource(
                    TerrainSourceResourceRole::MainDepthBeforeTranslucency,
                ) || runtime.candidate_source_requires_resource(
                    TerrainSourceResourceRole::MainDepthPrevious,
                )
            })
    }

    /// Prepares the depth-history copy contract for one exact graph/frame.
    /// This has no persistent effect until `confirm_g_buffer_depth_history`
    /// receives the submission token from `submit_whole_frame`.
    fn prepare_g_buffer_depth_history_submission(
        &self,
        frame_id: u64,
        resources: &GBufferResources,
    ) -> GalResult<Option<(TerrainDepthHistoryPlan, GBufferDepthHistorySubmission)>> {
        if !self.source_main_depth_history_required() {
            return Ok(None);
        }
        if self.pending_g_buffer_depth_history_submission.is_some() {
            return Err(GalError::backend(
                "main depth history submission is awaiting combined-frame confirmation",
            ));
        }
        let history = if self.g_buffer_depth_history.graph_generation == resources.generation {
            self.g_buffer_depth_history
        } else {
            GBufferDepthHistoryState::default()
        };
        Ok(Some((
            TerrainDepthHistoryPlan {
                prior_before_translucency_valid: history.before_translucency_valid,
                prior_previous_valid: history.previous_valid,
                extent: resources.extent,
            },
            GBufferDepthHistorySubmission {
                frame_id,
                graph_generation: resources.generation,
                prior_before_translucency_valid: history.before_translucency_valid,
            },
        )))
    }

    fn discard_pending_g_buffer_depth_history_submission(&mut self) {
        self.pending_g_buffer_depth_history_submission = None;
    }

    fn confirm_g_buffer_depth_history_submission(
        &mut self,
        submission: GBufferDepthHistorySubmission,
        gal_submission: SubmissionId,
        active_graph_generation: u64,
    ) -> GalResult<()> {
        if active_graph_generation != submission.graph_generation {
            return Err(GalError::backend(
                "main depth history graph generation changed before submission confirmation",
            ));
        }
        self.g_buffer_depth_history = GBufferDepthHistoryState {
            graph_generation: submission.graph_generation,
            before_translucency_valid: true,
            previous_valid: submission.prior_before_translucency_valid,
            last_frame_id: Some(submission.frame_id),
            last_submission: Some(gal_submission),
        };
        Ok(())
    }

    fn confirm_source_terrain_frame_transaction(
        &mut self,
        transaction: &SourceTerrainFrameSubmission,
        submission: SubmissionId,
    ) -> GalResult<()> {
        self.mark_source_terrain_frame_stream_submitted(
            transaction.frame_id,
            transaction.stream_buffer,
            transaction.stream_epoch,
            submission,
        )?;
        self.source_material_texture_resident.extend(
            transaction
                .uploaded_source_material_texture_ids
                .iter()
                .copied(),
        );
        self.source_material_texture_upload_confirmed.extend(
            transaction
                .uploaded_source_material_texture_ids
                .iter()
                .copied(),
        );
        for texture_id in &transaction.uploaded_source_material_texture_ids {
            self.source_material_texture_staged.remove(texture_id);
            self.source_material_texture_upload_operations
                .remove(texture_id);
        }
        Ok(())
    }

    fn discard_source_terrain_frame_submission(
        &mut self,
        gal: &mut VulkanicGal,
        submission: SourceTerrainFrameSubmission,
    ) {
        self.discard_unsubmitted_source_material_textures(
            gal,
            &submission.source_material_texture_ids,
        );
        self.discard_source_terrain_frame_transaction(gal, submission.frame_id);
    }

    /// Materializes the lowered source program's set-one semantic sampler and
    /// storage-image bindings. The owned resource table already proves each
    /// role's shape and generation; this method only turns that backend-neutral
    /// declaration into an explicit GAL layout/set. It cannot select a
    /// pipeline or issue a draw.
    fn ensure_lowered_source_terrain_pack_resources(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        resources: &TerrainSourceOwnedResourceSet,
    ) -> GalResult<LoweredSourceTerrainPackKey> {
        program.require_semantic_resources(resources.availability())?;
        let key = LoweredSourceTerrainPackKey {
            shader_program_identity: program.identity.clone(),
            shader_pack_generation: program.shader_pack_generation,
            world_generation: resources.availability().world_generation(),
            resource_generations: resources.generation_signature(),
        };
        if self
            .lowered_source_terrain_pack_resources
            .contains_key(&key)
        {
            return Ok(key);
        }
        let stale_keys = self
            .lowered_source_terrain_pack_resources
            .keys()
            .filter(|existing| {
                existing.shader_program_identity == key.shader_program_identity
                    && existing.shader_pack_generation == key.shader_pack_generation
                    && existing.world_generation == key.world_generation
                    && existing.resource_generations != key.resource_generations
            })
            .cloned()
            .collect::<Vec<_>>();
        self.destroy_lowered_source_terrain_pack_resources_for_keys(gal, stale_keys);
        if !lowered_source_pack_residency_allows(self.lowered_source_terrain_pack_resources.len()) {
            return Err(GalError::unsupported_feature(format!(
                "lowered terrain source pack residency limit reached (limit={})",
                LOWERED_SOURCE_PACK_RESIDENCY
            )));
        }

        let program_layouts = self.ensure_lowered_source_terrain_program_layouts(gal, program)?;
        let label = format!(
            "source-terrain-pack-{}-pack{}-world{}",
            program.identity.as_str(),
            key.shader_pack_generation,
            key.world_generation
        );
        let resource_set = match program.pack_resource_set_desc(
            format!("{label}.set-one"),
            program_layouts.pack_resources,
            resources,
        ) {
            Ok(desc) => match gal.create_resource_set(desc) {
                Ok(set) => set,
                Err(error) => return Err(error),
            },
            Err(error) => return Err(error),
        };
        self.lowered_source_terrain_pack_resources.insert(
            key.clone(),
            LoweredSourceTerrainPackResources { resource_set },
        );
        Ok(key)
    }

    /// Creates the two static layouts declared by a lowered source program
    /// exactly once per source generation. Individual mesh and resource-set
    /// caches reference these layouts but never own their lifetime.
    fn ensure_lowered_source_terrain_program_layouts(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
    ) -> GalResult<LoweredSourceTerrainProgramLayouts> {
        self.ensure_lowered_source_program_layouts(
            gal,
            program.identity.clone(),
            program.shader_pack_generation,
            program.execution_resource_layouts()?,
        )
    }

    fn ensure_lowered_local_source_program_layouts<P: LocalTexturedSourceProgram>(
        &mut self,
        gal: &mut VulkanicGal,
        program: &P,
    ) -> GalResult<LoweredSourceTerrainProgramLayouts> {
        self.ensure_lowered_source_program_layouts(
            gal,
            program.identity().clone(),
            program.shader_pack_generation(),
            program.execution_resource_layouts()?,
        )
    }

    /// Caches the two fixed source-stream layouts by semantic program
    /// identity. Entity and terrain source programs may share this ABI, but
    /// distinct source identities still receive distinct layouts and cannot
    /// alias set-one material semantics.
    fn ensure_lowered_source_program_layouts(
        &mut self,
        gal: &mut VulkanicGal,
        shader_program_identity: ProgramIdentity,
        shader_pack_generation: u64,
        layouts: TerrainSourceExecutionLayouts,
    ) -> GalResult<LoweredSourceTerrainProgramLayouts> {
        let key = LoweredSourceTerrainProgramKey {
            shader_program_identity,
            shader_pack_generation,
        };
        if let Some(layouts) = self
            .lowered_source_terrain_program_layouts
            .get(&key)
            .copied()
        {
            return Ok(layouts);
        }
        if !lowered_source_residency_allows(self.lowered_source_terrain_program_layouts.len()) {
            return Err(GalError::unsupported_feature(format!(
                "lowered source program-layout residency limit reached (limit={})",
                WORLD_MESH_PIPELINE_RESIDENCY
            )));
        }
        let source_data = gal.create_resource_layout(layouts.source_data)?;
        let pack_resources = match gal.create_resource_layout(layouts.pack_resources) {
            Ok(layout) => layout,
            Err(error) => {
                let _ = gal.destroy(source_data);
                return Err(error);
            }
        };
        let resources = LoweredSourceTerrainProgramLayouts {
            source_data,
            pack_resources,
        };
        self.lowered_source_terrain_program_layouts
            .insert(key, resources);
        Ok(resources)
    }

    /// Compiles and caches one private source-derived terrain pipeline from
    /// the owned lowered stages. It has no render-pass ownership or draw path
    /// yet; the purpose is to prove that source data and pack-resource layouts
    /// form a backend-neutral GAL pipeline without Java or Iris state.
    fn ensure_lowered_source_terrain_pipeline_resources(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
    ) -> GalResult<LoweredSourceTerrainPipelineKey> {
        self.ensure_lowered_source_terrain_pipeline_resources_for_outputs(
            gal,
            program,
            material_mode,
            cull_policy,
            winding,
            vec![TextureFormat::Rgba8Unorm; 4],
        )
    }

    fn ensure_lowered_source_shadow_pipeline_resources(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
    ) -> GalResult<LoweredSourceTerrainPipelineKey> {
        self.ensure_lowered_source_terrain_pipeline_resources_for_outputs(
            gal,
            program,
            material_mode,
            cull_policy,
            winding,
            vec![TextureFormat::Rgba8Unorm; 2],
        )
    }

    fn ensure_lowered_source_terrain_pipeline_resources_for_outputs(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
        color_formats: Vec<TextureFormat>,
    ) -> GalResult<LoweredSourceTerrainPipelineKey> {
        let (mut blend, mut depth_write) =
            source_terrain_pipeline_raster_state(program, material_mode)?;
        if matches!(
            std::env::var("MATTMC_RUST_SOURCE_DEPTH_TRACE").as_deref(),
            Ok("1") | Ok("true") | Ok("TRUE")
        ) {
            eprintln!(
                "[MattMC source-depth-trace] pipeline program={} material_mode={} vertex_label={} clip_finalizer={} depth_compare=LessOrEqual depth_write={} depth_format=Depth32Float color_formats={:?}",
                program.identity.as_str(),
                material_mode,
                program.vertex.label,
                program
                    .vertex
                    .source
                    .contains("gl_Position.z = (gl_Position.z + gl_Position.w) * 0.5"),
                depth_write,
                color_formats,
            );
        }
        if color_formats.is_empty() {
            return Err(GalError::invalid_argument(
                "lowered source terrain pipeline requires at least one explicit color output format",
            ));
        }
        let key = LoweredSourceTerrainPipelineKey {
            program: LoweredSourceTerrainProgramKey {
                shader_program_identity: program.identity.clone(),
                shader_pack_generation: program.shader_pack_generation,
            },
            material_mode,
            cull_policy,
            winding,
            color_formats: color_formats.clone(),
        };
        if self
            .lowered_source_terrain_pipeline_resources
            .contains_key(&key)
        {
            return Ok(key);
        }
        if !lowered_source_residency_allows(self.lowered_source_terrain_pipeline_resources.len()) {
            return Err(GalError::unsupported_feature(format!(
                "lowered source pipeline residency limit reached (limit={})",
                WORLD_MESH_PIPELINE_RESIDENCY
            )));
        }
        let layouts = self.ensure_lowered_source_terrain_program_layouts(gal, program)?;
        let label = format!(
            "source-terrain-pipeline-{}-mode{}-cull{}-winding{}",
            program.identity.as_str(),
            material_mode,
            cull_policy,
            winding
        );
        // This is a capture-only isolation aid for the owned source path. It
        // never changes normal routing or material semantics: each opt-in
        // process can prove whether an otherwise black source target is caused
        // by culling or by depth/clip rejection before a rendering change is
        // considered.
        let raster_probe = selected_source_raster_probe()?;
        let mut cull_mode = effective_cull_mode_for_winding(cull_policy, winding)?;
        let mut front_face = crate::render::vulkanic::resources::FrontFace::CounterClockwise;
        let mut depth_compare = Some(CompareOp::LessOrEqual);
        match raster_probe {
            SelectedSourceRasterProbe::None | SelectedSourceRasterProbe::InvertFrontFace => {}
            SelectedSourceRasterProbe::NoCull => cull_mode = CullMode::None,
            SelectedSourceRasterProbe::DepthDisabled => {
                depth_compare = None;
                depth_write = false;
            }
            SelectedSourceRasterProbe::BlendDisabled => blend = BlendMode::Disabled,
        }
        front_face = selected_source_raster_probe_front_face(front_face)?;
        let mut created = Vec::new();
        let result = (|| -> GalResult<LoweredSourceTerrainPipelineResources> {
            let [vertex_desc, fragment_desc] =
                program.shader_module_descriptors(gal.capabilities().api);
            let vertex_shader = gal.create_shader_module(vertex_desc)?;
            created.push(vertex_shader);
            let fragment_shader = gal.create_shader_module(fragment_desc)?;
            created.push(fragment_shader);
            let pipeline_layout = gal.create_pipeline_layout(PipelineLayoutDesc {
                label: format!("{label}.layout"),
                resource_layouts: vec![layouts.source_data, layouts.pack_resources],
            })?;
            created.push(pipeline_layout);
            let pipeline = gal.create_graphics_pipeline(GraphicsPipelineDesc {
                label: format!("{label}.pipeline"),
                layout: pipeline_layout,
                vertex_shader,
                fragment_shader,
                topology: PrimitiveTopology::Triangles,
                cull_mode,
                front_face,
                blend,
                depth_compare,
                depth_write,
                depth_bias: None,
                color_formats,
                depth_format: Some(TextureFormat::Depth32Float),
                stencil: None,
            })?;
            created.push(pipeline);
            Ok(LoweredSourceTerrainPipelineResources {
                vertex_shader,
                fragment_shader,
                pipeline_layout,
                pipeline,
            })
        })();
        if result.is_err() {
            for handle in created.into_iter().rev() {
                let _ = gal.destroy(handle);
            }
        }
        self.lowered_source_terrain_pipeline_resources
            .insert(key.clone(), result?);
        Ok(key)
    }

    /// Assembles explicit runtime draw records from a fully lowered source
    /// program and Rust-owned semantic resources. This is deliberately only
    /// draw preparation: it neither selects a source route nor records a
    /// render pass. A future admitted source terrain executor can hand these
    /// records to the existing Rust-owned terrain graph without borrowing
    /// Java, Iris, or backend state.
    fn prepare_lowered_source_terrain_draws(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        prepared: &PreparedSourceTerrainFrame,
        pack_resources: &TerrainSourceOwnedResourceSet,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
    ) -> GalResult<Vec<TerrainMeshDraw>> {
        self.prepare_lowered_source_terrain_draws_for_color_formats(
            gal,
            program,
            prepared,
            pack_resources,
            material_mode,
            cull_policy,
            winding,
            vec![TextureFormat::Rgba8Unorm; 4],
        )
    }

    /// Assembles source terrain draws for an already resolved named source
    /// output schema. The compact format vector follows named output order,
    /// never a legacy draw-buffer slot, and is part of the pipeline cache
    /// key so incompatible source targets cannot share a pipeline.
    fn prepare_lowered_source_terrain_draws_for_color_formats(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        prepared: &PreparedSourceTerrainFrame,
        pack_resources: &TerrainSourceOwnedResourceSet,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
        color_formats: Vec<TextureFormat>,
    ) -> GalResult<Vec<TerrainMeshDraw>> {
        self.ensure_source_mesh_generation(
            "terrain",
            prepared.mesh.mesh_key,
            prepared.mesh.mesh_generation,
        )?;
        // Validate material/pass compatibility before allocating any stream
        // resources. Translucency is admitted only when its distinct source
        // program carried explicit raster semantics; it cannot inherit the
        // opaque terrain pipeline's disabled blend/depth-write state.
        let _ = source_terrain_pipeline_raster_state(program, material_mode)?;
        if prepared.instance_transforms.len() % TERRAIN_SOURCE_INSTANCE_BYTES != 0 {
            return Err(GalError::invalid_argument(
                "source terrain instance payload does not contain whole records",
            ));
        }
        let instance_count = prepared.instance_transforms.len() / TERRAIN_SOURCE_INSTANCE_BYTES;
        let instance_count = u32::try_from(instance_count)
            .map_err(|_| GalError::invalid_argument("source terrain instance count exceeds u32"))?;
        if instance_count == 0 {
            return Err(GalError::invalid_argument(
                "source terrain draw preparation requires at least one instance",
            ));
        }

        let (geometry_key, frame_data_key, stream) =
            self.ensure_lowered_source_terrain_data_resources(gal, program, prepared)?;
        let pack_key =
            self.ensure_lowered_source_terrain_pack_resources(gal, program, pack_resources)?;
        let pipeline_key = self.ensure_lowered_source_terrain_pipeline_resources_for_outputs(
            gal,
            program,
            material_mode,
            cull_policy,
            winding,
            color_formats,
        )?;
        let index_buffer = self
            .lowered_source_terrain_geometry_resources
            .get(&geometry_key)
            .map(|resources| resources.index_buffer)
            .ok_or_else(|| GalError::backend("source terrain geometry resources vanished"))?;
        let resource_set = self
            .lowered_source_terrain_frame_data_resources
            .get(&frame_data_key)
            .map(|resources| resources.resource_set)
            .ok_or_else(|| GalError::backend("source terrain frame data resources vanished"))?;
        let pack_resource_set = self
            .lowered_source_terrain_pack_resources
            .get(&pack_key)
            .map(|resources| resources.resource_set)
            .ok_or_else(|| GalError::backend("source terrain pack resources vanished"))?;
        let (pipeline, pipeline_layout) = self
            .lowered_source_terrain_pipeline_resources
            .get(&pipeline_key)
            .map(|resources| (resources.pipeline, resources.pipeline_layout))
            .ok_or_else(|| GalError::backend("source terrain pipeline resources vanished"))?;
        let material_mode = terrain_material_pass_mode(material_mode)?;

        prepared
            .section_indices
            .iter()
            .map(|&section_index| {
                let section = prepared
                    .mesh
                    .sections
                    .get(section_index as usize)
                    .expect("validated source terrain section selection");
                Ok(TerrainMeshDraw {
                    shadow: None,
                    pipeline,
                    pipeline_layout,
                    resource_set,
                    resource_set_dynamic_offsets: {
                        let mut offsets = vec![stream.legacy_transform_offset];
                        if let Some(offset) = stream.scalar_uniform_offset {
                            offsets.push(offset);
                        }
                        offsets.push(stream.instance_offset);
                        offsets
                    },
                    shader_resource_set: Some(TerrainShaderResourceSet {
                        set_index: 1,
                        set: pack_resource_set,
                    }),
                    index_buffer,
                    index_offset: section.index_offset,
                    index_type: IndexType::U32,
                    index_count: section.index_count,
                    instance_count,
                    // This draw is the source-derived replacement for the
                    // vanilla terrain section.  Keep its semantic stratum as
                    // terrain so the explicit pass graph writes the main
                    // terrain attachment rather than Fabulous's item/entity
                    // attachment (the latter is reserved for entity meshes).
                    stratum: WORLD_STRATUM_TERRAIN,
                    material_mode,
                    shadow_participation: TerrainShadowParticipation::Required,
                })
            })
            .collect()
    }

    /// Assembles source-derived shadow bindings for the same copied mesh
    /// sections as an already prepared terrain frame. The shadow program owns
    /// its scalar uniforms and set-one resources; only the semantic mesh
    /// selection and Rust frame transaction are shared with terrain.
    fn prepare_lowered_source_shadow_draws(
        &mut self,
        gal: &mut VulkanicGal,
        program: &LoweredTerrainSourceProgram,
        prepared: &PreparedSourceTerrainFrame,
        pack_resources: &TerrainSourceOwnedResourceSet,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
    ) -> GalResult<Vec<TerrainShadowDraw>> {
        let (geometry_key, frame_data_key, stream) =
            self.ensure_lowered_source_terrain_data_resources(gal, program, prepared)?;
        let pack_key =
            self.ensure_lowered_source_terrain_pack_resources(gal, program, pack_resources)?;
        let pipeline_key = self.ensure_lowered_source_shadow_pipeline_resources(
            gal,
            program,
            material_mode,
            cull_policy,
            winding,
        )?;
        let resource_set = self
            .lowered_source_terrain_frame_data_resources
            .get(&frame_data_key)
            .map(|resources| resources.resource_set)
            .ok_or_else(|| GalError::backend("source shadow frame data resources vanished"))?;
        let pack_resource_set = self
            .lowered_source_terrain_pack_resources
            .get(&pack_key)
            .map(|resources| resources.resource_set)
            .ok_or_else(|| GalError::backend("source shadow pack resources vanished"))?;
        let (pipeline, pipeline_layout) = self
            .lowered_source_terrain_pipeline_resources
            .get(&pipeline_key)
            .map(|resources| (resources.pipeline, resources.pipeline_layout))
            .ok_or_else(|| GalError::backend("source shadow pipeline resources vanished"))?;
        let instance_count =
            u32::try_from(prepared.instance_transforms.len() / TERRAIN_SOURCE_INSTANCE_BYTES)
                .map_err(|_| {
                    GalError::invalid_argument("source shadow instance count exceeds u32")
                })?;
        if instance_count == 0 {
            return Err(GalError::invalid_argument(
                "source shadow draw preparation requires at least one instance",
            ));
        }
        let _ = geometry_key;
        let dynamic_offsets = {
            let mut offsets = vec![stream.legacy_transform_offset];
            if let Some(offset) = stream.scalar_uniform_offset {
                offsets.push(offset);
            }
            offsets.push(stream.instance_offset);
            offsets
        };
        Ok(prepared
            .section_indices
            .iter()
            .map(|_| TerrainShadowDraw {
                pipeline,
                pipeline_layout,
                resource_set,
                resource_set_dynamic_offsets: dynamic_offsets.clone(),
                shader_resource_set: Some(TerrainShaderResourceSet {
                    set_index: 1,
                    set: pack_resource_set,
                }),
            })
            .collect())
    }

    /// Prepares source-derived terrain draws only from the complete semantic
    /// resource snapshot recorded for this exact frame. Keeping the lookup
    /// here makes a future source executor prove pack, world, frame, and
    /// program identity before it can create a pipeline or resource set.
    /// This remains CPU/GAL preparation only and does not select a route,
    /// record a pass, or borrow Java/Iris state.
    fn prepare_lowered_source_terrain_draws_for_snapshot(
        &mut self,
        gal: &mut VulkanicGal,
        world_generation: u64,
        program: &LoweredTerrainSourceProgram,
        prepared: &PreparedSourceTerrainFrame,
        material_mode: u32,
        cull_policy: u32,
        winding: u32,
    ) -> GalResult<Vec<TerrainMeshDraw>> {
        let pack_resources = self
            .candidate_source_resources_for_program(
                program.shader_pack_generation,
                world_generation,
                prepared.frame_id,
                program,
            )?
            .clone();
        self.prepare_lowered_source_terrain_draws(
            gal,
            program,
            prepared,
            &pack_resources,
            material_mode,
            cull_policy,
            winding,
        )
    }

    /// Converts already-admitted ordinary terrain batch semantics into the
    /// fixed source-derived mesh ABI. The caller supplies no renderer state:
    /// section ranges, transforms, material mode, culling, and ordering all
    /// originate from the shared Rust frontend batch. This is still private
    /// preparation, not source-route selection or pass recording.
    fn prepare_lowered_source_terrain_draws_for_mesh_batches(
        &mut self,
        gal: &mut VulkanicGal,
        programs: &LoweredSourceTerrainPrograms,
        world_generation: u64,
        frame: &WorldPrimitiveFrame,
        batches: &[MeshBatch],
    ) -> GalResult<Vec<TerrainMeshDraw>> {
        if world_generation == 0 {
            return Err(GalError::invalid_argument(
                "lowered source terrain preparation requires a non-zero world generation",
            ));
        }
        let shader_pack_generation = programs.shader_pack_generation()?;
        // Validate the independently complete terrain program before
        // spending work on private source-stream state. Whole-frame route
        // selection separately requires every retained DH/fullscreen stage.
        self.candidate_source_resources_for_program(
            shader_pack_generation,
            world_generation,
            frame.frame_id,
            &programs.opaque,
        )?;
        self.candidate_source_resources_for_program(
            shader_pack_generation,
            world_generation,
            frame.frame_id,
            &programs.cutout,
        )?;
        self.candidate_source_resources_for_program(
            shader_pack_generation,
            world_generation,
            frame.frame_id,
            &programs.shadow,
        )?;
        let base_uniform_frame = self.source_uniform_frame_for_owned_resources(frame)?;
        let texture_transforms = TerrainSourceTextureTransforms::canonical_minecraft_terrain();
        let mut draws = Vec::new();
        let mut transform_probes = Vec::new();
        for batch in batches {
            if !is_source_terrain_mesh_stratum(batch.key.stratum) {
                return Err(GalError::unsupported_feature(format!(
                    "lowered source terrain preparation rejects unsupported mesh stratum {} for mesh {}",
                    batch.key.stratum, batch.key.mesh_key
                )));
            }
            if !batch.key.g_buffer {
                return Err(GalError::invalid_argument(
                    "lowered source terrain preparation requires G-buffer mesh batches",
                ));
            }
            let program = programs.for_material_mode(batch.key.material_mode)?;
            let mut uniform_frame = base_uniform_frame.clone();
            uniform_frame.render_stage =
                Some(self.source_render_stage_for_material_mode(batch.key.material_mode)?);
            let mut shadow_uniform_frame = base_uniform_frame.clone();
            shadow_uniform_frame.render_stage = Some(self.source_shadow_render_stage()?);
            let instances = batch
                .indices
                .iter()
                .map(|&index| {
                    frame
                        .mesh_instances
                        .get(index)
                        .map(|instance| (instance.transform, instance.color_argb))
                        .ok_or_else(|| {
                            GalError::invalid_argument(
                            "lowered source terrain batch references a missing semantic instance",
                        )
                        })
                })
                .collect::<GalResult<Vec<_>>>()?;
            let prepared = self.prepare_source_terrain_frame_for_mesh_range(
                program,
                frame.frame_id,
                batch.key.mesh_key,
                batch.key.mesh_generation,
                batch.index_offset,
                batch.index_count,
                &instances,
                &texture_transforms,
                &uniform_frame,
            )?;
            collect_selected_source_terrain_transform_probes(
                &mut transform_probes,
                frame,
                batch,
                &prepared,
            )?;
            let mut terrain_draws = self.prepare_lowered_source_terrain_draws_for_snapshot(
                gal,
                world_generation,
                program,
                &prepared,
                batch.key.material_mode,
                batch.key.cull_policy,
                batch.key.winding,
            )?;
            for terrain_draw in &mut terrain_draws {
                terrain_draw.stratum = batch.key.stratum;
            }
            if source_shadow_required_for_material_mode(batch.key.material_mode) {
                let shadow_prepared = self.prepare_source_terrain_frame_for_mesh_range(
                    &programs.shadow,
                    frame.frame_id,
                    batch.key.mesh_key,
                    batch.key.mesh_generation,
                    batch.index_offset,
                    batch.index_count,
                    &instances,
                    &texture_transforms,
                    &shadow_uniform_frame,
                )?;
                let source_resources = self
                    .candidate_source_resources_for_program(
                        shader_pack_generation,
                        world_generation,
                        frame.frame_id,
                        &programs.shadow,
                    )?
                    .clone();
                let shadow_draws = self.prepare_lowered_source_shadow_draws(
                    gal,
                    &programs.shadow,
                    &shadow_prepared,
                    &source_resources,
                    batch.key.material_mode,
                    batch.key.cull_policy,
                    batch.key.winding,
                )?;
                if terrain_draws.len() != shadow_draws.len() {
                    return Err(GalError::invalid_argument(
                        "source terrain and shadow programs selected different mesh section counts",
                    ));
                }
                for (terrain_draw, shadow_draw) in terrain_draws.iter_mut().zip(shadow_draws) {
                    terrain_draw.shadow = Some(shadow_draw);
                }
            } else {
                for terrain_draw in &mut terrain_draws {
                    terrain_draw.shadow_participation = TerrainShadowParticipation::Unavailable;
                }
            }
            draws.extend(terrain_draws);
        }
        self.write_selected_source_terrain_transform_receipt(frame, &transform_probes);
        Ok(draws)
    }

    /// Produces the only handoff a future admitted source executor needs:
    /// all source draws plus the upload transaction that must precede them in
    /// the same submission. Any preparation failure releases unsubmitted
    /// frame-local state rather than consuming a stream slot indefinitely.
    fn prepare_lowered_source_terrain_frame_plan(
        &mut self,
        gal: &mut VulkanicGal,
        programs: &LoweredSourceTerrainPrograms,
        world_generation: u64,
        frame: &WorldPrimitiveFrame,
        batches: &[MeshBatch],
    ) -> GalResult<PreparedLoweredSourceTerrainFramePlan> {
        let draws = match self.prepare_lowered_source_terrain_draws_for_mesh_batches(
            gal,
            programs,
            world_generation,
            frame,
            batches,
        ) {
            Ok(draws) => draws,
            Err(error) => {
                self.discard_source_terrain_frame_transaction(gal, frame.frame_id);
                return Err(error);
            }
        };
        let transaction = match self.take_source_terrain_frame_transaction(frame.frame_id) {
            Ok(transaction) => Some(transaction),
            Err(_error) if draws.is_empty() => None,
            Err(error) => {
                self.discard_source_terrain_frame_transaction(gal, frame.frame_id);
                return Err(error);
            }
        };
        Ok(PreparedLoweredSourceTerrainFramePlan {
            frame_id: frame.frame_id,
            draws,
            transaction,
        })
    }

    /// Assembles the ordinary terrain portion of a source-derived frame over
    /// the pack's Rust-owned named color generation. This is intentionally a
    /// private transaction builder: it prepares no presenter and cannot make
    /// the selected-source route available on its own. Its purpose is to keep
    /// vanilla terrain's stream upload, named color samplers, bootstrap clear,
    /// and color history inseparable from the eventual combined terrain/DH
    /// source submission.
    fn prepare_named_source_terrain_frame_plan(
        &mut self,
        gal: &mut VulkanicGal,
        programs: &LoweredSourceTerrainPrograms,
        world_generation: u64,
        graph_generation: u64,
        frame: &WorldPrimitiveFrame,
        batches: &[MeshBatch],
        extent: Extent3d,
        depth_texture: Handle,
        depth_view: Handle,
        shadow_targets: TerrainSourceShadowPassTargets,
        clear_values: ShaderPackColorBootstrapClearValues,
        source_sky_initializer: bool,
    ) -> GalResult<PreparedNamedSourceTerrainFramePlan> {
        if world_generation == 0 {
            return Err(GalError::invalid_argument(
                "named source terrain preparation requires a non-zero world generation",
            ));
        }
        let shader_pack_generation = programs.shader_pack_generation()?;
        let color_targets = self
            .shader_runtime
            .as_mut()
            .ok_or_else(|| {
                GalError::invalid_argument(
                    "named source terrain preparation requires an initialized shader runtime",
                )
            })?
            .stage_complete_source_color_targets(gal, world_generation, extent)?
            .ok_or_else(|| {
                GalError::unsupported_feature(
                    "selected source terrain program has no Rust-owned named color target manifest",
                )
            })?;
        if color_targets.identity.shader_pack_generation != shader_pack_generation {
            self.shader_runtime
                .as_mut()
                .expect("shader runtime remains installed while rolling back named source targets")
                .discard_source_color_targets_submission(gal);
            return Err(GalError::invalid_argument(
                "named source terrain color targets do not match the lowered program generation",
            ));
        }

        let result = (|| -> GalResult<PreparedNamedSourceTerrainFramePlan> {
            let terrain_phase = if source_sky_initializer {
                TerrainSourceColorPassPhase::BootstrapAfterSky
            } else {
                TerrainSourceColorPassPhase::for_program(&programs.opaque)
            };
            let terrain_targets = self
                .stage_source_terrain_color_pass_targets(
                    gal,
                    world_generation,
                    graph_generation,
                    extent,
                    &programs.opaque,
                    &color_targets,
                    depth_texture,
                    depth_view,
                    clear_values,
                    terrain_phase,
                )?
                .clone();
            let opaque_resources = self.stage_candidate_source_resources_for_terrain_program(
                gal,
                shader_pack_generation,
                world_generation,
                frame.frame_id,
                &programs.opaque,
                &color_targets,
            )?;
            let cutout_resources = self.stage_candidate_source_resources_for_terrain_program(
                gal,
                shader_pack_generation,
                world_generation,
                frame.frame_id,
                &programs.cutout,
                &color_targets,
            )?;
            let opaque_formats = terrain_targets
                .color_attachments
                .iter()
                .map(|attachment| attachment.format)
                .collect::<Vec<_>>();
            let cutout_targets = self
                .shader_runtime
                .as_ref()
                .expect("shader runtime remains installed while resolving cutout outputs")
                .resolve_terrain_source_color_outputs(&programs.cutout, &color_targets)?;
            let cutout_formats = cutout_targets
                .iter()
                .map(|attachment| attachment.format)
                .collect::<Vec<_>>();
            if opaque_formats != cutout_formats {
                return Err(GalError::unsupported_feature(
                    "ordinary source terrain opaque and cutout programs require different named color target schemas",
                ));
            }

            // The source pack owns a distinct translucent program and may
            // declare a different named output schema for it. Resolve and
            // stage that writer only when this exact frame actually contains
            // translucent terrain, so an incomplete water/transparency
            // contract cannot block ordinary vanilla terrain or DH.
            let has_translucent_batches = batches.iter().any(|batch| {
                is_source_terrain_mesh_stratum(batch.key.stratum)
                    && batch.key.g_buffer
                    && batch.key.material_mode == WORLD_MATERIAL_MODE_TRANSLUCENT
            });
            let has_bootstrap_batches = batches.iter().any(|batch| {
                is_source_terrain_mesh_stratum(batch.key.stratum)
                    && batch.key.g_buffer
                    && matches!(
                        batch.key.material_mode,
                        WORLD_MATERIAL_MODE_OPAQUE | WORLD_MATERIAL_MODE_CUTOUT
                    )
            });
            // Translucent source draws deliberately do not use the opaque
            // shadow program. Keep shadow resources absent when this frame
            // has no opaque/cutout caster instead of manufacturing an empty
            // shadow pass with unrelated generation dependencies.
            let shadow_resources = has_bootstrap_batches
                .then(|| {
                    self.candidate_source_resources_for_program(
                        shader_pack_generation,
                        world_generation,
                        frame.frame_id,
                        &programs.shadow,
                    )
                    .cloned()
                })
                .transpose()?;
            let (
                translucent_program,
                translucent_targets,
                translucent_resources,
                translucent_formats,
            ) = if has_translucent_batches {
                let program = self
                        .shader_runtime
                        .as_ref()
                        .expect("shader runtime remains installed while resolving translucent source program")
                        .prepared_lowered_translucent_terrain_source_program()?
                        .ok_or_else(|| {
                            GalError::unsupported_feature(
                                "named source terrain frame contains translucent batches but the selected pack has no admitted translucent program",
                            )
                        })?;
                if program.shader_pack_generation != shader_pack_generation {
                    return Err(GalError::invalid_argument(
                        "translucent source program does not match the opaque/cutout shader-pack generation",
                    ));
                }
                let translucent_phase = source_terrain_translucent_phase(has_bootstrap_batches);
                let targets = self
                    .stage_source_terrain_color_pass_targets(
                        gal,
                        world_generation,
                        graph_generation,
                        extent,
                        &program,
                        &color_targets,
                        depth_texture,
                        depth_view,
                        clear_values,
                        translucent_phase,
                    )?
                    .clone();
                let resources = self.stage_candidate_source_resources_for_terrain_program(
                    gal,
                    shader_pack_generation,
                    world_generation,
                    frame.frame_id,
                    &program,
                    &color_targets,
                )?;
                let formats = targets
                    .color_attachments
                    .iter()
                    .map(|attachment| attachment.format)
                    .collect::<Vec<_>>();
                (Some(program), Some(targets), Some(resources), Some(formats))
            } else {
                (None, None, None, None)
            };

            let textured_material_batches = source_textured_material_batches(frame)?;
            let (
                textured_material_program,
                textured_material_targets,
                textured_material_resources,
                textured_material_formats,
            ) = if textured_material_batches.is_empty() {
                (None, None, None, None)
            } else {
                let program = self
                    .shader_runtime
                    .as_ref()
                    .expect("shader runtime remains installed while resolving gbuffers_textured")
                    .prepared_lowered_textured_material_source_program()?
                    .ok_or_else(|| {
                        GalError::unsupported_feature(
                            "selected source frame has textured material work but no lowered gbuffers_textured program",
                        )
                    })?;
                if program.shader_pack_generation != shader_pack_generation {
                    return Err(GalError::invalid_argument(
                        "gbuffers_textured program generation does not match the named terrain target generation",
                    ));
                }
                let targets = self
                    .stage_textured_material_source_color_pass_targets(
                        gal,
                        world_generation,
                        graph_generation,
                        extent,
                        &program,
                        &color_targets,
                        depth_texture,
                        depth_view,
                        clear_values,
                    )?
                    .clone();
                let resources = self
                    .stage_candidate_source_resources_for_textured_material_program(
                        gal,
                        world_generation,
                        frame.frame_id,
                        &program,
                        &color_targets,
                    )?;
                let formats = targets
                    .color_attachments
                    .iter()
                    .map(|attachment| attachment.format)
                    .collect::<Vec<_>>();
                (Some(program), Some(targets), Some(resources), Some(formats))
            };

            let weather_batches = source_weather_material_batches(frame)?;
            let (weather_program, weather_targets, weather_resources, weather_formats) =
                if weather_batches.is_empty() {
                    (None, None, None, None)
                } else {
                    let weather = self
                    .shader_runtime
                    .as_ref()
                    .expect("shader runtime remains installed while resolving gbuffers_weather")
                    .prepared_lowered_weather_source_program()?
                    .ok_or_else(|| {
                        GalError::unsupported_feature(
                            "selected source frame has weather work but no lowered gbuffers_weather program",
                        )
                    })?;
                    if weather.shader_pack_generation != shader_pack_generation {
                        return Err(GalError::invalid_argument(
                            "gbuffers_weather program generation does not match the named terrain target generation",
                        ));
                    }
                    let program = weather.material_stream_program();
                    let targets = self
                        .stage_weather_source_color_pass_targets(
                            gal,
                            world_generation,
                            graph_generation,
                            extent,
                            &program,
                            &color_targets,
                            depth_texture,
                            depth_view,
                            clear_values,
                        )?
                        .clone();
                    let resources = self.stage_candidate_source_resources_for_weather_program(
                        gal,
                        world_generation,
                        frame.frame_id,
                        &weather,
                        &color_targets,
                    )?;
                    let formats = targets
                        .color_attachments
                        .iter()
                        .map(|attachment| attachment.format)
                        .collect::<Vec<_>>();
                    (Some(program), Some(targets), Some(resources), Some(formats))
                };

            let cloud_batches = source_cloud_material_batches(frame)?;
            let clouds_suppressed = self
                .shader_runtime
                .as_ref()
                .is_some_and(ShaderPackRuntimeExecutor::suppresses_vanilla_cloud_faces);
            let (cloud_program, cloud_targets, cloud_resources, cloud_formats, cloud_blend) =
                if cloud_batches.is_empty() || clouds_suppressed {
                    (None, None, None, None, None)
                } else {
                    let clouds = self
                        .shader_runtime
                        .as_ref()
                        .expect("shader runtime remains installed while resolving gbuffers_clouds")
                        .prepared_lowered_cloud_source_program()?
                        .ok_or_else(|| {
                            GalError::unsupported_feature(
                                "selected source frame has cloud work but no lowered gbuffers_clouds program",
                            )
                        })?;
                    if clouds.shader_pack_generation != shader_pack_generation {
                        return Err(GalError::invalid_argument(
                            "gbuffers_clouds program generation does not match the named terrain target generation",
                        ));
                    }
                    let program = clouds.material_stream_program();
                    let targets = self
                        .stage_cloud_source_color_pass_targets(
                            gal,
                            world_generation,
                            graph_generation,
                            extent,
                            &program,
                            &color_targets,
                            depth_texture,
                            depth_view,
                            clear_values,
                        )?
                        .clone();
                    let resources = self.stage_candidate_source_resources_for_cloud_program(
                        gal,
                        world_generation,
                        frame.frame_id,
                        &clouds,
                        &color_targets,
                    )?;
                    let formats = targets
                        .color_attachments
                        .iter()
                        .map(|attachment| attachment.format)
                        .collect::<Vec<_>>();
                    (
                        Some(program),
                        Some(targets),
                        Some(resources),
                        Some(formats),
                        Some(clouds.blend),
                    )
                };

            let has_entity_meshes = frame
                .mesh_instances
                .iter()
                .any(|instance| instance.stratum == WORLD_STRATUM_ENTITY_MESH);
            let (entity_program, entity_targets, entity_resources, entity_formats, entity_frames) =
                if has_entity_meshes {
                    let program = self
                    .shader_runtime
                    .as_ref()
                    .expect("shader runtime remains installed while resolving gbuffers_entities")
                    .prepared_lowered_entity_source_program()?
                    .ok_or_else(|| {
                        GalError::unsupported_feature(
                            "selected source frame has entity meshes but no lowered gbuffers_entities program",
                        )
                    })?;
                    if program.shader_pack_generation != shader_pack_generation {
                        return Err(GalError::invalid_argument(
                            "gbuffers_entities program generation does not match the named terrain target generation",
                        ));
                    }
                    let targets = self
                        .stage_entity_source_color_pass_targets(
                            gal,
                            world_generation,
                            graph_generation,
                            extent,
                            &program,
                            &color_targets,
                            depth_texture,
                            depth_view,
                            clear_values,
                        )?
                        .clone();
                    let resources = self.stage_candidate_source_resources_for_entity_program(
                        gal,
                        world_generation,
                        frame.frame_id,
                        &program,
                        &color_targets,
                    )?;
                    let frames = self.prepare_source_entity_frames(&program, frame)?;
                    if frames.is_empty() {
                        return Err(GalError::invalid_argument(
                            "selected source frame advertised entity meshes but entity preparation emitted no semantic sections",
                        ));
                    }
                    let formats = targets
                        .color_attachments
                        .iter()
                        .map(|attachment| attachment.format)
                        .collect::<Vec<_>>();
                    (
                        Some(program),
                        Some(targets),
                        Some(resources),
                        Some(formats),
                        frames,
                    )
                } else {
                    (None, None, None, None, Vec::new())
                };

            let has_first_person_meshes = !frame.first_person_mesh_instances.is_empty();
            let (hand_program, hand_targets, hand_resources, hand_formats, hand_frames) =
                if has_first_person_meshes {
                    let program = self
                        .shader_runtime
                        .as_ref()
                        .expect("shader runtime remains installed while resolving gbuffers_hand")
                        .prepared_lowered_hand_source_program()?
                        .ok_or_else(|| {
                            GalError::unsupported_feature(
                                "selected source frame has first-person meshes but no lowered gbuffers_hand program",
                            )
                        })?;
                    if program.shader_pack_generation != shader_pack_generation {
                        return Err(GalError::invalid_argument(
                            "gbuffers_hand program generation does not match the named terrain target generation",
                        ));
                    }
                    let targets = self
                        .stage_hand_source_color_pass_targets(
                            gal,
                            world_generation,
                            graph_generation,
                            extent,
                            &program,
                            &color_targets,
                            clear_values,
                        )?
                        .clone();
                    let resources = self.stage_candidate_source_resources_for_hand_program(
                        gal,
                        world_generation,
                        frame.frame_id,
                        &program,
                        &color_targets,
                    )?;
                    let frames = self.prepare_source_hand_frames(&program, frame)?;
                    if frames.is_empty() {
                        return Err(GalError::invalid_argument(
                            "selected source frame advertised first-person meshes but hand preparation emitted no semantic sections",
                        ));
                    }
                    let formats = targets
                        .color_attachments
                        .iter()
                        .map(|attachment| attachment.format)
                        .collect::<Vec<_>>();
                    (
                        Some(program),
                        Some(targets),
                        Some(resources),
                        Some(formats),
                        frames,
                    )
                } else {
                    (None, None, None, None, Vec::new())
                };

            let base_uniform_frame = self.source_uniform_frame_for_owned_resources(frame)?;
            let texture_transforms = TerrainSourceTextureTransforms::canonical_minecraft_terrain();
            // Entity meshes have an independent source-program writer below.
            // Keep the terrain stream reservation and terrain draw preparation
            // scoped to the terrain strata so a combined frame never attempts
            // to interpret entity sections as terrain batches.
            let terrain_batches = batches
                .iter()
                .filter(|batch| is_source_terrain_mesh_stratum(batch.key.stratum))
                .collect::<Vec<_>>();
            let required_stream_bytes = terrain_batches.iter().try_fold(0_u64, |total, batch| {
                let program = match batch.key.material_mode {
                    WORLD_MATERIAL_MODE_OPAQUE => &programs.opaque,
                    WORLD_MATERIAL_MODE_CUTOUT => &programs.cutout,
                    WORLD_MATERIAL_MODE_TRANSLUCENT => translucent_program.as_ref().ok_or_else(|| {
                        GalError::unsupported_feature(
                            "named source terrain frame has translucent batches without an admitted translucent program",
                        )
                    })?,
                    mode => {
                        return Err(GalError::unsupported_feature(format!(
                            "named source terrain preparation rejects material mode {mode}",
                        )));
                    }
                };
                let instance_count = u64::try_from(batch.indices.len()).map_err(|_| {
                    GalError::invalid_argument(
                        "named source terrain batch instance count exceeds u64",
                    )
                })?;
                let color_bytes =
                    Self::source_terrain_frame_stream_payload_bytes(program, instance_count)?;
                let shadow_bytes = source_shadow_required_for_material_mode(batch.key.material_mode)
                .then(|| {
                    Self::source_terrain_frame_stream_payload_bytes(
                        &programs.shadow,
                        instance_count,
                    )
                })
                .transpose()?
                .unwrap_or(0);
                total
                    .checked_add(color_bytes)
                    .and_then(|total| total.checked_add(shadow_bytes))
                    .ok_or_else(|| {
                        GalError::invalid_argument(
                            "named source terrain frame stream reservation overflows",
                        )
                    })
            })?;
            let textured_material_stream_bytes = match textured_material_program.as_ref() {
                Some(program) => source_material_batch_stream_bytes(
                    program,
                    &textured_material_batches,
                    "textured material",
                )?,
                None => 0,
            };
            let weather_stream_bytes = match weather_program.as_ref() {
                Some(program) => {
                    source_material_batch_stream_bytes(program, &weather_batches, "weather")?
                }
                None => 0,
            };
            let cloud_stream_bytes = match cloud_program.as_ref() {
                Some(program) => {
                    source_material_batch_stream_bytes(program, &cloud_batches, "clouds")?
                }
                None => 0,
            };
            let entity_stream_bytes = match entity_program.as_ref() {
                Some(program) => entity_frames.iter().try_fold(0_u64, |total, prepared| {
                    let instance_count = u64::try_from(
                        prepared.instance_transforms.len() / TERRAIN_SOURCE_INSTANCE_BYTES,
                    )
                    .map_err(|_| {
                        GalError::invalid_argument("entity source instance count exceeds u64")
                    })?;
                    let payload =
                        Self::source_entity_frame_stream_payload_bytes(program, instance_count)?;
                    total.checked_add(payload).ok_or_else(|| {
                        GalError::invalid_argument(
                            "entity source frame stream reservation overflows",
                        )
                    })
                })?,
                None => 0,
            };
            let hand_stream_bytes = match hand_program.as_ref() {
                Some(program) => hand_frames.iter().try_fold(0_u64, |total, prepared| {
                    let instance_count = u64::try_from(
                        prepared.instance_transforms.len() / TERRAIN_SOURCE_INSTANCE_BYTES,
                    )
                    .map_err(|_| {
                        GalError::invalid_argument("hand source instance count exceeds u64")
                    })?;
                    let payload =
                        Self::source_hand_frame_stream_payload_bytes(program, instance_count)?;
                    total.checked_add(payload).ok_or_else(|| {
                        GalError::invalid_argument("hand source frame stream reservation overflows")
                    })
                })?,
                None => 0,
            };
            let required_stream_bytes = required_stream_bytes
                .checked_add(textured_material_stream_bytes)
                .and_then(|bytes| bytes.checked_add(weather_stream_bytes))
                .and_then(|bytes| bytes.checked_add(cloud_stream_bytes))
                .and_then(|bytes| bytes.checked_add(entity_stream_bytes))
                .and_then(|bytes| bytes.checked_add(hand_stream_bytes))
                .ok_or_else(|| {
                    GalError::invalid_argument("combined source frame stream reservation overflows")
                })?;
            self.reserve_source_terrain_frame_stream_capacity(
                gal,
                frame.frame_id,
                required_stream_bytes,
            )?;
            let mut draws = Vec::new();
            let mut transform_probes = Vec::new();
            for batch in terrain_batches {
                if !batch.key.g_buffer {
                    return Err(GalError::unsupported_feature(
                        "named source terrain preparation accepts only source-compatible G-buffer mesh batches",
                    ));
                }
                let (program, resources, color_formats, shadow_required) = match batch.key.material_mode {
                    WORLD_MATERIAL_MODE_OPAQUE => {
                        (&programs.opaque, &opaque_resources, &opaque_formats, true)
                    }
                    WORLD_MATERIAL_MODE_CUTOUT => {
                        (&programs.cutout, &cutout_resources, &opaque_formats, true)
                    }
                    WORLD_MATERIAL_MODE_TRANSLUCENT => (
                        translucent_program.as_ref().ok_or_else(|| {
                            GalError::unsupported_feature(
                                "named source terrain frame has translucent batches without an admitted translucent program",
                            )
                        })?,
                        translucent_resources.as_ref().ok_or_else(|| {
                            GalError::backend(
                                "named source terrain frame lost its translucent resource snapshot",
                            )
                        })?,
                        translucent_formats.as_ref().ok_or_else(|| {
                            GalError::backend(
                                "named source terrain frame lost its translucent named output schema",
                            )
                        })?,
                        false,
                    ),
                    mode => {
                        return Err(GalError::unsupported_feature(format!(
                            "named source terrain preparation rejects material mode {mode}",
                        )));
                }
            };
                if matches!(
                    std::env::var("MATTMC_RUST_SOURCE_DRAW_TRACE").as_deref(),
                    Ok("1") | Ok("true") | Ok("TRUE")
                ) {
                    eprintln!(
                        "[MattMC source-draw-trace] frame={} stratum={} material_mode={} program={} instances={} indices={} color_formats={:?}",
                        frame.frame_id,
                        batch.key.stratum,
                        batch.key.material_mode,
                        program.identity.as_str(),
                        batch.indices.len(),
                        batch.index_count,
                        color_formats,
                    );
                }
                let instances = batch
                    .indices
                    .iter()
                    .map(|&index| {
                        frame.mesh_instances.get(index).map(|instance| (instance.transform, instance.color_argb)).ok_or_else(
                            || {
                                GalError::invalid_argument(
                                    "named source terrain batch references a missing semantic instance",
                                )
                            },
                        )
                    })
                    .collect::<GalResult<Vec<_>>>()?;
                let mut uniform_frame = base_uniform_frame.clone();
                uniform_frame.render_stage =
                    Some(self.source_render_stage_for_material_mode(batch.key.material_mode)?);
                let prepared = self.prepare_source_terrain_frame_for_mesh_range(
                    program,
                    frame.frame_id,
                    batch.key.mesh_key,
                    batch.key.mesh_generation,
                    batch.index_offset,
                    batch.index_count,
                    &instances,
                    &texture_transforms,
                    &uniform_frame,
                )?;
                collect_selected_source_terrain_transform_probes(
                    &mut transform_probes,
                    frame,
                    batch,
                    &prepared,
                )?;
                let mut terrain_draws = self
                    .prepare_lowered_source_terrain_draws_for_color_formats(
                        gal,
                        program,
                        &prepared,
                        resources,
                        batch.key.material_mode,
                        batch.key.cull_policy,
                        batch.key.winding,
                        color_formats.clone(),
                    )?;
                // Source lowering is shared across semantic mesh families;
                // retain the batch's producer stratum on every lowered draw
                // so moving-block coverage cannot be misclassified as an
                // entity submission.
                for terrain_draw in &mut terrain_draws {
                    terrain_draw.stratum = batch.key.stratum;
                }
                if shadow_required {
                    let mut shadow_uniform_frame = base_uniform_frame.clone();
                    shadow_uniform_frame.render_stage = Some(self.source_shadow_render_stage()?);
                    let shadow_prepared = self.prepare_source_terrain_frame_for_mesh_range(
                        &programs.shadow,
                        frame.frame_id,
                        batch.key.mesh_key,
                        batch.key.mesh_generation,
                        batch.index_offset,
                        batch.index_count,
                        &instances,
                        &texture_transforms,
                        &shadow_uniform_frame,
                    )?;
                    let shadow_draws = self.prepare_lowered_source_shadow_draws(
                        gal,
                        &programs.shadow,
                        &shadow_prepared,
                        shadow_resources.as_ref().ok_or_else(|| {
                            GalError::backend(
                                "named source terrain frame lost its opaque/cutout shadow resource snapshot",
                            )
                        })?,
                        batch.key.material_mode,
                        batch.key.cull_policy,
                        batch.key.winding,
                    )?;
                    if terrain_draws.len() != shadow_draws.len() {
                        return Err(GalError::invalid_argument(
                            "named source terrain and shadow programs selected different mesh section counts",
                        ));
                    }
                    for (terrain_draw, shadow_draw) in terrain_draws.iter_mut().zip(shadow_draws) {
                        terrain_draw.shadow = Some(shadow_draw);
                    }
                } else {
                    for terrain_draw in &mut terrain_draws {
                        terrain_draw.shadow_participation = TerrainShadowParticipation::Unavailable;
                    }
                }
                draws.extend(terrain_draws);
            }
            self.write_selected_source_terrain_transform_receipt(frame, &transform_probes);
            let textured_material = match (
                textured_material_program.as_ref(),
                textured_material_targets,
                textured_material_resources.as_ref(),
                textured_material_formats.as_ref(),
            ) {
                (None, None, None, None) => None,
                (Some(program), Some(targets), Some(resources), Some(formats)) => {
                    let texture_transforms =
                        self.source_texture_transforms_for_owned_resources()?;
                    let mut material_draws = Vec::with_capacity(textured_material_batches.len());
                    for batch in textured_material_batches {
                        let (batch_resources, local_texture, local_texture_extent) = self
                            .source_resources_for_textured_material_batch(
                                gal,
                                program,
                                resources,
                                batch,
                                frame.frame_id,
                            )?;
                        let mut uniform_frame = base_uniform_frame.clone();
                        uniform_frame.render_stage =
                            Some(self.source_render_stage_for_material_mode(batch.material_mode)?);
                        uniform_frame.block_entity_id = Some(batch.block_entity_id);
                        if let Some(extent) = local_texture_extent {
                            uniform_frame.material_atlas_size = Some(extent);
                        }
                        let prepared = self.prepare_textured_material_source_frame_for_indices(
                            program,
                            frame,
                            batch.indices(),
                            &texture_transforms,
                            &uniform_frame,
                        )?;
                        material_draws.push(self.prepare_lowered_textured_material_source_draw(
                            gal,
                            program,
                            &prepared,
                            &batch_resources,
                            local_texture,
                            batch.material_mode,
                            batch.depth_policy,
                            batch.cull_policy,
                            batch.winding,
                            formats.clone(),
                        )?);
                    }
                    Some(PreparedNamedSourceTexturedMaterialFramePlan {
                        targets,
                        draws: material_draws,
                    })
                }
                _ => {
                    return Err(GalError::backend(
                        "textured material source preparation retained an incomplete program/target/resource tuple",
                    ));
                }
            };
            let weather = match (
                weather_program.as_ref(),
                weather_targets,
                weather_resources.as_ref(),
                weather_formats.as_ref(),
            ) {
                (None, None, None, None) => None,
                (Some(program), Some(targets), Some(resources), Some(formats)) => {
                    let texture_transforms =
                        self.source_texture_transforms_for_owned_resources()?;
                    let mut weather_draws = Vec::with_capacity(weather_batches.len());
                    for batch in weather_batches {
                        let (batch_resources, local_texture, local_texture_extent) = self
                            .source_resources_for_textured_material_batch(
                                gal,
                                program,
                                resources,
                                batch,
                                frame.frame_id,
                            )?;
                        let mut uniform_frame = base_uniform_frame.clone();
                        uniform_frame.render_stage = Some(self.source_weather_render_stage()?);
                        if let Some(extent) = local_texture_extent {
                            uniform_frame.material_atlas_size = Some(extent);
                        }
                        let prepared = self.prepare_textured_material_source_frame_for_indices(
                            program,
                            frame,
                            batch.indices(),
                            &texture_transforms,
                            &uniform_frame,
                        )?;
                        weather_draws.push(self.prepare_lowered_weather_source_draw(
                            gal,
                            program,
                            &prepared,
                            &batch_resources,
                            local_texture,
                            batch.material_mode,
                            batch.depth_policy,
                            batch.cull_policy,
                            batch.winding,
                            formats.clone(),
                        )?);
                    }
                    Some(PreparedNamedSourceWeatherFramePlan {
                        targets,
                        draws: weather_draws,
                    })
                }
                _ => {
                    return Err(GalError::backend(
                        "weather source preparation retained an incomplete program/target/resource tuple",
                    ));
                }
            };
            let clouds = match (
                cloud_program.as_ref(),
                cloud_targets,
                cloud_resources.as_ref(),
                cloud_formats.as_ref(),
                cloud_blend,
            ) {
                (None, None, None, None, None) => None,
                (Some(program), Some(targets), Some(resources), Some(formats), Some(blend)) => {
                    self.write_cloud_pipeline_receipt(
                        frame.frame_id,
                        program,
                        &cloud_batches,
                        blend,
                        targets.color_attachments.len(),
                    );
                    let texture_transforms =
                        self.source_texture_transforms_for_owned_resources()?;
                    let mut cloud_draws = Vec::with_capacity(cloud_batches.len());
                    for batch in cloud_batches {
                        let (batch_resources, local_texture, local_texture_extent) = self
                            .source_resources_for_textured_material_batch(
                                gal,
                                program,
                                resources,
                                batch,
                                frame.frame_id,
                            )?;
                        let mut uniform_frame = base_uniform_frame.clone();
                        uniform_frame.render_stage = Some(self.source_cloud_render_stage()?);
                        if let Some(extent) = local_texture_extent {
                            uniform_frame.material_atlas_size = Some(extent);
                        }
                        let prepared = self.prepare_textured_material_source_frame_for_indices(
                            program,
                            frame,
                            batch.indices(),
                            &texture_transforms,
                            &uniform_frame,
                        )?;
                        cloud_draws.push(self.prepare_lowered_cloud_source_draw(
                            gal,
                            program,
                            &prepared,
                            &batch_resources,
                            local_texture,
                            batch.material_mode,
                            batch.depth_policy,
                            batch.cull_policy,
                            batch.winding,
                            formats.clone(),
                            blend,
                        )?);
                    }
                    Some(PreparedNamedSourceCloudFramePlan {
                        targets,
                        draws: cloud_draws,
                    })
                }
                _ => {
                    return Err(GalError::backend(
                        "cloud source preparation retained an incomplete program/target/resource tuple",
                    ));
                }
            };
            let entities = match (
                entity_program.as_ref(),
                entity_targets,
                entity_resources.as_ref(),
                entity_formats.as_ref(),
            ) {
                (None, None, None, None) => None,
                (Some(program), Some(targets), Some(resources), Some(formats)) => {
                    let mut entity_draws = Vec::with_capacity(entity_frames.len());
                    for prepared in &entity_frames {
                        entity_draws.push(self.prepare_lowered_source_entity_draw(
                            gal,
                            program,
                            prepared,
                            resources,
                            formats.clone(),
                        )?);
                    }
                    Some(PreparedNamedSourceEntityFramePlan {
                        targets,
                        draws: entity_draws,
                    })
                }
                _ => {
                    return Err(GalError::backend(
                        "entity source preparation retained an incomplete program/target/resource tuple",
                    ));
                }
            };
            let hands = match (
                hand_program.as_ref(),
                hand_targets,
                hand_resources.as_ref(),
                hand_formats.as_ref(),
            ) {
                (None, None, None, None) => None,
                (Some(program), Some(targets), Some(resources), Some(formats)) => {
                    let mut hand_draws = Vec::with_capacity(hand_frames.len());
                    for prepared in &hand_frames {
                        hand_draws.push(self.prepare_lowered_source_hand_draw(
                            gal,
                            program,
                            prepared,
                            resources,
                            formats.clone(),
                        )?);
                    }
                    Some(PreparedNamedSourceHandFramePlan {
                        targets,
                        draws: hand_draws,
                    })
                }
                _ => {
                    return Err(GalError::backend(
                        "hand source preparation retained an incomplete program/target/resource tuple",
                    ));
                }
            };
            // Celestial and other source fullscreen consumers can request a
            // copied local material after the indexed writers have prepared
            // their draws. Fold those uploads into the same frame transaction
            // before taking it, preserving upload-before-draw ordering.
            self.absorb_pending_source_material_texture_uploads(frame.frame_id)?;
            let terrain = match self.take_source_terrain_frame_transaction(frame.frame_id) {
                Ok(transaction) => PreparedLoweredSourceTerrainFramePlan {
                    frame_id: frame.frame_id,
                    draws,
                    transaction: Some(transaction),
                },
                Err(_error) if draws.is_empty() => PreparedLoweredSourceTerrainFramePlan {
                    frame_id: frame.frame_id,
                    draws,
                    transaction: None,
                },
                Err(error) => return Err(error),
            };
            let mut bootstrap_operations = Vec::new();
            let color_transaction = self
                .shader_runtime
                .as_ref()
                .expect("shader runtime remains installed while creating named source transaction")
                .begin_source_color_transaction(
                    gal,
                    &color_targets,
                    clear_values,
                    &mut bootstrap_operations,
                )?;
            Ok(PreparedNamedSourceTerrainFramePlan {
                terrain,
                entities,
                hands,
                textured_material,
                weather,
                clouds,
                color_targets,
                shadow_targets: has_bootstrap_batches.then_some(shadow_targets),
                main_depth_history: None,
                targets: terrain_targets,
                translucent_targets,
                pre_terrain_sky: Vec::new(),
                color_transaction,
                bootstrap_operations,
            })
        })();
        if result.is_err() {
            self.discard_source_terrain_frame_transaction(gal, frame.frame_id);
            self.shader_runtime
                .as_mut()
                .expect(
                    "shader runtime remains installed while discarding named source transaction",
                )
                .discard_source_color_targets_submission(gal);
        }
        result
    }

    /// Prepares the source-derived Distant Horizons material stages against
    /// the exact named color generation staged by normal terrain. Opaque and
    /// the source pack's late translucent program use their own lowered
    /// programs but join one Rust-owned color/depth transaction. Complementary
    /// calls that late material program `dh_water`, yet it contains both its
    /// generic transparent path and a material-id water branch; copied layer
    /// identity and ordering remain explicit here.
    fn prepare_named_source_distant_horizons_frame_plan(
        &mut self,
        gal: &mut VulkanicGal,
        frame: &WorldPrimitiveFrame,
        color_targets: ShaderPackColorTargets,
    ) -> GalResult<Option<PreparedNamedSourceDistantHorizonsFramePlan>> {
        if !frame.lod_render_frame.rust_route_selected() || frame.lod_instances.is_empty() {
            return Ok(None);
        }
        let extent = Extent3d {
            width: frame.viewport_width,
            height: frame.viewport_height,
            depth: 1,
        };
        let Some(staged) = self.stage_distant_horizons_source_targets_for_colors(
            gal,
            frame.frame_id,
            frame.shader_environment.world_generation,
            extent,
            color_targets,
        )?
        else {
            return Ok(None);
        };
        let result = (|| -> GalResult<PreparedNamedSourceDistantHorizonsFramePlan> {
            let program = self
                .shader_runtime
                .as_ref()
                .expect("shader runtime remains installed while preparing source DH")
                .prepared_lowered_distant_horizons_source_program()?
                .ok_or_else(|| {
                    GalError::unsupported_feature(
                        "Rust Distant Horizons source plan has no admitted opaque program",
                    )
                })?;
            let resources = self.candidate_source_resources_for_distant_horizons_program(
                gal,
                frame.shader_environment.world_generation,
                frame.frame_id,
                &program,
                &staged.color_targets,
                &staged.depth_targets,
            )?;
            let mut upload_operations = Vec::new();
            self.lod_gpu_residency.stage_visible_uploads(
                gal,
                &self.lod_gpu_column_assets,
                &frame.lod_instances,
                &mut upload_operations,
            )?;
            let visible = self
                .lod_gpu_residency
                .resolve_visible_draws(&self.lod_gpu_column_assets, &frame.lod_instances)?;
            let plan = lod::plan_world_lod_frame_with_camera(
                &frame.lod_render_frame,
                &visible,
                frame.lod_render_frame.camera_world_position,
            )?;
            // Preserve the selected source program's declared material
            // convention. Complementary's dh_terrain program consumes DH's
            // reduced color/category stream and has no material-atlas input.
            // Atlas replacement is valid only for a source program that
            // explicitly declares an atlas-backed stream.
            let visible_by_source = visible
                .iter()
                .map(|draw| {
                    (
                        (
                            draw.column_key,
                            draw.column_generation,
                            draw.layer,
                            draw.segment_index,
                        ),
                        *draw,
                    )
                })
                .collect::<BTreeMap<_, _>>();
            let audit_exact_atlas_mode = world_lod_audit_exact_atlas_mode();
            let source_accepts_exact_atlas = program.has_exact_material_texture_identity();
            if !source_accepts_exact_atlas
                && matches!(
                    audit_exact_atlas_mode,
                    WorldLodAuditExactAtlasMode::ExactOnly
                )
            {
                return Err(GalError::unsupported_feature(
                    "the selected Distant Horizons source program does not declare an atlas-backed material interface",
                ));
            }
            let mut exact_atlas_instances = Vec::new();
            let mut partial_exact_instances = Vec::new();
            for instance in frame
                .lod_instances
                .iter()
                .filter(|_| source_accepts_exact_atlas)
            {
                if instance.layer != WORLD_LOD_LAYER_OPAQUE {
                    continue;
                }
                let asset = self
                    .lod_textured_gpu_column_assets
                    .get(&instance.column_key)
                    .filter(|asset| asset.column_generation == instance.column_generation)
                    .ok_or_else(|| GalError::invalid_argument(format!(
                        "world LOD exact-atlas source instance {} has no matching immutable column asset",
                        instance.column_key
                    )))?;
                if let Some(complete) = world_lod_exact_atlas_segment_completeness(asset, instance)?
                {
                    exact_atlas_instances.push(*instance);
                    if !complete {
                        partial_exact_instances.push(*instance);
                    }
                }
            }
            if matches!(
                audit_exact_atlas_mode,
                WorldLodAuditExactAtlasMode::CoarseOnly
            ) {
                // Audit-only isolation: leave every visible source segment on
                // the normal copied DH stream. This must happen before the
                // replacement set is derived so no coarse geometry is lost.
                exact_atlas_instances.clear();
                partial_exact_instances.clear();
            }
            self.lod_textured_gpu_residency.stage_visible_uploads(
                gal,
                &self.lod_textured_gpu_column_assets,
                &exact_atlas_instances,
                &mut upload_operations,
            )?;
            let mut exact_atlas_geometry = Vec::new();
            for instance in &exact_atlas_instances {
                let origin = self
                    .lod_column_assets
                    .get(&instance.column_key)
                    .filter(|asset| asset.column_generation == instance.column_generation)
                    .map(|asset| asset.origin)
                    .ok_or_else(|| {
                        GalError::invalid_argument(format!(
                        "world LOD exact-atlas source instance {} has no matching column origin",
                        instance.column_key
                    ))
                    })?;
                if let Some(draw) = self.lod_textured_gpu_residency.resolve_visible_draw(
                    &self.lod_textured_gpu_column_assets,
                    instance,
                    origin,
                )? {
                    exact_atlas_geometry.push(draw);
                }
            }
            let exact_source_segments = exact_atlas_geometry
                .iter()
                .map(|draw| {
                    (
                        draw.column_key,
                        draw.column_generation,
                        draw.source_segment_index,
                    )
                })
                .collect::<BTreeSet<_>>();
            let mut unresolved_coarse_draws = BTreeMap::new();
            for instance in &partial_exact_instances {
                let key = (
                    instance.column_key,
                    instance.column_generation,
                    instance.layer,
                    instance.segment_index,
                );
                let source_draw = visible_by_source.get(&key).copied().ok_or_else(|| {
                    GalError::backend(
                        "world LOD partial exact-atlas source segment is absent from visible source draws",
                    )
                })?;
                let unresolved = self
                    .lod_textured_gpu_residency
                    .resolve_visible_unresolved_draw(
                        &self.lod_textured_gpu_column_assets,
                        instance,
                        source_draw,
                    )?
                    .ok_or_else(|| {
                        GalError::backend(
                            "world LOD partial exact-atlas source segment has no complementary reduced-color range",
                        )
                    })?;
                unresolved_coarse_draws.insert(key, unresolved);
            }
            let partial_exact_source_segments = partial_exact_instances
                .iter()
                .map(|instance| {
                    (
                        instance.column_key,
                        instance.column_generation,
                        instance.segment_index,
                    )
                })
                .collect::<BTreeSet<_>>();
            let complete_replacement_draw_count = exact_source_segments
                .difference(&partial_exact_source_segments)
                .count() as u64;
            // The capture gate consumes this bounded, frame-scoped semantic
            // receipt. Selected-source execution resolves the same exact
            // geometry through a distinct pass owner, so publish its plan on
            // this frame rather than letting a prior ordinary DH plan stand
            // in for the presented source submission.
            self.write_world_lod_exact_atlas_status(
                frame,
                &exact_atlas_geometry,
                plan.opaque_draws.len() as u64,
                complete_replacement_draw_count,
                exact_atlas_geometry.len() as u64,
                partial_exact_instances.len() as u64,
                exact_atlas_geometry
                    .iter()
                    .map(|draw| u64::from(draw.index_count))
                    .sum(),
                unresolved_coarse_draws
                    .values()
                    .map(|draw| u64::from(draw.index_count))
                    .sum(),
            );
            let transparent_draw_count = plan.transparent_draws.len();
            let transparent_index_count = plan
                .transparent_draws
                .iter()
                .map(|draw| u64::from(draw.draw.index_count))
                .sum();
            let water_draw_count = plan.water_draws.len();
            let water_index_count = plan
                .water_draws
                .iter()
                .map(|draw| u64::from(draw.draw.index_count))
                .sum();
            let mut late_translucent_draws = plan
                .transparent_draws
                .iter()
                .map(|admitted| (admitted.draw, admitted.uniforms))
                .collect::<Vec<_>>();
            late_translucent_draws.extend(
                plan.water_draws
                    .iter()
                    .map(|admitted| (admitted.draw, admitted.uniforms)),
            );
            // The Java collector's order is the authoritative semantic order
            // for these alpha-blended DH ranges. Preserve it across the two
            // material classifications; the selected source program branches
            // on material identity rather than on a backend pass alias.
            late_translucent_draws.sort_by_key(|(draw, _)| {
                (draw.order, draw.layer, draw.column_key, draw.segment_index)
            });
            let late_translucent_draw_count = late_translucent_draws.len();
            let late_translucent_index_count = late_translucent_draws
                .iter()
                .map(|(draw, _)| u64::from(draw.index_count))
                .sum();
            let translucent_program = if late_translucent_draws.is_empty() {
                None
            } else {
                let translucent_source_status = self.shader_runtime.as_ref().and_then(
                    ShaderPackRuntimeExecutor::distant_horizons_translucent_source_candidate,
                );
                Some(
                    self.shader_runtime
                        .as_ref()
                        .expect("shader runtime remains installed while preparing source DH water")
                        .prepared_lowered_distant_horizons_translucent_source_program()?
                        .ok_or_else(|| {
                            GalError::unsupported_feature(format!(
                                "Rust Distant Horizons source plan has {} late translucent ranges, but its selected source program is unavailable: {}",
                                late_translucent_draw_count,
                                describe_distant_horizons_translucent_source_status(
                                    translucent_source_status,
                                ),
                            ))
                        })?,
                )
            };
            let target = self.lod_source_pass_resources.stage_target(
                gal,
                &staged.color_targets,
                staged.depth_targets,
            )?;
            let source_uniforms = self.source_uniform_frame_for_distant_horizons(frame)?;
            let pack_resources = self.lod_source_pass_resources.stage_pack_resources(
                gal,
                &program,
                target.primary_color_format,
                &resources,
            )?;
            let pack_resources_layout = self.lod_source_pass_resources.pack_resources_layout(
                gal,
                &program,
                target.primary_color_format,
            )?;
            let atlas = if exact_atlas_geometry.is_empty() {
                None
            } else {
                self.ensure_mesh_texture_resources(
                    gal,
                    WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
                    "world-lod-exact-atlas-source",
                )?;
                let resources = self
                    .mesh_texture_resources
                    .get(&WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS)
                    .expect("terrain atlas resources exist after successful source preparation");
                Some(lod::WorldLodTerrainAtlasBinding {
                    mesh_generation: self.mesh_asset_generation,
                    texture_view: resources.view,
                    sampler: resources.sampler,
                })
            };
            let primary_attachment = target
                .color_attachments
                .iter()
                .find(|attachment| attachment.output == TerrainPassOutput::LitTerrainColor)
                .ok_or_else(|| {
                    GalError::backend(
                        "selected-source Distant Horizons target omitted its semantic primary color attachment",
                    )
                })?;
            let mut exact_atlas_draws = Vec::with_capacity(exact_atlas_geometry.len());
            if let Some(atlas) = atlas {
                let exact_atlas_program =
                    prepare_lowered_distant_horizons_exact_atlas_source_program(&program)?;
                // An audit-only limiter isolates one real provenance-resolved
                // range when diagnosing a selected-source GPU fault. It is
                // unavailable outside graphics-audit runs and never changes
                // production route selection.
                let exact_atlas_draw_limit = if matches!(
                    std::env::var("MATTMC_GRAPHICS_AUDIT")
                        .as_deref()
                        .map(str::trim),
                    Ok("1") | Ok("true") | Ok("TRUE")
                ) {
                    std::env::var("MATTMC_RUST_DH_EXACT_ATLAS_MAX_DRAWS")
                        .ok()
                        .and_then(|value| value.trim().parse::<usize>().ok())
                } else {
                    None
                };
                let exact_atlas_index_limit = if matches!(
                    std::env::var("MATTMC_GRAPHICS_AUDIT")
                        .as_deref()
                        .map(str::trim),
                    Ok("1") | Ok("true") | Ok("TRUE")
                ) {
                    std::env::var("MATTMC_RUST_DH_EXACT_ATLAS_MAX_INDICES")
                        .ok()
                        .and_then(|value| value.trim().parse::<u32>().ok())
                        .map(|indices| indices - indices % 3)
                } else {
                    None
                };
                for draw in exact_atlas_geometry
                    .iter()
                    .copied()
                    .take(exact_atlas_draw_limit.unwrap_or(usize::MAX))
                {
                    let draw = lod::WorldLodTexturedGpuDraw {
                        index_count: exact_atlas_index_limit
                            .map(|limit| draw.index_count.min(limit))
                            .unwrap_or(draw.index_count),
                        ..draw
                    };
                    if draw.index_count == 0 {
                        continue;
                    }
                    let uniforms = lod::WorldLodDrawUniform::from_semantics_with_camera(
                        &frame.lod_render_frame,
                        lod::WorldLodGpuDraw {
                            column_key: draw.column_key,
                            column_generation: draw.column_generation,
                            origin: draw.origin,
                            layer: draw.layer,
                            segment_index: draw.source_segment_index,
                            order: draw.order,
                            vertex_buffer: draw.vertex_buffer,
                            index_buffer: draw.index_buffer,
                            index_type: draw.index_type,
                            index_count: draw.index_count,
                        },
                        frame.lod_render_frame.camera_world_position,
                    )?;
                    let prepared = self.lod_exact_atlas_source_pass_resources.stage_draw(
                        gal,
                        &exact_atlas_program,
                        primary_attachment,
                        pack_resources_layout,
                        draw,
                        uniforms,
                        atlas,
                        &source_uniforms,
                        &mut upload_operations,
                    )?;
                    exact_atlas_draws.push((prepared, pack_resources));
                }
            }
            let mut draws = Vec::with_capacity(plan.opaque_draws.len());
            // Keep the semantic draw records alongside the private prepared
            // commands for the audit receipt below. This is intentionally
            // scoped to the selected source stream: uploaded or exact-atlas
            // replacement geometry must not be mistaken for a source-program
            // draw when diagnosing clip-space faults.
            let mut selected_source_geometry = Vec::with_capacity(plan.opaque_draws.len());
            for admitted in plan.opaque_draws {
                let key = (
                    admitted.draw.column_key,
                    admitted.draw.column_generation,
                    admitted.draw.layer,
                    admitted.draw.segment_index,
                );
                let exact_key = (key.0, key.1, key.3);
                let draw = match audit_exact_atlas_mode {
                    WorldLodAuditExactAtlasMode::ExactOnly => continue,
                    WorldLodAuditExactAtlasMode::Default => {
                        if exact_source_segments.contains(&exact_key) {
                            let Some(unresolved) = unresolved_coarse_draws.get(&key).copied()
                            else {
                                continue;
                            };
                            unresolved
                        } else {
                            admitted.draw
                        }
                    }
                    WorldLodAuditExactAtlasMode::CoarseOnly => admitted.draw,
                };
                if draw.index_count == 0 {
                    continue;
                }
                selected_source_geometry.push(draw);
                draws.push(self.lod_source_pass_resources.stage_draw(
                    gal,
                    &program,
                    target.primary_color_format,
                    draw,
                    admitted.uniforms,
                    &source_uniforms,
                    &mut upload_operations,
                )?);
            }
            self.write_selected_source_distant_horizons_material_receipt(
                frame,
                &program,
                translucent_program.as_ref(),
                draws.len(),
                draws.iter().map(|draw| u64::from(draw.index_count)).sum(),
                transparent_draw_count,
                transparent_index_count,
                water_draw_count,
                water_index_count,
                &plan
                    .water_draws
                    .iter()
                    .map(|draw| draw.draw.origin)
                    .collect::<Vec<_>>(),
                late_translucent_draw_count,
                late_translucent_index_count,
                exact_atlas_draws.len(),
                exact_atlas_draws
                    .iter()
                    .map(|(draw, _)| u64::from(draw.index_count))
                    .sum(),
            );
            self.write_selected_source_distant_horizons_stream_receipt(frame, &program);
            // Keep the capture receipt representative of every executed DH
            // material range. Water has its own late translucent pass, so an
            // opaque-only trace cannot distinguish a bad water transform from
            // a later depth/composite defect.
            let mut selected_source_transform_geometry = selected_source_geometry.clone();
            selected_source_transform_geometry
                .extend(late_translucent_draws.iter().map(|(draw, _uniforms)| *draw));
            self.write_distant_horizons_transform_receipt(
                frame,
                "selected-source",
                program.identity.as_str(),
                &selected_source_transform_geometry,
            );
            let (translucent_draws, translucent_pack_resources) =
                if let Some(translucent_program) = translucent_program {
                    let translucent_resources = self
                        .candidate_source_resources_for_distant_horizons_program(
                            gal,
                            frame.shader_environment.world_generation,
                            frame.frame_id,
                            &translucent_program,
                            &staged.color_targets,
                            &staged.depth_targets,
                        )?;
                    let translucent_pack_resources =
                        self.lod_source_pass_resources.stage_pack_resources(
                            gal,
                            &translucent_program,
                            target.primary_color_format,
                            &translucent_resources,
                        )?;
                    let mut translucent_draws = Vec::with_capacity(late_translucent_draws.len());
                    for (draw, uniforms) in late_translucent_draws {
                        translucent_draws.push(self.lod_source_pass_resources.stage_draw(
                            gal,
                            &translucent_program,
                            target.primary_color_format,
                            draw,
                            uniforms,
                            &source_uniforms,
                            &mut upload_operations,
                        )?);
                    }
                    (translucent_draws, Some(translucent_pack_resources))
                } else {
                    (Vec::new(), None)
                };
            Ok(PreparedNamedSourceDistantHorizonsFramePlan {
                submission: staged.submission,
                target,
                depth_targets: staged.depth_targets,
                draws,
                pack_resources,
                exact_atlas_draws,
                translucent_draws,
                translucent_pack_resources,
                upload_operations,
            })
        })();
        if result.is_err() {
            // This helper owns only the DH depth/upload half. Its caller owns
            // the shared color generation and decides whether normal terrain
            // can continue or the complete source frame must be discarded.
            self.lod_source_targets.discard_submission(gal);
            self.pending_distant_horizons_source_targets = None;
            self.lod_gpu_residency.discard_submission(gal);
        }
        result.map(Some)
    }

    /// Records the actual selected-source DH material contract for one
    /// diagnostic frame. The selected pack program may legally consume the
    /// reduced DH stream. Provenance-resolved atlas ranges are executed only
    /// when that program explicitly declares an atlas-backed material input;
    /// both facts are reported so a capture cannot mistake prepared atlas data
    /// for an executed draw.
    fn write_selected_source_distant_horizons_material_receipt(
        &self,
        frame: &WorldPrimitiveFrame,
        opaque_program: &LoweredDistantHorizonsSourceProgram,
        late_translucent_program: Option<&LoweredDistantHorizonsSourceProgram>,
        opaque_draw_count: usize,
        opaque_index_count: u64,
        transparent_draw_count: usize,
        transparent_index_count: u64,
        water_draw_count: usize,
        water_index_count: u64,
        water_origins: &[[i32; 3]],
        late_translucent_draw_count: usize,
        late_translucent_index_count: u64,
        exact_atlas_draw_count: usize,
        exact_atlas_index_count: u64,
    ) {
        if !self.source_execution_enabled()
            || !matches!(
                std::env::var("MATTMC_GRAPHICS_AUDIT")
                    .as_deref()
                    .map(str::trim),
                Ok("1") | Ok("true") | Ok("TRUE")
            )
        {
            return;
        }
        let Some(dir) = std::env::var_os("MATTMC_TERRAIN_PASS_CONTRACT_DIAGNOSTIC_DIR") else {
            return;
        };
        let bindings = opaque_program
            .opaque_resource_bindings
            .bindings()
            .iter()
            .map(|binding| {
                format!(
                    "{{\"source_name\":\"{}\",\"semantic_role\":\"{}\",\"kind\":\"{:?}\"}}",
                    json_escape(binding.resource_name()),
                    json_escape(binding.role().semantic_name()),
                    binding.kind(),
                )
            })
            .collect::<Vec<_>>();
        let atlas_bound = opaque_program
            .opaque_resource_bindings
            .bindings()
            .iter()
            .any(|binding| matches!(binding.role(), TerrainSourceResourceRole::MaterialAtlas));
        let exact_atlas_segments_available = self
            .lod_textured_gpu_column_assets
            .values()
            .map(|asset| asset.segments.len() as u64)
            .sum::<u64>();
        let texture_identity_contract = if exact_atlas_draw_count > 0 && atlas_bound {
            "mixed-exact-atlas-and-pack-atlas"
        } else if exact_atlas_draw_count > 0 {
            "mixed-exact-atlas-and-reduced-color"
        } else if atlas_bound {
            "atlas-backed"
        } else {
            "reduced-color-material-category"
        };
        // Audit-only: prove a requested DH fragment probe reached the exact
        // lowered program about to be compiled, rather than a stale process.
        let fragment_probe = opaque_program
            .fragment
            .source
            .split("selected-source DH diagnostic probe: ")
            .nth(1)
            .and_then(|suffix| suffix.split_whitespace().next())
            .unwrap_or("none");
        let path = Path::new(&dir).join(format!(
            "world-lod-selected-source-material-contract-frame-{}.json",
            frame.frame_id
        ));
        if std::fs::create_dir_all(&dir).is_ok() {
            let _ = std::fs::write(
                path,
                format!(
                    concat!(
                        "{{\"frame_id\":{},\"world_generation\":{},\"program\":\"{}\",",
                        "\"pass_kind\":\"{:?}\",\"late_translucent_program\":{},",
                        "\"late_translucent_pass_kind\":{},\"vertex_stride\":{},",
                        "\"texture_identity_contract\":\"{}\",\"material_atlas_bound\":{},",
                        "\"opaque_draw_count\":{},\"opaque_index_count\":{},",
                        "\"exact_atlas_draw_count\":{},\"exact_atlas_index_count\":{},",
                        "\"transparent_draw_count\":{},\"transparent_index_count\":{},",
                        "\"water_draw_count\":{},\"water_index_count\":{},",
                        "\"water_origins\":[{}],",
                        "\"late_translucent_draw_count\":{},\"late_translucent_index_count\":{},",
                        "\"exact_atlas_segments_available\":{},",
                        "\"fragment_probe\":\"{}\",",
                        "\"resource_bindings\":[{}]}}"
                    ),
                    frame.frame_id,
                    frame.shader_environment.world_generation,
                    json_escape(opaque_program.identity.as_str()),
                    opaque_program.pass_kind,
                    late_translucent_program
                        .map(|program| format!("\"{}\"", json_escape(program.identity.as_str())))
                        .unwrap_or_else(|| "null".to_string()),
                    late_translucent_program
                        .map(|program| format!("\"{:?}\"", program.pass_kind))
                        .unwrap_or_else(|| "null".to_string()),
                    opaque_program.execution_interface.vertex_stride,
                    texture_identity_contract,
                    atlas_bound,
                    opaque_draw_count,
                    opaque_index_count,
                    exact_atlas_draw_count,
                    exact_atlas_index_count,
                    transparent_draw_count,
                    transparent_index_count,
                    water_draw_count,
                    water_index_count,
                    water_origins
                        .iter()
                        .take(16)
                        .map(|origin| format!("[{},{},{}]", origin[0], origin[1], origin[2]))
                        .collect::<Vec<_>>()
                        .join(","),
                    late_translucent_draw_count,
                    late_translucent_index_count,
                    exact_atlas_segments_available,
                    json_escape(fragment_probe),
                    bindings.join(","),
                ),
            );
        }
    }

    /// Captures a bounded decode of the *actual* compact DH stream selected
    /// for a source-program frame. This is deliberately emitted before the
    /// private source pass expands it into commands, so an incorrect color,
    /// light, material category, or normal cannot be mistaken for an atlas
    /// lookup problem later in the shader graph. It is audit-only and never
    /// participates in route selection or rendering.
    fn write_selected_source_distant_horizons_stream_receipt(
        &self,
        frame: &WorldPrimitiveFrame,
        program: &LoweredDistantHorizonsSourceProgram,
    ) {
        if !self.source_execution_enabled()
            || !matches!(
                std::env::var("MATTMC_GRAPHICS_AUDIT")
                    .as_deref()
                    .map(str::trim),
                Ok("1") | Ok("true") | Ok("TRUE")
            )
        {
            return;
        }
        let Some(dir) = std::env::var_os("MATTMC_TERRAIN_PASS_CONTRACT_DIAGNOSTIC_DIR") else {
            return;
        };

        const SAMPLE_LIMIT: usize = 48;
        let mut samples = Vec::new();
        let mut sampled_categories = BTreeSet::new();
        let mut seen_segments = BTreeSet::new();
        for instance in &frame.lod_instances {
            let segment_key = (
                instance.column_key,
                instance.column_generation,
                instance.layer,
                instance.segment_index,
            );
            if !seen_segments.insert(segment_key) {
                continue;
            }
            let Some(column) = self.lod_gpu_column_assets.get(&instance.column_key) else {
                continue;
            };
            if column.column_generation != instance.column_generation {
                continue;
            }
            let Some(segment) = column.segments.get(instance.segment_index as usize) else {
                continue;
            };
            if segment.layer != instance.layer
                || segment.vertex_layout_version != lod::WORLD_LOD_GPU_VERTEX_LAYOUT_V1
                || segment.vertex_bytes.len() % lod::WORLD_LOD_GPU_VERTEX_BYTES != 0
            {
                continue;
            }
            for (vertex_index, vertex) in segment
                .vertex_bytes
                .chunks_exact(lod::WORLD_LOD_GPU_VERTEX_BYTES)
                .enumerate()
            {
                let material = vertex[30];
                // Keep one representative for every coarse DH category, then
                // retain a few additional vertices only while the receipt is
                // still small. This avoids a single far column hiding every
                // other semantic material in a capture.
                if samples.len() >= SAMPLE_LIMIT
                    || (!sampled_categories.insert(material) && samples.len() >= 16)
                {
                    continue;
                }
                let local = [
                    f32::from_le_bytes(vertex[0..4].try_into().expect("fixed LOD vertex x")),
                    f32::from_le_bytes(vertex[4..8].try_into().expect("fixed LOD vertex y")),
                    f32::from_le_bytes(vertex[8..12].try_into().expect("fixed LOD vertex z")),
                ];
                let micro = [
                    f32::from_le_bytes(vertex[12..16].try_into().expect("fixed LOD micro x")),
                    f32::from_le_bytes(vertex[16..20].try_into().expect("fixed LOD micro y")),
                    f32::from_le_bytes(vertex[20..24].try_into().expect("fixed LOD micro z")),
                ];
                let color = [vertex[24], vertex[25], vertex[26], vertex[27]];
                let sky_light = vertex[28];
                let block_light = vertex[29];
                let normal = vertex[31];
                samples.push(format!(
                    concat!(
                        "{{\"columnKey\":{},\"columnGeneration\":{},\"layer\":{},\"segment\":{},\"vertex\":{},",
                        "\"local\":[{:.3},{:.3},{:.3}],\"micro\":[{:.3},{:.3},{:.3}],",
                        "\"world\":[{:.3},{:.3},{:.3}],\"rgba\":[{},{},{},{}],",
                        "\"skyLight\":{},\"blockLight\":{},\"materialCategory\":{},\"normalIndex\":{}}}"
                    ),
                    instance.column_key,
                    instance.column_generation,
                    instance.layer,
                    instance.segment_index,
                    vertex_index,
                    local[0],
                    local[1],
                    local[2],
                    micro[0],
                    micro[1],
                    micro[2],
                    local[0] + micro[0] + column.origin[0] as f32,
                    local[1] + micro[1] + column.origin[1] as f32,
                    local[2] + micro[2] + column.origin[2] as f32,
                    color[0],
                    color[1],
                    color[2],
                    color[3],
                    sky_light,
                    block_light,
                    material,
                    normal,
                ));
                if samples.len() >= SAMPLE_LIMIT {
                    break;
                }
            }
            if samples.len() >= SAMPLE_LIMIT {
                break;
            }
        }
        let path = Path::new(&dir).join(format!(
            "world-lod-selected-source-stream-frame-{}.json",
            frame.frame_id
        ));
        if std::fs::create_dir_all(&dir).is_ok() {
            let _ = std::fs::write(
                path,
                format!(
                    concat!(
                        "{{\"frame_id\":{},\"world_generation\":{},\"program\":\"{}\",",
                        "\"vertex_stride\":{},\"contract\":\"{:?}\",\"samples\":[{}]}}"
                    ),
                    frame.frame_id,
                    frame.shader_environment.world_generation,
                    json_escape(program.identity.as_str()),
                    lod::WORLD_LOD_GPU_VERTEX_BYTES,
                    program.execution_interface.material_identity_contract,
                    samples.join(","),
                ),
            );
        }
    }

    /// Captures the source-program position contract for a bounded set of
    /// *executed* coarse DH draws. The selected source shader receives a
    /// camera-relative local position plus the per-column model offset, then
    /// applies DH's copied projection and model-view matrices. Recording both
    /// multiplication forms catches a semantic camera/origin fault before a
    /// screenshot is blamed on material data or later composition.
    fn write_distant_horizons_transform_receipt(
        &self,
        frame: &WorldPrimitiveFrame,
        scope: &str,
        program_identity: &str,
        draws: &[lod::WorldLodGpuDraw],
    ) {
        if !matches!(
            std::env::var("MATTMC_GRAPHICS_AUDIT")
                .as_deref()
                .map(str::trim),
            Ok("1") | Ok("true") | Ok("TRUE")
        ) {
            return;
        }
        let Some(dir) = std::env::var_os("MATTMC_TERRAIN_PASS_CONTRACT_DIAGNOSTIC_DIR") else {
            return;
        };

        const SAMPLE_LIMIT: usize = 24;
        let camera = frame.lod_render_frame.camera_world_position;
        let combined_from_parts = matrix4_column_major_multiply(
            frame.lod_render_frame.projection_matrix,
            frame.lod_render_frame.model_view_matrix,
        );
        let mut samples = Vec::new();
        for draw in draws {
            if samples.len() >= SAMPLE_LIMIT {
                break;
            }
            let Some(column) = self.lod_gpu_column_assets.get(&draw.column_key) else {
                continue;
            };
            if column.column_generation != draw.column_generation {
                continue;
            }
            let Some(segment) = column.segments.get(draw.segment_index as usize) else {
                continue;
            };
            if segment.layer != draw.layer
                || segment.vertex_layout_version != lod::WORLD_LOD_GPU_VERTEX_LAYOUT_V1
                || segment.vertex_bytes.len() < lod::WORLD_LOD_GPU_VERTEX_BYTES
            {
                continue;
            }
            // A water surface is the one DH stream where a first-vertex-only
            // receipt cannot establish its projected orientation. Keep this
            // bounded, but retain each vertex of its first two quads.
            let sampled_vertices = if draw.layer == WORLD_LOD_LAYER_TRANSPARENT_WATER_UP {
                (segment.vertex_bytes.len() / lod::WORLD_LOD_GPU_VERTEX_BYTES).min(8)
            } else {
                1
            };
            for vertex_index in 0..sampled_vertices {
                if samples.len() >= SAMPLE_LIMIT {
                    break;
                }
                let vertex_start = vertex_index * lod::WORLD_LOD_GPU_VERTEX_BYTES;
                let vertex = &segment.vertex_bytes
                    [vertex_start..vertex_start + lod::WORLD_LOD_GPU_VERTEX_BYTES];
                let local = [
                    f32::from_le_bytes(vertex[0..4].try_into().expect("fixed LOD vertex x")),
                    f32::from_le_bytes(vertex[4..8].try_into().expect("fixed LOD vertex y")),
                    f32::from_le_bytes(vertex[8..12].try_into().expect("fixed LOD vertex z")),
                ];
                let micro = [
                    f32::from_le_bytes(vertex[12..16].try_into().expect("fixed LOD micro x")),
                    f32::from_le_bytes(vertex[16..20].try_into().expect("fixed LOD micro y")),
                    f32::from_le_bytes(vertex[20..24].try_into().expect("fixed LOD micro z")),
                ];
                // Iris's DH transformer decodes all micro fields but applies only
                // X/Z to the final terrain position. Preserve that exact semantic
                // contract here rather than treating the compact stream as a
                // generic three-axis offset.
                let model_offset = [
                    draw.origin[0] as f32 - camera[0],
                    draw.origin[1] as f32 - camera[1],
                    draw.origin[2] as f32 - camera[2],
                ];
                let shader_position = [
                    local[0] + micro[0] + model_offset[0],
                    local[1] + model_offset[1],
                    local[2] + micro[2] + model_offset[2],
                    1.0,
                ];
                let model_view = matrix4_column_major_transform_point(
                    frame.lod_render_frame.model_view_matrix,
                    shader_position,
                );
                let clip_from_parts = matrix4_column_major_transform_point(
                    frame.lod_render_frame.projection_matrix,
                    model_view,
                );
                let clip_from_frame = matrix4_column_major_transform_point(
                    frame.lod_render_frame.combined_matrix,
                    shader_position,
                );
                let clip_from_derived =
                    matrix4_column_major_transform_point(combined_from_parts, shader_position);
                let ndc = matrix4_ndc(clip_from_parts);
                samples.push(format!(
                concat!(
                    "{{\"columnKey\":{},\"columnGeneration\":{},\"layer\":{},\"segment\":{},\"vertexIndex\":{},\"quadIndex\":{},",
                    "\"origin\":[{},{},{}],\"camera\":[{:.3},{:.3},{:.3}],",
                    "\"local\":[{:.3},{:.3},{:.3}],\"micro\":[{:.3},{:.3},{:.3}],",
                    "\"modelOffset\":[{:.3},{:.3},{:.3}],\"shaderPosition\":[{:.3},{:.3},{:.3},{:.3}],",
                    "\"modelView\":[{:.6},{:.6},{:.6},{:.6}],\"clip\":[{:.6},{:.6},{:.6},{:.6}],",
                    "\"frameCombinedClip\":[{:.6},{:.6},{:.6},{:.6}],",
                    "\"derivedCombinedClip\":[{:.6},{:.6},{:.6},{:.6}],",
                    "\"frameVsPartsMaxAbsError\":{:.8},\"derivedVsPartsMaxAbsError\":{:.8},",
                    "\"ndc\":{} }}"
                ),
                draw.column_key,
                draw.column_generation,
                draw.layer,
                draw.segment_index,
                vertex_index,
                vertex_index / 4,
                draw.origin[0],
                draw.origin[1],
                draw.origin[2],
                camera[0],
                camera[1],
                camera[2],
                local[0],
                local[1],
                local[2],
                micro[0],
                micro[1],
                micro[2],
                model_offset[0],
                model_offset[1],
                model_offset[2],
                shader_position[0],
                shader_position[1],
                shader_position[2],
                shader_position[3],
                model_view[0],
                model_view[1],
                model_view[2],
                model_view[3],
                clip_from_parts[0],
                clip_from_parts[1],
                clip_from_parts[2],
                clip_from_parts[3],
                clip_from_frame[0],
                clip_from_frame[1],
                clip_from_frame[2],
                clip_from_frame[3],
                clip_from_derived[0],
                clip_from_derived[1],
                clip_from_derived[2],
                clip_from_derived[3],
                vector4_max_abs_difference(clip_from_frame, clip_from_parts),
                vector4_max_abs_difference(clip_from_derived, clip_from_parts),
                matrix4_ndc_json(ndc),
            ));
            }
        }
        let path = Path::new(&dir).join(format!(
            "world-lod-{}-transform-frame-{}.json",
            scope, frame.frame_id
        ));
        if std::fs::create_dir_all(&dir).is_ok() {
            let _ = std::fs::write(
                path,
                format!(
                    concat!(
                        "{{\"frame_id\":{},\"world_generation\":{},\"scope\":\"{}\",\"program\":\"{}\",",
                        "\"drawCount\":{},\"camera\":[{:.3},{:.3},{:.3}],",
                        "\"projectionModelViewMaxAbsError\":{:.8},\"samples\":[{}]}}"
                    ),
                    frame.frame_id,
                    frame.shader_environment.world_generation,
                    json_escape(scope),
                    json_escape(program_identity),
                    draws.len(),
                    camera[0],
                    camera[1],
                    camera[2],
                    matrix4_max_abs_difference(
                        frame.lod_render_frame.combined_matrix,
                        combined_from_parts,
                    ),
                    samples.join(","),
                ),
            );
        }
    }

    /// Records the exact lowered fullscreen chain attached to one selected
    /// source frame. This is a bounded source-contract receipt: it exposes
    /// semantic stage/resource identities only, never attachments, native
    /// descriptors, or backend state. It lets a real gameplay capture isolate
    /// the first consumer that can change an already-valid DH primary target.
    fn write_selected_source_fullscreen_chain_receipt(
        &self,
        frame: &WorldPrimitiveFrame,
        programs: &[LoweredFullscreenSourceProgram],
    ) {
        if !self.source_execution_enabled()
            || !matches!(
                std::env::var("MATTMC_GRAPHICS_AUDIT")
                    .as_deref()
                    .map(str::trim),
                Ok("1") | Ok("true") | Ok("TRUE")
            )
        {
            return;
        }
        let Some(dir) = std::env::var_os("MATTMC_TERRAIN_PASS_CONTRACT_DIAGNOSTIC_DIR") else {
            return;
        };
        let stages = programs
            .iter()
            .map(|program| {
                let outputs = program
                    .outputs
                    .iter()
                    .map(|output| {
                        format!(
                            "{{\"location\":{},\"semantic_role\":\"{}\"}}",
                            output.source_location(),
                            json_escape(&output.role().diagnostic_name()),
                        )
                    })
                    .collect::<Vec<_>>();
                let inputs = program
                    .opaque_resource_bindings
                    .bindings()
                    .iter()
                    .map(|binding| {
                        format!(
                            "{{\"source_name\":\"{}\",\"semantic_role\":\"{}\",\"kind\":\"{:?}\"}}",
                            json_escape(binding.resource_name()),
                            json_escape(&binding.role().diagnostic_name()),
                            binding.kind(),
                        )
                    })
                    .collect::<Vec<_>>();
                let feedback = program
                    .feedback_requirements
                    .iter()
                    .map(|requirement| {
                        format!(
                            "{{\"semantic_role\":\"{}\",\"sampled_binding\":{},\"output_location\":{}}}",
                            json_escape(&requirement.role.diagnostic_name()),
                            requirement.sampled_binding,
                            requirement.output_location,
                        )
                    })
                    .collect::<Vec<_>>();
                let mipmaps = program
                    .mipmap_requirements
                    .iter()
                    .map(|requirement| {
                        format!(
                            "{{\"semantic_role\":\"{}\",\"sampled_binding\":{}}}",
                            json_escape(&requirement.role.diagnostic_name()),
                            requirement.sampled_binding,
                        )
                    })
                    .collect::<Vec<_>>();
                format!(
                    concat!(
                        "{{\"identity\":\"{}\",\"source_stage\":\"{}\",",
                        "\"outputs\":[{}],\"inputs\":[{}],\"feedback\":[{}],\"mipmap_samples\":[{}]}}"
                    ),
                    json_escape(program.identity.as_str()),
                    json_escape(&program.source_stage_path),
                    outputs.join(","),
                    inputs.join(","),
                    feedback.join(","),
                    mipmaps.join(","),
                )
            })
            .collect::<Vec<_>>();
        let path = Path::new(&dir).join(format!(
            "selected-source-fullscreen-chain-frame-{}.json",
            frame.frame_id
        ));
        if std::fs::create_dir_all(&dir).is_ok() {
            let _ = std::fs::write(
                path,
                format!(
                    "{{\"frame_id\":{},\"world_generation\":{},\"stages\":[{}]}}",
                    frame.frame_id,
                    frame.shader_environment.world_generation,
                    stages.join(","),
                ),
            );
        }
    }

    /// Makes an explicitly requested source probe observable at the lowered
    /// program boundary. A stage image alone cannot distinguish an inactive
    /// source branch from a probe that was never compiled into the program.
    fn write_selected_source_fullscreen_probe_receipt(
        &self,
        frame: &WorldPrimitiveFrame,
        programs: &[LoweredFullscreenSourceProgram],
    ) {
        let Ok(mode) = std::env::var("MATTMC_RUST_SELECTED_SOURCE_FULLSCREEN_PROBE") else {
            return;
        };
        let mode = mode.trim();
        if mode.is_empty()
            || !self.source_execution_enabled()
            || !matches!(
                std::env::var("MATTMC_GRAPHICS_AUDIT")
                    .as_deref()
                    .map(str::trim),
                Ok("1") | Ok("true") | Ok("TRUE")
            )
        {
            return;
        }
        let Some(dir) = std::env::var_os("MATTMC_TERRAIN_PASS_CONTRACT_DIAGNOSTIC_DIR") else {
            return;
        };
        let Some(program) = programs.iter().find(|program| {
            program
                .source_stage_path
                .replace('\\', "/")
                .ends_with("world0/deferred1.fsh")
        }) else {
            return;
        };
        let source = &program.fragment.source;
        let hash = source
            .as_bytes()
            .iter()
            .fold(0xcbf2_9ce4_8422_2325_u64, |hash, byte| {
                (hash ^ u64::from(*byte)).wrapping_mul(0x0000_0100_0000_01b3)
            });
        let marker = format!("selected-source fullscreen diagnostic probe: {mode}");
        let dir = Path::new(&dir);
        if std::fs::create_dir_all(dir).is_err() {
            return;
        }
        let _ = std::fs::write(
            dir.join("selected-source-fullscreen-probe-receipt.json"),
            format!(
                concat!(
                    "{{\"frame_id\":{},\"mode\":\"{}\",\"program\":\"{}\",",
                    "\"source_stage_path\":\"{}\",\"fragment_bytes\":{},",
                    "\"fragment_hash\":\"{:016x}\",\"marker_present\":{},",
                    "\"dh_depth_binding_present\":{}}}"
                ),
                frame.frame_id,
                json_escape(mode),
                json_escape(program.identity.as_str()),
                json_escape(&program.source_stage_path),
                source.len(),
                hash,
                source
                    .as_bytes()
                    .windows(marker.len())
                    .any(|window| window == marker.as_bytes()),
                source
                    .as_bytes()
                    .windows(b"dhDepthTex".len())
                    .any(|window| window == b"dhDepthTex"),
            ),
        );
    }

    /// Retains the pre-terrain sky decision separately from the post-terrain
    /// fullscreen chain. The latter intentionally never included sky, which
    /// made a real selected-source capture unable to distinguish a missing sky
    /// program from a successfully staged pre-terrain writer.
    fn write_selected_source_sky_receipt(
        &self,
        frame: &WorldPrimitiveFrame,
        sky: &[PreparedNamedSourceFullscreenConsumer],
    ) {
        if !self.source_execution_enabled()
            || !matches!(
                std::env::var("MATTMC_GRAPHICS_AUDIT")
                    .as_deref()
                    .map(str::trim),
                Ok("1") | Ok("true") | Ok("TRUE")
            )
        {
            return;
        }
        let Some(dir) = std::env::var_os("MATTMC_TERRAIN_PASS_CONTRACT_DIAGNOSTIC_DIR") else {
            return;
        };
        let stages = sky
            .iter()
            .map(|sky| {
                format!(
                    "{{\"identity\":\"{}\",\"source_stage\":\"{}\"}}",
                    json_escape(sky.program.identity.as_str()),
                    json_escape(&sky.program.source_stage_path),
                )
            })
            .collect::<Vec<_>>()
            .join(",");
        let path = Path::new(&dir).join(format!(
            "selected-source-pre-terrain-sky-frame-{}.json",
            frame.frame_id
        ));
        if std::fs::create_dir_all(&dir).is_ok() {
            let _ = std::fs::write(
                path,
                format!(
                    concat!(
                        "{{\"frame_id\":{},\"world_generation\":{},",
                        "\"requested\":{},\"sky_visible\":{},\"sky_type\":{},",
                        "\"staged\":[{}]}}"
                    ),
                    frame.frame_id,
                    frame.shader_environment.world_generation,
                    source_sky_initializer_requested(frame),
                    frame.background.sky.visible,
                    frame.background.sky_type,
                    stages,
                ),
            );
        }
    }

    /// Stages the complete pack-declared fullscreen chain once every terrain
    /// writer has contributed its generation-coherent semantic inputs. Normal
    /// terrain owns this scheduling boundary; Distant Horizons may add depth
    /// resources but never gains a private composite or presentation path.
    fn prepare_complete_named_source_fullscreen_consumers(
        &mut self,
        gal: &mut VulkanicGal,
        frame: &WorldPrimitiveFrame,
        color_targets: &ShaderPackColorTargets,
        main_depth_resources: TerrainSourceOwnedResourceSet,
        distant_horizons: Option<&PreparedNamedSourceDistantHorizonsFramePlan>,
    ) -> GalResult<Vec<PreparedNamedSourceFullscreenConsumer>> {
        let shader_pack_generation = color_targets.identity.shader_pack_generation;
        let world_generation = color_targets.identity.world_generation;
        let source_snapshot = self
            .candidate_source_resource_snapshot_for_frame(
                shader_pack_generation,
                world_generation,
                frame.frame_id,
            )?
            .resources
            .excluding_roles([TerrainSourceResourceRole::MainDepth])?;
        let mut external_inputs = vec![source_snapshot.clone()];
        let mut accumulated = source_snapshot;
        let exact_main_depth_availability = main_depth_resources
            .availability()
            .resource_for(TerrainSourceResourceRole::MainDepth);
        let mut append_unique = |resources: TerrainSourceOwnedResourceSet| -> GalResult<()> {
            let unique = resources.excluding_roles_already_owned_by(&accumulated)?;
            if unique.len() != 0 {
                accumulated = TerrainSourceOwnedResourceSet::merge([&accumulated, &unique])?;
                external_inputs.push(unique);
            }
            Ok(())
        };
        append_unique(main_depth_resources)?;
        if let Some(distant_horizons) = distant_horizons {
            append_unique(distant_horizons.depth_targets.semantic_resources()?)?;
        }
        if matches!(
            std::env::var("MATTMC_RUST_SOURCE_DEPTH_TRACE").as_deref(),
            Ok("1") | Ok("true") | Ok("TRUE")
        ) {
            eprintln!(
                "[MattMC source-depth-trace] fullscreen main-depth sampler={:?} available={:?} exact_resources={:?}",
                accumulated
                    .combined_sampler_for(TerrainSourceResourceRole::MainDepth)
                    .map(Handle::raw),
                accumulated
                    .availability()
                    .resource_for(TerrainSourceResourceRole::MainDepth),
                exact_main_depth_availability,
            );
        }

        let source_uses_distant_horizons = distant_horizons.is_some();
        let programs = {
            let runtime = self.shader_runtime.as_ref().ok_or_else(|| {
                GalError::backend("shader runtime vanished before complete fullscreen staging")
            })?;
            if source_uses_distant_horizons {
                runtime.prepared_lowered_distant_horizons_post_terrain_fullscreen_programs()?
            } else {
                runtime.prepared_lowered_post_terrain_fullscreen_programs()?
            }
            .into_iter()
            .cloned()
            .collect::<Vec<_>>()
        };
        self.write_selected_source_fullscreen_chain_receipt(frame, &programs);
        self.write_selected_source_fullscreen_probe_receipt(frame, &programs);
        let mut source_uniforms = self.source_uniform_frame_for_owned_resources(frame)?;
        if source_uses_distant_horizons {
            // The shared post-terrain source stages reconstruct ordinary
            // pixels through the normal gbuffer matrices, but reconstruct DH
            // pixels from the separate copied DH depth image. Keep those
            // coordinate systems independent and supply the exact projection
            // pair that created that depth image.
            apply_distant_horizons_fullscreen_projection(
                &mut source_uniforms,
                &frame.lod_render_frame,
            )?;
        }
        let frames = programs
            .iter()
            .map(|program| {
                let scalar_uniforms = program.pack_scalar_uniforms(&source_uniforms)?;
                self.write_selected_source_fullscreen_uniform_receipt(
                    frame.frame_id,
                    program,
                    &scalar_uniforms,
                );
                self.write_selected_source_fullscreen_program_receipt(frame.frame_id, program);
                Ok(FullscreenSourcePassFrame {
                    texture_transforms: program.pack_texture_transforms(
                        &TerrainSourceTextureTransforms::canonical_minecraft_terrain(),
                    )?,
                    scalar_uniforms,
                    texture_transform_before: TextureUsageState::Undefined,
                    scalar_uniform_before: program
                        .execution_interface
                        .scalar_uniforms
                        .map(|_| TextureUsageState::Undefined),
                    clear_values: ShaderPackColorBootstrapClearValues {
                        fog_color: background_clear_color(&frame.background),
                    },
                    color_attachment_before: Vec::new(),
                })
            })
            .collect::<GalResult<Vec<_>>>()?;
        let runtime = self.shader_runtime.as_ref().ok_or_else(|| {
            GalError::backend("shader runtime vanished while staging complete fullscreen chain")
        })?;
        let plans = if source_uses_distant_horizons {
            runtime.stage_distant_horizons_complete_post_terrain_execution_plans(
                gal,
                color_targets,
                &external_inputs,
                color_targets.identity.extent,
            )?
        } else {
            runtime.stage_complete_post_terrain_execution_plans(
                gal,
                color_targets,
                &external_inputs,
                color_targets.identity.extent,
            )?
        };
        if programs.len() != plans.len() || programs.len() != frames.len() {
            destroy_named_source_fullscreen_consumers(
                gal,
                programs
                    .into_iter()
                    .zip(plans)
                    .zip(frames)
                    .map(
                        |((program, plan), frame)| PreparedNamedSourceFullscreenConsumer {
                            program,
                            plan,
                            frame,
                        },
                    ),
            );
            return Err(GalError::backend(
                "complete source fullscreen program, frame-data, and execution-plan counts diverged",
            ));
        }
        Ok(programs
            .into_iter()
            .zip(plans)
            .zip(frames)
            .map(
                |((program, plan), frame)| PreparedNamedSourceFullscreenConsumer {
                    program,
                    plan,
                    frame,
                },
            )
            .collect())
    }

    /// Stages the optional source-defined sky initializer over the exact
    /// Rust-owned named-color generation for this frame. The caller appends
    /// it after the bootstrap clear and before terrain, which makes the sky a
    /// normal source writer instead of a Java/Iris target dependency.
    fn prepare_pre_terrain_source_sky_consumer(
        &mut self,
        gal: &mut VulkanicGal,
        frame: &WorldPrimitiveFrame,
        color_targets: &ShaderPackColorTargets,
        main_depth_resources: &TerrainSourceOwnedResourceSet,
    ) -> GalResult<Option<PreparedNamedSourceFullscreenConsumer>> {
        if !source_sky_initializer_requested(frame) {
            return Ok(None);
        }
        let source_snapshot = self
            .candidate_source_resource_snapshot_for_frame(
                color_targets.identity.shader_pack_generation,
                color_targets.identity.world_generation,
                frame.frame_id,
            )?
            .resources
            .clone();
        let (program, plan) = {
            let runtime = self.shader_runtime.as_ref().ok_or_else(|| {
                GalError::backend("shader runtime vanished before source sky staging")
            })?;
            let Some(program) = runtime.prepared_lowered_pre_terrain_sky_program()? else {
                return Ok(None);
            };
            let unique_main_depth =
                main_depth_resources.excluding_roles_already_owned_by(&source_snapshot)?;
            let inputs = if unique_main_depth.len() == 0 {
                source_snapshot.clone()
            } else {
                TerrainSourceOwnedResourceSet::merge([&source_snapshot, &unique_main_depth])?
            };
            let plan = runtime.stage_pre_terrain_sky_execution_plan(
                gal,
                color_targets,
                std::slice::from_ref(&inputs),
                color_targets.identity.extent,
            )?;
            (program.clone(), plan)
        };
        let Some(plan) = plan else {
            return Ok(None);
        };
        let source_uniforms = self.source_uniform_frame_for_owned_resources(frame)?;
        let scalar_uniforms = program.pack_scalar_uniforms(&source_uniforms)?;
        self.write_selected_source_sky_uniform_receipt(
            frame.frame_id,
            program.identity.as_str(),
            &program.execution_interface.scalar_uniform_fields,
            &scalar_uniforms,
        );
        self.write_selected_source_sky_program_receipt(frame.frame_id, &program);
        let frame = FullscreenSourcePassFrame {
            texture_transforms: program.pack_texture_transforms(
                &TerrainSourceTextureTransforms::canonical_minecraft_terrain(),
            )?,
            scalar_uniforms,
            texture_transform_before: TextureUsageState::Undefined,
            scalar_uniform_before: program
                .execution_interface
                .scalar_uniforms
                .map(|_| TextureUsageState::Undefined),
            clear_values: ShaderPackColorBootstrapClearValues {
                fog_color: background_clear_color(&frame.background),
            },
            color_attachment_before: Vec::new(),
        };
        Ok(Some(PreparedNamedSourceFullscreenConsumer {
            program,
            plan,
            frame,
        }))
    }

    /// Stages the source pack's textured vanilla celestial writer twice: once
    /// for the sun and once for the moon. Both draws consume copied vanilla
    /// sky semantics and Rust-owned PNG resources; no Iris object, texture,
    /// or phase is borrowed.
    fn prepare_pre_terrain_source_celestial_consumers(
        &mut self,
        gal: &mut VulkanicGal,
        frame: &WorldPrimitiveFrame,
        color_targets: &ShaderPackColorTargets,
        main_depth_resources: &TerrainSourceOwnedResourceSet,
    ) -> GalResult<Vec<PreparedNamedSourceFullscreenConsumer>> {
        if !source_sky_initializer_requested(frame) {
            return Ok(Vec::new());
        }
        // Candidate preparation is also used by non-executing source tests.
        // A selected source route separately treats these assets as required;
        // here their absence simply keeps the optional writer inert.
        if !self.source_celestial_assets_available() {
            return Ok(Vec::new());
        }
        let source_snapshot = self
            .candidate_source_resource_snapshot_for_frame(
                color_targets.identity.shader_pack_generation,
                color_targets.identity.world_generation,
                frame.frame_id,
            )?
            .resources
            .clone();
        let (program, has_program) = {
            let runtime = self.shader_runtime.as_ref().ok_or_else(|| {
                GalError::backend("shader runtime vanished before source celestial staging")
            })?;
            let program = runtime.prepared_lowered_pre_terrain_celestial_program()?;
            (program.cloned(), program.is_some())
        };
        if !has_program {
            return Ok(Vec::new());
        }
        let program = program.expect("checked source celestial program presence");
        let mut consumers = Vec::with_capacity(2);
        for (is_moon, texture_id) in [
            (false, WORLD_MATERIAL_TEXTURE_SKY_SUN),
            (true, WORLD_MATERIAL_TEXTURE_SKY_MOON_PHASES),
        ] {
            let (resources, _, texture_extent) = self
                .source_resources_with_local_material_texture(
                    gal,
                    program.shader_pack_generation,
                    &source_snapshot,
                    texture_id,
                    frame.frame_id,
                )?;
            let unique_main_depth =
                main_depth_resources.excluding_roles_already_owned_by(&resources)?;
            let merged_resources = if unique_main_depth.len() == 0 {
                resources
            } else {
                TerrainSourceOwnedResourceSet::merge([&resources, &unique_main_depth])?
            };
            let plan = self
                .shader_runtime
                .as_ref()
                .ok_or_else(|| {
                    GalError::backend("shader runtime vanished while staging source celestial")
                })?
                .stage_pre_terrain_celestial_execution_plan(
                    gal,
                    color_targets,
                    std::slice::from_ref(&merged_resources),
                    color_targets.identity.extent,
                )?
                .ok_or_else(|| {
                    GalError::backend(
                        "source celestial program vanished after successful discovery",
                    )
                })?;
            let mut source_uniforms = self.source_uniform_frame_for_owned_resources(frame)?;
            source_uniforms.render_stage = Some(self.source_celestial_render_stage(is_moon)?);
            source_uniforms.celestial_is_moon = Some(i32::from(is_moon));
            source_uniforms.celestial_alpha = Some(frame.background.sky.rain_brightness);
            source_uniforms.moon_phase = Some(frame.background.sky.moon_phase);
            source_uniforms.material_atlas_size = Some(texture_extent);
            let scalar_uniforms = program.pack_scalar_uniforms(&source_uniforms)?;
            self.write_selected_source_sky_uniform_receipt(
                frame.frame_id,
                program.identity.as_str(),
                &program.execution_interface.scalar_uniform_fields,
                &scalar_uniforms,
            );
            self.write_selected_source_sky_program_receipt(frame.frame_id, &program);
            consumers.push(PreparedNamedSourceFullscreenConsumer {
                frame: FullscreenSourcePassFrame {
                    texture_transforms: program.pack_texture_transforms(
                        &TerrainSourceTextureTransforms::canonical_minecraft_terrain(),
                    )?,
                    scalar_uniforms,
                    texture_transform_before: TextureUsageState::Undefined,
                    scalar_uniform_before: program
                        .execution_interface
                        .scalar_uniforms
                        .map(|_| TextureUsageState::Undefined),
                    clear_values: ShaderPackColorBootstrapClearValues {
                        fog_color: background_clear_color(&frame.background),
                    },
                    color_attachment_before: Vec::new(),
                },
                program: program.clone(),
                plan,
            });
        }
        Ok(consumers)
    }

    /// Prepares the currently supported terrain writers as one private source
    /// frame. It accepts ordinary opaque/cutout terrain and optional opaque
    /// Distant Horizons ranges, then stages every scoped fullscreen stage and
    /// a Rust-owned copy to one acquired frame target. It still does not
    /// acquire, present, or select the route.
    ///
    /// The returned plan is intentionally inert until its caller appends it
    /// to one combined submission. On any DH preparation failure, every
    /// normal-terrain reservation and named-color bootstrap is discarded with
    /// the DH staging so no partial source frame can leak into a later route.
    fn prepare_named_source_frame_plan(
        &mut self,
        gal: &mut VulkanicGal,
        programs: &LoweredSourceTerrainPrograms,
        world_generation: u64,
        graph_generation: u64,
        frame: &WorldPrimitiveFrame,
        batches: &[MeshBatch],
        extent: Extent3d,
        depth_texture: Handle,
        depth_view: Handle,
        shadow_targets: TerrainSourceShadowPassTargets,
        main_depth: NamedSourceMainDepthInputs,
        final_frame_target: Handle,
        clear_values: ShaderPackColorBootstrapClearValues,
    ) -> GalResult<PreparedNamedSourceFramePlan> {
        let final_color_attachment = gal.pass_target_color_attachment(final_frame_target)?;
        let shader_pack_generation = programs.opaque.shader_pack_generation;
        let main_depth_resources = self
            .shader_runtime
            .as_mut()
            .ok_or_else(|| {
                GalError::backend("shader runtime vanished before named source depth staging")
            })?
            .ensure_candidate_source_main_depth_resources(
                gal,
                TerrainSourceMainDepthInput {
                    shader_pack_generation,
                    world_generation,
                    shader_graph_generation: main_depth.graph_generation,
                    main_depth_view: main_depth.main_depth_view,
                    before_translucency_view: Some(main_depth.before_translucency_view),
                    previous_view: Some(main_depth.previous_view),
                    sampler: main_depth.sampler,
                },
            )?
            .ok_or_else(|| {
                GalError::unsupported_feature(
                    "named source terrain/DH plan requires Rust-owned main-depth semantic resources",
                )
            })?;
        self.append_candidate_source_frame_resources(
            shader_pack_generation,
            world_generation,
            frame.frame_id,
            std::slice::from_ref(&main_depth_resources),
        )?;
        let source_sky_initializer = if source_sky_initializer_requested(frame) {
            let runtime = self.shader_runtime.as_ref().ok_or_else(|| {
                GalError::backend("shader runtime vanished before source sky discovery")
            })?;
            runtime
                .prepared_lowered_pre_terrain_sky_program()?
                .is_some()
                || runtime
                    .prepared_lowered_pre_terrain_celestial_program()?
                    .is_some()
        } else {
            false
        };
        let mut terrain = self.prepare_named_source_terrain_frame_plan(
            gal,
            programs,
            world_generation,
            graph_generation,
            frame,
            batches,
            extent,
            depth_texture,
            depth_view,
            shadow_targets,
            clear_values,
            source_sky_initializer,
        )?;
        terrain.main_depth_history = Some((
            main_depth.targets,
            TerrainDepthHistoryPlan {
                prior_before_translucency_valid: false,
                prior_previous_valid: false,
                extent,
            },
        ));
        terrain.pre_terrain_sky = match self.prepare_pre_terrain_source_sky_consumer(
            gal,
            frame,
            terrain.color_targets(),
            &main_depth_resources,
        ) {
            Ok(sky) => sky.into_iter().collect(),
            Err(error) => {
                PreparedNamedSourceFramePlan {
                    terrain,
                    distant_horizons: None,
                    fullscreen_consumers: Vec::new(),
                    final_output: None,
                }
                .discard(self, gal);
                return Err(error);
            }
        };
        let celestial = match self.prepare_pre_terrain_source_celestial_consumers(
            gal,
            frame,
            terrain.color_targets(),
            &main_depth_resources,
        ) {
            Ok(consumers) => consumers,
            Err(error) => {
                PreparedNamedSourceFramePlan {
                    terrain,
                    distant_horizons: None,
                    fullscreen_consumers: Vec::new(),
                    final_output: None,
                }
                .discard(self, gal);
                return Err(error);
            }
        };
        terrain.pre_terrain_sky.extend(celestial);
        let color_targets = terrain.color_targets().clone();
        let distant_horizons = match self.prepare_named_source_distant_horizons_frame_plan(
            gal,
            frame,
            color_targets,
        ) {
            Ok(distant_horizons) => distant_horizons,
            Err(error) => {
                PreparedNamedSourceFramePlan {
                    terrain,
                    distant_horizons: None,
                    fullscreen_consumers: Vec::new(),
                    final_output: None,
                }
                .discard(self, gal);
                return Err(error);
            }
        };
        let mut frame_resources = vec![main_depth_resources];
        if let Some(distant_horizons) = distant_horizons.as_ref() {
            frame_resources.push(distant_horizons.depth_targets.semantic_resources()?);
        }
        let merge_result = self.merge_candidate_source_frame_resources(
            shader_pack_generation,
            world_generation,
            frame.frame_id,
            terrain.color_targets(),
            distant_horizons.is_some(),
            &frame_resources,
        );
        if let Err(error) = merge_result {
            PreparedNamedSourceFramePlan {
                terrain,
                distant_horizons,
                fullscreen_consumers: Vec::new(),
                final_output: None,
            }
            .discard(self, gal);
            return Err(error);
        }
        let fullscreen_consumers = match self.prepare_complete_named_source_fullscreen_consumers(
            gal,
            frame,
            terrain.color_targets(),
            frame_resources
                .first()
                .expect("main-depth resources are always present for a complete source plan")
                .clone(),
            distant_horizons.as_ref(),
        ) {
            Ok(consumers) => consumers,
            Err(error) => {
                PreparedNamedSourceFramePlan {
                    terrain,
                    distant_horizons,
                    fullscreen_consumers: Vec::new(),
                    final_output: None,
                }
                .discard(self, gal);
                return Err(error);
            }
        };
        let final_output = match self.source_final_output_cache.reserve(
            gal,
            &fullscreen_consumers
                .last()
                .expect("complete fullscreen staging rejects an empty chain")
                .program,
            terrain.color_targets(),
            final_frame_target,
            final_color_attachment,
            main_depth.main_depth_view,
            main_depth.graph_generation,
        ) {
            Ok(plan) => plan,
            Err(error) => {
                destroy_named_source_fullscreen_consumers(gal, fullscreen_consumers);
                PreparedNamedSourceFramePlan {
                    terrain,
                    distant_horizons,
                    fullscreen_consumers: Vec::new(),
                    final_output: None,
                }
                .discard(self, gal);
                return Err(error);
            }
        };
        self.write_selected_source_sky_receipt(frame, &terrain.pre_terrain_sky);
        Ok(PreparedNamedSourceFramePlan {
            terrain,
            distant_horizons,
            fullscreen_consumers,
            final_output: Some(final_output),
        })
    }

    /// Returns the currently visible static-terrain source meshes with the
    /// exact model transforms used by the frame. This is intentionally a
    /// semantic cache query: it does not allocate GPU resources, record
    /// commands, or select a shader path.
    pub(crate) fn terrain_voxel_source_meshes(
        &mut self,
        frame: &WorldPrimitiveFrame,
    ) -> GalResult<Vec<TerrainVoxelSourceMesh>> {
        let camera_world_position = frame.voxel_volume.camera_world_position;
        if camera_world_position.iter().any(|value| !value.is_finite()) {
            return Err(GalError::invalid_argument(
                "terrain voxel source frame has a non-finite camera world position",
            ));
        }
        let mut seen_meshes = BTreeSet::new();
        let mut result = Vec::new();
        for instance in frame
            .mesh_instances
            .iter()
            .filter(|instance| instance.stratum == WORLD_STRATUM_TERRAIN)
        {
            validate_mesh_instance(instance, frame)?;
            if !seen_meshes.insert(instance.mesh_key) {
                return Err(GalError::invalid_argument(format!(
                    "terrain voxel source frame has duplicate visible mesh {}",
                    instance.mesh_key
                )));
            }
            let source_material_ids = self
                .shader_runtime
                .as_ref()
                .and_then(ShaderPackRuntimeExecutor::candidate_runtime_block_state_material_ids);
            let asset = self
                .mesh_assets
                .get_mut(&instance.mesh_key)
                .ok_or_else(|| {
                    GalError::invalid_argument(format!(
                        "terrain voxel source mesh {} is missing from the asset cache",
                        instance.mesh_key
                    ))
                })?;
            if asset.mesh_generation != instance.mesh_generation {
                return Err(GalError::invalid_argument(format!(
                    "terrain voxel source mesh {} generation {} does not match cached generation {}",
                    instance.mesh_key, instance.mesh_generation, asset.mesh_generation
                )));
            }
            if asset.vertex_layout_version != WORLD_MESH_VERTEX_LAYOUT_V3 {
                return Err(GalError::unsupported_feature(format!(
                    "terrain voxel source mesh {} requires V3 semantic vertices; cached layout is {}",
                    instance.mesh_key, asset.vertex_layout_version
                )));
            }
            let vertices = Arc::clone(asset.terrain_voxel_vertices.get_or_insert_with(|| {
                let SourceMeshSemanticInput::Terrain(input) = asset
                    .source_input
                    .as_ref()
                    .expect("v3 terrain asset keeps immutable semantic source input")
                else {
                    panic!("v3 terrain asset must retain terrain source semantics");
                };
                Arc::new(
                    input
                        .iter()
                        .map(|vertex| TerrainVoxelSourceVertex {
                            position: vertex.position,
                            mid_block_packed: vertex.mid_block_packed,
                            shader_material_id: source_material_ids
                                .as_ref()
                                .and_then(|ids| ids.get(&vertex.shader_block_id))
                                .copied()
                                .unwrap_or(vertex.shader_block_id),
                        })
                        .collect(),
                )
            }));
            let indices = Arc::clone(asset.terrain_voxel_indices.get_or_insert_with(|| {
                Arc::new(
                    decoded_terrain_voxel_indices(&asset.index_bytes, asset.index_type)
                        .expect("validated world mesh indices remain decodable"),
                )
            }));
            let translucent_indices =
                Self::terrain_voxel_translucent_indices(instance.mesh_key, asset, &indices)?;
            result.push(TerrainVoxelSourceMesh {
                mesh_key: instance.mesh_key,
                mesh_generation: instance.mesh_generation,
                vertices,
                indices,
                translucent_indices: Arc::new(translucent_indices),
                // Static terrain instances render in a camera-relative
                // coordinate space. The voxel field is world-addressed, so
                // reconstruct only that semantic origin here; the rendering
                // transform remains untouched for the normal Rust pass.
                transform: Self::world_transform_from_camera_relative(
                    instance.transform,
                    camera_world_position,
                )?,
            });
        }
        for mesh in self.distant_horizons_voxel_source_meshes(frame)? {
            if !seen_meshes.insert(mesh.mesh_key) {
                return Err(GalError::invalid_argument(format!(
                    "terrain voxel source frame has duplicate static/Distant Horizons mesh key {}",
                    mesh.mesh_key
                )));
            }
            result.push(mesh);
        }
        Ok(result)
    }

    /// Converts only generation-bound, per-quad DH material provenance into
    /// the compact semantic geometry consumed by the shared occupancy path.
    /// DH's coarse category is intentionally never used as a substitute for a
    /// block state or atlas identity: unresolved and mixed quads remain out
    /// of this source input rather than acquiring a guessed material.
    fn distant_horizons_voxel_source_meshes(
        &mut self,
        frame: &WorldPrimitiveFrame,
    ) -> GalResult<Vec<TerrainVoxelSourceMesh>> {
        if !frame.lod_render_frame.rust_route_selected() || frame.lod_instances.is_empty() {
            return Ok(Vec::new());
        }
        let Some(runtime) = self.shader_runtime.as_ref() else {
            return Ok(Vec::new());
        };
        if !runtime.has_candidate_material_contract() {
            return Ok(Vec::new());
        }
        let shader_pack_generation = runtime.expected_shader_pack_generation_for_resources();

        let mut seen_columns = BTreeSet::new();
        let mut result = Vec::new();
        for instance in &frame.lod_instances {
            let column_key = instance.column_key;
            let asset = self.lod_column_assets.get(&column_key).ok_or_else(|| {
                GalError::invalid_argument(format!(
                    "terrain voxel source references missing Distant Horizons column {column_key}"
                ))
            })?;
            if asset.column_generation != instance.column_generation {
                return Err(GalError::invalid_argument(format!(
                    "terrain voxel source Distant Horizons column {column_key} generation {} differs from visible generation {}",
                    asset.column_generation, instance.column_generation
                )));
            }
            let provenance = self.lod_material_provenance.get(&column_key).ok_or_else(|| {
                GalError::unsupported_feature(format!(
                    "terrain voxel source Distant Horizons column {column_key} has no generation-bound material provenance"
                ))
            })?;
            let plan = self.lod_textured_column_plans.get(&column_key).ok_or_else(|| {
                GalError::unsupported_feature(format!(
                    "terrain voxel source Distant Horizons column {column_key} has no exact material plan"
                ))
            })?;
            if provenance.column_generation != instance.column_generation
                || plan.column_generation != instance.column_generation
            {
                return Err(GalError::invalid_argument(format!(
                    "terrain voxel source Distant Horizons column {column_key} mixes asset, provenance, or exact-plan generations"
                )));
            }
            let segment = plan
                .segments
                .get(instance.segment_index as usize)
                .ok_or_else(|| {
                    GalError::invalid_argument(format!(
                        "terrain voxel source Distant Horizons column {column_key} is missing visible segment {}",
                        instance.segment_index
                    ))
                })?;
            if segment.layer != instance.layer {
                return Err(GalError::invalid_argument(
                    "terrain voxel source Distant Horizons visible layer differs from its exact material plan",
                ));
            }

            let cache_key = (column_key, instance.segment_index);
            if let Some(entry) = self.lod_voxel_source_meshes.get(&cache_key) {
                if entry.shader_pack_generation == shader_pack_generation
                    && entry.mesh.mesh_generation == instance.column_generation
                    && entry.world_y_offset == frame.lod_render_frame.world_y_offset
                {
                    result.push(entry.mesh.clone());
                    continue;
                }
            }

            let mut vertices = Vec::with_capacity(segment.quads.len().saturating_mul(4));
            let mut indices = Vec::with_capacity(segment.quads.len().saturating_mul(6));
            for quad in &segment.quads {
                let identity = provenance
                    .identities
                    .get(quad.material_id.saturating_sub(1) as usize)
                    .ok_or_else(|| {
                        GalError::invalid_argument(format!(
                            "terrain voxel source Distant Horizons column {column_key} quad {} references material {} outside its provenance table",
                            quad.quad_index, quad.material_id
                        ))
                    })?;
                let shader_material_id = self
                    .shader_runtime
                    .as_ref()
                    .expect("source candidate remains present while building its semantic occupancy")
                    .candidate_material_id_for_block_state_identity(&identity.block_state_identity)
                    .ok_or_else(|| {
                        GalError::unsupported_feature(format!(
                            "terrain voxel source Distant Horizons column {column_key} has no source material mapping for '{}'",
                            identity.block_state_identity
                        ))
                    })??;
                let base = u32::try_from(vertices.len()).map_err(|_| {
                    GalError::invalid_argument(
                        "terrain voxel source Distant Horizons vertex count exceeds u32",
                    )
                })?;
                for vertex in quad.vertices {
                    vertices.push(TerrainVoxelSourceVertex {
                        position: [
                            asset.origin[0] as f32
                                + vertex.local_position[0]
                                + vertex.micro_offset[0],
                            asset.origin[1] as f32
                                + vertex.local_position[1]
                                + vertex.micro_offset[1],
                            asset.origin[2] as f32
                                + vertex.local_position[2]
                                + vertex.micro_offset[2],
                        ],
                        // DH geometry is already a reduced world-space
                        // primitive. It has no Minecraft `at_midBlock` lane;
                        // a zero midpoint explicitly preserves its copied
                        // geometry rather than inventing a block-local one.
                        mid_block_packed: 0,
                        shader_material_id,
                    });
                }
                indices.extend_from_slice(&[base, base + 1, base + 2, base + 2, base + 3, base]);
            }
            if vertices.is_empty() {
                continue;
            }
            let mesh_key = distant_horizons_voxel_mesh_key(column_key, instance.segment_index);
            if !seen_columns.insert(mesh_key) {
                return Err(GalError::invalid_argument(format!(
                    "terrain voxel source Distant Horizons frame has duplicate visible column/segment key {mesh_key}"
                )));
            }
            let mesh = TerrainVoxelSourceMesh {
                mesh_key,
                mesh_generation: instance.column_generation,
                vertices: Arc::new(vertices),
                indices: Arc::new(indices),
                translucent_indices: Arc::new(Vec::new()),
                transform: IDENTITY_WORLD_TRANSFORM,
            };
            if !self.lod_voxel_source_meshes.contains_key(&cache_key)
                && self.lod_voxel_source_meshes.len() >= WORLD_LOD_MAX_SOURCE_MESH_CACHE
            {
                self.lod_voxel_source_meshes.clear();
            }
            self.lod_voxel_source_meshes.insert(
                cache_key,
                DistantHorizonsVoxelSourceCacheEntry {
                    shader_pack_generation,
                    world_y_offset: frame.lod_render_frame.world_y_offset,
                    mesh: mesh.clone(),
                },
            );
            result.push(mesh);
        }
        Ok(result)
    }

    fn terrain_voxel_translucent_indices(
        mesh_key: u64,
        asset: &MeshAssetStore,
        indices: &[u32],
    ) -> GalResult<Vec<u32>> {
        let stride = index_stride(asset.index_type);
        let mut translucent = Vec::new();
        for (section_index, section) in asset.sections.iter().enumerate() {
            if section.material_mode != WORLD_MATERIAL_MODE_TRANSLUCENT {
                continue;
            }
            let first = u64::from(section.index_offset)
            .checked_div(stride)
            .filter(|_| u64::from(section.index_offset) % stride == 0)
            .ok_or_else(|| {
                GalError::invalid_argument(format!(
                    "terrain voxel source mesh {} translucent section {} has unaligned index offset {}",
                    mesh_key, section_index, section.index_offset
                ))
            })?;
            let end = first
                .checked_add(u64::from(section.index_count))
                .ok_or_else(|| {
                    GalError::invalid_argument(
                        "terrain voxel translucent section index range overflows",
                    )
                })?;
            let range = usize::try_from(first)
            .ok()
            .zip(usize::try_from(end).ok())
            .filter(|(start, end)| start <= end && *end <= indices.len())
            .ok_or_else(|| {
                GalError::invalid_argument(format!(
                    "terrain voxel source mesh {} translucent section {} range {}..{} exceeds {} decoded indices",
                    mesh_key, section_index, first, end, indices.len()
                ))
            })?;
            translucent.extend_from_slice(&indices[range.0..range.1]);
        }
        Ok(translucent)
    }

    fn world_transform_from_camera_relative(
        camera_relative: [f32; 16],
        camera_world_position: [f32; 3],
    ) -> GalResult<[f32; 16]> {
        if camera_relative.iter().any(|value| !value.is_finite())
            || camera_world_position.iter().any(|value| !value.is_finite())
        {
            return Err(GalError::invalid_argument(
                "camera-relative terrain transform must be finite",
            ));
        }
        // Column-major `translation(camera) * camera_relative`. Static chunk
        // section origins are integral world coordinates, whereas their
        // camera-relative float subtraction may vary by a few ULPs from frame
        // to frame. Canonicalize only near-integral translations for the
        // private occupancy identity; rendering retains the original matrix.
        let mut world = camera_relative;
        for column in 0..4 {
            let row_w = camera_relative[column * 4 + 3];
            world[column * 4] += camera_world_position[0] * row_w;
            world[column * 4 + 1] += camera_world_position[1] * row_w;
            world[column * 4 + 2] += camera_world_position[2] * row_w;
        }
        for component in [12, 13, 14] {
            let nearest = world[component].round();
            if (world[component] - nearest).abs() <= 0.001 {
                world[component] = nearest;
            }
        }
        Ok(world)
    }

    /// Installs a private Rust-owned occupancy transaction for an already
    /// validated shader-pack generation. This accepts semantic descriptors
    /// only; no Java state, native resource, or selected shader execution is
    /// exposed here.
