#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct LineBatch {
    start: usize,
    count: usize,
    depth_policy: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct CrackBatch {
    start: usize,
    count: usize,
    depth_policy: u32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct BorderBatch {
    start: usize,
    count: usize,
    depth_policy: u32,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct MaterialBatch {
    key: MaterialResourceKey,
    indices: Vec<usize>,
}

/// Preserves semantic source-material ordering while grouping only adjacent
/// quads with identical raster and semantic texture bindings. A local
/// material texture remains a Rust-owned source resource; it is never an
/// atlas object, texture unit, or backend handle in the semantic frame.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SourceTexturedMaterialBatch {
    start: usize,
    count: usize,
    texture_id: u32,
    source_uv_space: u32,
    material_mode: u32,
    depth_policy: u32,
    cull_policy: u32,
    winding: u32,
    block_entity_id: i32,
}

impl SourceTexturedMaterialBatch {
    fn indices(self) -> std::ops::Range<usize> {
        self.start..self.start + self.count
    }
}

impl MaterialBatch {
    fn count(&self) -> usize {
        self.indices.len()
    }
}

#[derive(Clone)]
struct MeshBatch {
    key: MeshResourceKey,
    index_offset: u64,
    index_count: u32,
    indices: Vec<usize>,
}

/// Bounded selected-source audit evidence. This is deliberately calculated
/// from the shared frontend batches and the source draw records before command
/// recording so a diagnostic capture can distinguish missing semantic work
/// from a later raster or fragment-stage failure.
#[derive(Clone, Copy, Debug, Default)]
struct SourceTerrainDrawCoverage {
    opaque_batches: u64,
    cutout_batches: u64,
    opaque_instances: u64,
    cutout_instances: u64,
    opaque_indices: u64,
    cutout_indices: u64,
    opaque_draws: u64,
    cutout_draws: u64,
    opaque_draw_indices: u64,
    cutout_draw_indices: u64,
    translucent_batches: u64,
    translucent_instances: u64,
    translucent_indices: u64,
    translucent_draws: u64,
    translucent_draw_indices: u64,
}

impl SourceTerrainDrawCoverage {
    fn from_batches_and_draws(batches: &[MeshBatch], draws: &[TerrainMeshDraw]) -> Self {
        let mut coverage = Self::default();
        for batch in batches {
            if !is_source_terrain_mesh_stratum(batch.key.stratum) {
                continue;
            }
            let (batch_count, instance_count, index_count) = match batch.key.material_mode {
                WORLD_MATERIAL_MODE_OPAQUE => (
                    &mut coverage.opaque_batches,
                    &mut coverage.opaque_instances,
                    &mut coverage.opaque_indices,
                ),
                WORLD_MATERIAL_MODE_CUTOUT => (
                    &mut coverage.cutout_batches,
                    &mut coverage.cutout_instances,
                    &mut coverage.cutout_indices,
                ),
                WORLD_MATERIAL_MODE_TRANSLUCENT => (
                    &mut coverage.translucent_batches,
                    &mut coverage.translucent_instances,
                    &mut coverage.translucent_indices,
                ),
                _ => continue,
            };
            *batch_count = batch_count.saturating_add(1);
            *instance_count = instance_count.saturating_add(batch.indices.len() as u64);
            *index_count = index_count.saturating_add(batch.index_count as u64);
        }
        for draw in draws {
            match draw.material_mode {
                TerrainMaterialPassMode::Opaque => {
                    coverage.opaque_draws = coverage.opaque_draws.saturating_add(1);
                    coverage.opaque_draw_indices = coverage
                        .opaque_draw_indices
                        .saturating_add(draw.index_count as u64);
                }
                TerrainMaterialPassMode::Cutout => {
                    coverage.cutout_draws = coverage.cutout_draws.saturating_add(1);
                    coverage.cutout_draw_indices = coverage
                        .cutout_draw_indices
                        .saturating_add(draw.index_count as u64);
                }
                TerrainMaterialPassMode::Translucent => {
                    coverage.translucent_draws = coverage.translucent_draws.saturating_add(1);
                    coverage.translucent_draw_indices = coverage
                        .translucent_draw_indices
                        .saturating_add(draw.index_count as u64);
                }
            }
        }
        coverage
    }
}

impl MeshBatch {
    fn count(&self) -> usize {
        self.indices.len()
    }
}

fn line_batches(frame: &WorldPrimitiveFrame) -> Vec<LineBatch> {
    let mut batches = Vec::new();
    let Some(first) = frame.segments.first() else {
        return batches;
    };
    let mut current = LineBatch {
        start: 0,
        count: 0,
        depth_policy: first.depth_policy,
    };
    for (index, segment) in frame.segments.iter().enumerate() {
        if current.count > 0 && segment.depth_policy != current.depth_policy {
            batches.push(current);
            current = LineBatch {
                start: index,
                count: 0,
                depth_policy: segment.depth_policy,
            };
        }
        current.count += 1;
    }
    if current.count > 0 {
        batches.push(current);
    }
    batches
}

fn crack_batches(frame: &WorldPrimitiveFrame) -> Vec<CrackBatch> {
    let mut batches = Vec::new();
    let Some(first) = frame.crack_quads.first() else {
        return batches;
    };
    let mut current = CrackBatch {
        start: 0,
        count: 0,
        depth_policy: first.depth_policy,
    };
    for (index, quad) in frame.crack_quads.iter().enumerate() {
        if current.count > 0 && quad.depth_policy != current.depth_policy {
            batches.push(current);
            current = CrackBatch {
                start: index,
                count: 0,
                depth_policy: quad.depth_policy,
            };
        }
        current.count += 1;
    }
    if current.count > 0 {
        batches.push(current);
    }
    batches
}

fn border_batches(frame: &WorldPrimitiveFrame) -> Vec<BorderBatch> {
    let mut batches = Vec::new();
    let Some(first) = frame.border_quads.first() else {
        return batches;
    };
    let mut current = BorderBatch {
        start: 0,
        count: 0,
        depth_policy: first.depth_policy,
    };
    for (index, quad) in frame.border_quads.iter().enumerate() {
        if current.count > 0 && quad.depth_policy != current.depth_policy {
            batches.push(current);
            current = BorderBatch {
                start: index,
                count: 0,
                depth_policy: quad.depth_policy,
            };
        }
        current.count += 1;
    }
    if current.count > 0 {
        batches.push(current);
    }
    batches
}

/// Resolves the copied vanilla sampler wrap policy for source-local material
/// textures.  Weather's U/V coordinates deliberately scroll beyond `[0, 1]`;
/// Frozen loads those PNGs without clamp metadata, so both axes must repeat.
/// Keeping this identity policy beside material resource creation prevents the
/// private Vulkan sampler from inheriting an unrelated generic-local-texture
/// default.
/// Frozen uses core/particle for both ordinary particles and weather. The
/// lightmap is an explicit Rust-owned resource, never a borrowed GPU binding.
fn material_uses_particle_shader(source_program: u32) -> bool {
    matches!(source_program, WORLD_MATERIAL_SOURCE_WEATHER | WORLD_MATERIAL_SOURCE_PARTICLES)
}

fn material_sampler_address_mode(texture_id: u32) -> SamplerAddressMode {
    match texture_id {
        WORLD_MATERIAL_TEXTURE_END_SKY
        | WORLD_MATERIAL_TEXTURE_WEATHER_RAIN
        | WORLD_MATERIAL_TEXTURE_WEATHER_SNOW => SamplerAddressMode::Repeat,
        _ => SamplerAddressMode::ClampToEdge,
    }
}

/// Java's weather `TextureStateShard` deliberately declares `mipmap=false`.
/// The copied rain and snow images are therefore sampled exclusively from mip
/// zero in Frozen.  Keep that source policy explicit in the Rust-owned
/// resource description instead of silently allocating a derivative-selected
/// mip chain for the weather stream.
fn material_texture_mip_level_count(source_program: u32, width: u32, height: u32) -> u32 {
    if source_program == WORLD_MATERIAL_SOURCE_WEATHER {
        1
    } else {
        texture_mip_level_count(width, height)
    }
}


fn material_batches(frame: &WorldPrimitiveFrame, color_format: ColorFormat) -> Vec<MaterialBatch> {
    let mut batches: Vec<MaterialBatch> = Vec::new();
    let mut key_to_batch = BTreeMap::<MaterialResourceKey, usize>::new();
    for (index, quad) in frame.material_quads.iter().enumerate() {
        let key = material_key(quad, color_format);
        // Clouds use ordinary source-alpha composition.  Their decoded face
        // stream is therefore part of the semantic result: re-grouping an
        // earlier cloud face after a later one changes overlapping interior
        // and exterior pixels. Frozen emits one ordered cloud stream, so keep
        // only adjacent compatible cloud faces together. Other material
        // families retain their established resource-key batching.
        if key.source_program == WORLD_MATERIAL_SOURCE_CLOUDS {
            if let Some(previous) = batches.last_mut().filter(|batch| {
                batch.key == key && batch.count() < WORLD_MAX_MATERIAL_QUADS_PER_BATCH
            }) {
                previous.indices.push(index);
            } else {
                batches.push(MaterialBatch {
                    key,
                    indices: vec![index],
                });
            }
            continue;
        }
        let reusable_batch = key_to_batch.get(&key).copied().filter(|batch_index| {
            batches[*batch_index].count() < WORLD_MAX_MATERIAL_QUADS_PER_BATCH
        });
        if let Some(batch_index) = reusable_batch {
            batches[batch_index].indices.push(index);
        } else {
            let batch_index = batches.len();
            key_to_batch.insert(key, batch_index);
            batches.push(MaterialBatch {
                key,
                indices: vec![index],
            });
        }
    }
    batches
}

fn source_material_batches_for_program(
    frame: &WorldPrimitiveFrame,
    source_program: u32,
    allowed_modes: &[u32],
) -> GalResult<Vec<SourceTexturedMaterialBatch>> {
    let mut batches = Vec::new();
    for (index, quad) in frame.material_quads.iter().enumerate() {
        let source_program_matches = quad.source_program == source_program
            || (source_program == WORLD_MATERIAL_SOURCE_TEXTURED
                && matches!(
                    quad.source_program,
                    WORLD_MATERIAL_SOURCE_PARTICLES | WORLD_MATERIAL_SOURCE_ENTITY_MODEL
                ));
        if !source_program_matches {
            continue;
        }
        if !allowed_modes.contains(&quad.material_mode) {
            return Err(GalError::unsupported_feature(format!(
                "world material quad {index} has unsupported source material mode {} for source program {source_program}",
                quad.material_mode
            )));
        }
        if !matches!(
            quad.depth_policy,
            WORLD_DEPTH_POLICY_TEST_WRITE | WORLD_DEPTH_POLICY_TEST_NO_WRITE
        ) {
            return Err(GalError::unsupported_feature(format!(
                "world material quad {index} has unsupported source depth policy {}",
                quad.depth_policy
            )));
        }
        if !matches!(quad.winding, WORLD_WINDING_CCW | WORLD_WINDING_CW) {
            return Err(GalError::invalid_argument(format!(
                "world material quad {index} has invalid source winding {}",
                quad.winding
            )));
        }
        if quad.block_entity_id < -1 {
            return Err(GalError::invalid_argument(format!(
                "world material quad {index} has invalid block entity id {}",
                quad.block_entity_id
            )));
        }
        if !matches!(
            quad.source_uv_space,
            WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE | WORLD_MATERIAL_SOURCE_UV_MINECRAFT_BLOCK_ATLAS
        ) {
            return Err(GalError::invalid_argument(format!(
                "world material quad {index} has invalid source UV space {}",
                quad.source_uv_space
            )));
        }
        let same_state = batches
            .last()
            .is_some_and(|batch: &SourceTexturedMaterialBatch| {
                batch.texture_id == quad.texture_id
                    && batch.source_uv_space == quad.source_uv_space
                    && batch.material_mode == quad.material_mode
                    && batch.depth_policy == quad.depth_policy
                    && batch.cull_policy == quad.cull_policy
                    && batch.winding == quad.winding
                    && batch.block_entity_id == quad.block_entity_id
            });
        if same_state
            && batches.last().expect("checked source batch").count
                < WORLD_MAX_MATERIAL_QUADS_PER_BATCH
        {
            batches.last_mut().expect("checked source batch").count += 1;
        } else {
            batches.push(SourceTexturedMaterialBatch {
                start: index,
                count: 1,
                texture_id: quad.texture_id,
                source_uv_space: quad.source_uv_space,
                material_mode: quad.material_mode,
                depth_policy: quad.depth_policy,
                cull_policy: quad.cull_policy,
                winding: quad.winding,
                block_entity_id: quad.block_entity_id,
            });
        }
    }
    Ok(batches)
}

fn source_textured_material_batches(
    frame: &WorldPrimitiveFrame,
) -> GalResult<Vec<SourceTexturedMaterialBatch>> {
    source_material_batches_for_program(
        frame,
        WORLD_MATERIAL_SOURCE_TEXTURED,
        &[
            WORLD_MATERIAL_MODE_OPAQUE,
            WORLD_MATERIAL_MODE_CUTOUT,
            WORLD_MATERIAL_MODE_TRANSLUCENT,
        ],
    )
}

/// `gbuffers_textured` is the generic Rust-owned writer for compact material
/// quads. Its translucent records retain straight-alpha composition; the
/// semantic source program, not the producer, determines pass ownership.
fn source_textured_material_blend(material_mode: u32) -> GalResult<BlendMode> {
    match material_mode {
        WORLD_MATERIAL_MODE_OPAQUE
        | WORLD_MATERIAL_MODE_CUTOUT
        | WORLD_MATERIAL_MODE_GLINT
        | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_WRITE
        | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_TEST => Ok(BlendMode::Disabled),
        WORLD_MATERIAL_MODE_TRANSLUCENT => Ok(BlendMode::Alpha),
        value => Err(GalError::unsupported_feature(format!(
            "textured material source program does not support material mode {value}"
        ))),
    }
}

/// Vanilla's `ENTITY_CUTOUT` pipeline declares `ALPHA_CUTOUT = 0.1`.  The
/// selected-source entity program exposes an explicit shader hook for this
/// semantic material decision because VulkanicGAL deliberately has no legacy
/// fixed-function alpha-test state.
fn source_entity_alpha_cutoff(material_mode: u32) -> GalResult<Option<f32>> {
    match material_mode {
        WORLD_MATERIAL_MODE_OPAQUE
        | WORLD_MATERIAL_MODE_TRANSLUCENT
        | WORLD_MATERIAL_MODE_GLINT => Ok(None),
        WORLD_MATERIAL_MODE_CUTOUT
        | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_WRITE
        | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_TEST => Ok(Some(0.1)),
        value => Err(GalError::unsupported_feature(format!(
            "entity source program does not support material mode {value}"
        ))),
    }
}

fn source_weather_material_batches(
    frame: &WorldPrimitiveFrame,
) -> GalResult<Vec<SourceTexturedMaterialBatch>> {
    source_material_batches_for_program(
        frame,
        WORLD_MATERIAL_SOURCE_WEATHER,
        &[WORLD_MATERIAL_MODE_TRANSLUCENT],
    )
}

fn source_cloud_material_batches(
    frame: &WorldPrimitiveFrame,
) -> GalResult<Vec<SourceTexturedMaterialBatch>> {
    source_material_batches_for_program(
        frame,
        WORLD_MATERIAL_SOURCE_CLOUDS,
        &[WORLD_MATERIAL_MODE_TRANSLUCENT],
    )
}

fn source_material_batch_stream_bytes(
    program: &LoweredTexturedMaterialSourceProgram,
    batches: &[SourceTexturedMaterialBatch],
    writer: &str,
) -> GalResult<u64> {
    batches.iter().try_fold(0_u64, |total, batch| {
        let vertices = u64::try_from(batch.count)
            .ok()
            .and_then(|count| count.checked_mul(4))
            .and_then(|count| {
                count.checked_mul(u64::from(program.execution_interface.vertex_stride))
            })
            .ok_or_else(|| {
                GalError::invalid_argument(format!(
                    "{writer} source frame stream reservation overflows"
                ))
            })?;
        total
            .checked_add(u64::from(
                program.execution_interface.legacy_transform_bytes,
            ))
            .and_then(|value| {
                value.checked_add(u64::from(program.execution_interface.scalar_uniform_bytes))
            })
            .and_then(|value| value.checked_add(vertices))
            .and_then(|value| value.checked_add(3 * WORLD_MESH_INSTANCE_STREAM_ALIGNMENT as u64))
            .ok_or_else(|| {
                GalError::invalid_argument(format!(
                    "{writer} source frame stream reservation overflows"
                ))
            })
    })
}

#[derive(Clone, Copy, Debug, Default)]
struct SourceMaterialWriterCoverage {
    batches: u64,
    quads: u64,
    draws: u64,
    vertices: u64,
}

fn source_material_writer_coverage(
    batches: &[SourceTexturedMaterialBatch],
    draws: Option<&[TexturedMaterialSourceDraw]>,
) -> GalResult<SourceMaterialWriterCoverage> {
    let quads = batches.iter().try_fold(0_u64, |total, batch| {
        total
            .checked_add(u64::try_from(batch.count).map_err(|_| {
                GalError::invalid_argument("source material batch quad count exceeds u64")
            })?)
            .ok_or_else(|| GalError::invalid_argument("source material quad count overflows"))
    })?;
    let draws = draws.unwrap_or_default();
    let vertices = draws.iter().try_fold(0_u64, |total, draw| {
        total
            .checked_add(u64::from(draw.vertices))
            .ok_or_else(|| GalError::invalid_argument("source material vertex count overflows"))
    })?;
    Ok(SourceMaterialWriterCoverage {
        batches: u64::try_from(batches.len())
            .map_err(|_| GalError::invalid_argument("source material batch count exceeds u64"))?,
        quads,
        draws: u64::try_from(draws.len())
            .map_err(|_| GalError::invalid_argument("source material draw count exceeds u64"))?,
        vertices,
    })
}

/// A compact semantic material quad lowers to exactly one six-vertex direct
/// draw. Keep this receipt invariant at the combined source transaction: a
/// missing draw or a truncated expansion must invalidate the frame before the
/// single presenter can publish an incomplete material family.
fn require_source_material_writer_coverage(
    writer: &str,
    coverage: SourceMaterialWriterCoverage,
) -> GalResult<()> {
    if coverage.quads == 0 {
        return Ok(());
    }
    if coverage.draws == 0 {
        return Err(GalError::backend(format!(
            "{writer} source writer produced no draws for {} semantic quads",
            coverage.quads
        )));
    }
    let expected_vertices = coverage.quads.checked_mul(6).ok_or_else(|| {
        GalError::invalid_argument(format!("{writer} source vertex coverage overflows"))
    })?;
    if coverage.vertices != expected_vertices {
        return Err(GalError::backend(format!(
            "{writer} source writer expanded {} semantic quads to {} vertices; expected {}",
            coverage.quads, coverage.vertices, expected_vertices
        )));
    }
    Ok(())
}

/// Particles deliberately reuse the compact `gbuffers_textured` ABI and
/// writer, but remain a distinct semantic source family. Prove that their
/// admitted quads are included in that shared writer's expanded vertex
/// stream instead of relying on the generic textured receipt alone.
fn require_source_material_family_coverage(
    family: &str,
    expected: SourceMaterialWriterCoverage,
    shared_writer: SourceMaterialWriterCoverage,
) -> GalResult<()> {
    if expected.quads == 0 {
        return Ok(());
    }
    if shared_writer.draws == 0 {
        return Err(GalError::backend(format!(
            "{family} source writer produced no draws for {} semantic quads",
            expected.quads
        )));
    }
    if shared_writer.quads < expected.quads {
        return Err(GalError::backend(format!(
            "{family} source writer covered {} of {} semantic quads",
            shared_writer.quads, expected.quads
        )));
    }
    let required_vertices = expected.quads.checked_mul(6).ok_or_else(|| {
        GalError::invalid_argument(format!("{family} source vertex coverage overflows"))
    })?;
    if shared_writer.vertices < required_vertices {
        return Err(GalError::backend(format!(
            "{family} source writer covered {} of {} required vertices",
            shared_writer.vertices, required_vertices
        )));
    }
    Ok(())
}

/// Particle-group coverage is valid only when the copied frame contains at
/// least one Rust semantic particle batch. This check is shared by ordinary,
/// Fabulous, and selected-source submissions so no route can silently drop a
/// reported particle group before the explicit writer receipt runs.
fn require_particle_group_semantics(frame: &WorldPrimitiveFrame) -> GalResult<()> {
    if frame.feature_coverage.particle_group_submits == 0 {
        return Ok(());
    }
    let batches = source_material_batches_for_program(
        frame,
        WORLD_MATERIAL_SOURCE_PARTICLES,
        &[
            WORLD_MATERIAL_MODE_OPAQUE,
            WORLD_MATERIAL_MODE_CUTOUT,
            WORLD_MATERIAL_MODE_TRANSLUCENT,
        ],
    )?;
    if batches.is_empty() {
        return Err(GalError::unsupported_feature(
            "frame reports particle groups without Rust-owned semantic particle quads",
        ));
    }
    Ok(())
}

/// Every admitted fullscreen source consumer is a real Rust draw, including
/// shader-pack post-processing and cloud stages. A consumer that only records
/// copies or barriers must not silently satisfy the semantic source contract.
fn require_source_fullscreen_writer_coverage(
    writer: &str,
    operations: &[CommandOp],
) -> GalResult<()> {
    let draws = operations
        .iter()
        .filter(|operation| {
            matches!(
                operation,
                CommandOp::Draw { .. } | CommandOp::DrawIndexed { .. }
            )
        })
        .count();
    if draws == 0 {
        return Err(GalError::backend(format!(
            "{writer} fullscreen source writer produced no draw operations"
        )));
    }
    Ok(())
}

/// Outline, crack, and border streams are separate semantic overlay writers.
/// A non-empty stream must emit its own Rust draw before the source presenter
/// can publish the frame; unrelated terrain or fullscreen work cannot satisfy
/// this receipt because the operation slice is isolated per writer.
fn require_source_overlay_writer_coverage(
    writer: &str,
    expected: bool,
    operations: &[CommandOp],
) -> GalResult<()> {
    if !expected {
        return Ok(());
    }
    let draws = operations
        .iter()
        .filter(|operation| {
            matches!(
                operation,
                CommandOp::Draw { .. } | CommandOp::DrawIndexed { .. }
            )
        })
        .count();
    if draws == 0 {
        return Err(GalError::backend(format!(
            "{writer} source overlay writer produced no draw operations"
        )));
    }
    Ok(())
}

/// World text is a semantic quad stream with a dedicated Rust atlas/pass.
/// Every admitted quad must be represented by at least one text draw before
/// the source overlay is allowed to continue toward presentation.
fn require_source_text_writer_coverage(expected_quads: u64, actual_draws: u64) -> GalResult<()> {
    if expected_quads != 0 && actual_draws == 0 {
        return Err(GalError::backend(format!(
            "world text source writer produced no draws for {expected_quads} semantic quads"
        )));
    }
    Ok(())
}

/// Entity mesh instances are semantic submissions, not optional diagnostics.
/// Every admitted ordinary entity instance must reach at least one Rust draw
/// with a non-empty indexed range before the combined source presenter runs.
fn require_source_entity_writer_coverage(
    expected_instances: u64,
    actual_instances: u64,
    draws: u64,
    indices: u64,
) -> GalResult<()> {
    if expected_instances == 0 {
        return Ok(());
    }
    // A single semantic instance may own several immutable mesh sections;
    // each section is emitted as its own indexed draw. Therefore the draw
    // stream's summed instance counts can exceed the semantic-instance count
    // while still providing complete coverage.
    if actual_instances < expected_instances {
        return Err(GalError::backend(format!(
            "entity source writer covered {} of {} semantic instances",
            actual_instances, expected_instances
        )));
    }
    if draws == 0 || indices == 0 {
        return Err(GalError::backend(format!(
            "entity source writer produced incomplete coverage for {} semantic instances (draws={}, indices={})",
            expected_instances, draws, indices
        )));
    }
    Ok(())
}

/// The hand stream has its own projection and depth domain, but it is still
/// part of the same source transaction. Do not let a prepared hand frame
/// disappear while ordinary entity coverage remains valid.
fn require_source_hand_writer_coverage(
    expected_instances: u64,
    actual_instances: u64,
    draws: u64,
    indices: u64,
) -> GalResult<()> {
    if expected_instances == 0 {
        return Ok(());
    }
    // Hand models also expand one semantic instance into multiple section
    // draws; require coverage, not one-to-one draw accounting.
    if actual_instances < expected_instances {
        return Err(GalError::backend(format!(
            "hand source writer covered {} of {} semantic instances",
            actual_instances, expected_instances
        )));
    }
    if draws == 0 || indices == 0 {
        return Err(GalError::backend(format!(
            "hand source writer produced incomplete coverage for {} semantic instances (draws={}, indices={})",
            expected_instances, draws, indices
        )));
    }
    Ok(())
}

/// The near-terrain source plan owns only the indexed baked-block strata;
/// entity batches share the transport list but have a separate writer. Keep
/// the receipt partition explicit so an entity draw cannot falsely satisfy
/// terrain coverage, and reject any admitted terrain range omitted by the
/// source terrain pass.
fn require_source_terrain_writer_coverage(
    batches: &[MeshBatch],
    coverage: SourceTerrainDrawCoverage,
) -> GalResult<()> {
    let mut expected_opaque_indices = 0_u64;
    let mut expected_cutout_indices = 0_u64;
    let mut expected_translucent_indices = 0_u64;
    let mut expected_opaque_batches = 0_u64;
    let mut expected_cutout_batches = 0_u64;
    let mut expected_translucent_batches = 0_u64;
    for batch in batches
        .iter()
        .filter(|batch| is_source_terrain_mesh_stratum(batch.key.stratum))
    {
        match batch.key.material_mode {
            WORLD_MATERIAL_MODE_OPAQUE => {
                expected_opaque_batches = expected_opaque_batches.saturating_add(1);
                expected_opaque_indices =
                    expected_opaque_indices.saturating_add(u64::from(batch.index_count));
            }
            WORLD_MATERIAL_MODE_CUTOUT => {
                expected_cutout_batches = expected_cutout_batches.saturating_add(1);
                expected_cutout_indices =
                    expected_cutout_indices.saturating_add(u64::from(batch.index_count));
            }
            WORLD_MATERIAL_MODE_TRANSLUCENT => {
                expected_translucent_batches = expected_translucent_batches.saturating_add(1);
                expected_translucent_indices =
                    expected_translucent_indices.saturating_add(u64::from(batch.index_count));
            }
            _ => {}
        }
    }
    if expected_opaque_batches != 0
        && (coverage.opaque_draws == 0 || coverage.opaque_draw_indices != expected_opaque_indices)
    {
        return Err(GalError::backend(format!(
            "opaque source terrain coverage omitted or truncated indexed work (batches={}, draws={}, indices={}/{})",
            expected_opaque_batches,
            coverage.opaque_draws,
            coverage.opaque_draw_indices,
            expected_opaque_indices
        )));
    }
    if expected_cutout_batches != 0
        && (coverage.cutout_draws == 0 || coverage.cutout_draw_indices != expected_cutout_indices)
    {
        return Err(GalError::backend(format!(
            "cutout source terrain coverage omitted or truncated indexed work (batches={}, draws={}, indices={}/{})",
            expected_cutout_batches,
            coverage.cutout_draws,
            coverage.cutout_draw_indices,
            expected_cutout_indices
        )));
    }
    if expected_translucent_batches != 0
        && (coverage.translucent_draws == 0
            || coverage.translucent_draw_indices != expected_translucent_indices)
    {
        return Err(GalError::backend(format!(
            "translucent source terrain coverage omitted or truncated indexed work (batches={}, draws={}, indices={}/{})",
            expected_translucent_batches,
            coverage.translucent_draws,
            coverage.translucent_draw_indices,
            expected_translucent_indices
        )));
    }
    Ok(())
}

/// Block-model and moving-block producers use the shared indexed terrain
/// writer, but retain distinct semantic strata. Keep a family-specific receipt
/// so ordinary terrain draws cannot mask a dropped block-model submission.
fn require_source_mesh_family_writer_coverage(
    family: &str,
    stratum: u32,
    batches: &[MeshBatch],
    draws: &[TerrainMeshDraw],
) -> GalResult<()> {
    let expected = batches
        .iter()
        .filter(|batch| {
            is_source_terrain_mesh_stratum(batch.key.stratum) && batch.key.stratum == stratum
        })
        .fold((0_u64, 0_u64), |(batch_count, indices), batch| {
            (
                batch_count.saturating_add(1),
                indices.saturating_add(u64::from(batch.index_count)),
            )
        });
    if expected.0 == 0 {
        return Ok(());
    }
    let actual = draws.iter().filter(|draw| draw.stratum == stratum).fold(
        (0_u64, 0_u64),
        |(draw_count, indices), draw| {
            (
                draw_count.saturating_add(1),
                indices.saturating_add(u64::from(draw.index_count)),
            )
        },
    );
    if actual.0 == 0 || actual.1 != expected.1 {
        return Err(GalError::backend(format!(
            "{family} source writer omitted or truncated indexed work (batches={}, draws={}, indices={}/{})",
            expected.0, actual.0, actual.1, expected.1
        )));
    }
    Ok(())
}

/// Distant Horizons has several material streams (reduced-color, exact-atlas,
/// and translucent water). They share one source transaction, so prove that
/// any admitted LOD workload reached at least one Rust-owned indexed draw.
fn require_source_lod_writer_coverage(expected_instances: u64, actual_draws: u64) -> GalResult<()> {
    if expected_instances != 0 && actual_draws < expected_instances {
        return Err(GalError::backend(format!(
            "Distant Horizons source writer covered {actual_draws} of {expected_instances} admitted LOD instances"
        )));
    }
    Ok(())
}

fn material_key(quad: &WorldMaterialQuadRequest, color_format: ColorFormat) -> MaterialResourceKey {
    MaterialResourceKey {
        material_id: quad.material_id,
        texture_id: quad.texture_id,
        source_program: quad.source_program,
        material_mode: quad.material_mode,
        depth_policy: quad.depth_policy,
        cull_policy: quad.cull_policy,
        winding: quad.winding,
        color_format,
    }
}

/// Bounded source-instance receipt for the mesh family shared by terrain,
/// static displays, and moving blocks. It proves the copied semantic color
/// modulation that the selected source ABI consumes without exposing asset,
/// pipeline, or native resource identities. The fixed sample bound keeps a
/// diagnostic capture from scaling with the world's visible mesh count.
fn source_mesh_instance_semantics_json(frame: &WorldPrimitiveFrame) -> String {
    let mut source_instances = 0u64;
    let mut non_white_color_instances = 0u64;
    let mut translucent_instances = 0u64;
    let mut terrain_instances = 0u64;
    let mut opaque_geometry_instances = 0u64;
    let mut moving_mesh_instances = 0u64;
    let mut records = Vec::new();
    for instance in frame
        .mesh_instances
        .iter()
        .filter(|instance| is_source_terrain_mesh_stratum(instance.stratum))
    {
        source_instances = source_instances.saturating_add(1);
        match instance.stratum {
            WORLD_STRATUM_TERRAIN => terrain_instances = terrain_instances.saturating_add(1),
            WORLD_STRATUM_OPAQUE_TEXTURED_GEOMETRY => {
                opaque_geometry_instances = opaque_geometry_instances.saturating_add(1)
            }
            WORLD_STRATUM_ORDINARY_BLOCK => {
                opaque_geometry_instances = opaque_geometry_instances.saturating_add(1)
            }
            WORLD_STRATUM_MOVING_MESH => {
                moving_mesh_instances = moving_mesh_instances.saturating_add(1)
            }
            _ => unreachable!("source mesh stratum was filtered above"),
        }
        if instance.color_argb != u32::MAX {
            non_white_color_instances = non_white_color_instances.saturating_add(1);
        }
        if instance.depth_policy == WORLD_DEPTH_POLICY_TEST_NO_WRITE {
            translucent_instances = translucent_instances.saturating_add(1);
        }
        if records.len() < 16 {
            let color = argb_to_rgba(instance.color_argb);
            records.push(format!(
                concat!(
                    "{{\"stratum\":{},\"mesh_key\":{},\"mesh_generation\":{},",
                    "\"section_index\":{},\"color_argb\":{},",
                    "\"color_rgba\":[{},{},{},{}],\"depth_policy\":{},",
                    "\"cull_policy\":{},\"winding\":{}}}"
                ),
                instance.stratum,
                instance.mesh_key,
                instance.mesh_generation,
                instance.mesh_section_index,
                instance.color_argb,
                color[0],
                color[1],
                color[2],
                color[3],
                instance.depth_policy,
                instance.cull_policy,
                instance.winding,
            ));
        }
    }
    format!(
        concat!(
            "{{\"source_instances\":{},",
            "\"terrain_instances\":{},\"opaque_geometry_instances\":{},",
            "\"moving_mesh_instances\":{},",
            "\"non_white_color_instances\":{},",
            "\"test_no_write_instances\":{},",
            "\"instance_record_bytes\":{},",
            "\"records\":[{}]}}"
        ),
        source_instances,
        terrain_instances,
        opaque_geometry_instances,
        moving_mesh_instances,
        non_white_color_instances,
        translucent_instances,
        TERRAIN_SOURCE_INSTANCE_BYTES,
        records.join(","),
    )
}

/// Bounded receipt for copied ModelPart/entity-model instances. This is
/// deliberately separate from terrain and moving-mesh receipts: a selected
/// source frame containing only terrain must never satisfy an entity producer
/// capture gate. The record remains semantic and contains no local texture,
/// pipeline, descriptor, or backend identities.
impl WorldPrimitiveFrontend {
    /// The source writer can privately expand a copied mesh, so capture
    /// correlation uses its canonical entity identity rather than a transient
    /// Java-side mesh key.
    fn source_entity_instance_semantics_json(&self, frame: &WorldPrimitiveFrame) -> String {
        let mut instances = 0u64;
        let mut records = Vec::new();
        for instance in frame
            .mesh_instances
            .iter()
            .filter(|instance| instance.stratum == WORLD_STRATUM_ENTITY_MESH)
        {
            instances = instances.saturating_add(1);
            if records.len() < 16 {
                let color = argb_to_rgba(instance.color_argb);
                let entity_identity = self
                    .mesh_assets
                    .get(&instance.mesh_key)
                    .map(|asset| asset.entity_identity.as_str())
                    .unwrap_or("");
                let section_semantics = self
                    .mesh_assets
                    .get(&instance.mesh_key)
                    .map(|asset| {
                        asset
                            .sections
                            .iter()
                            .take(16)
                            .map(|section| {
                                format!(
                                    "{{\"texture_id\":{},\"material_mode\":{},\"depth_policy\":{},\"cull_policy\":{},\"winding\":{}}}",
                                    section.texture_id,
                                    section.material_mode,
                                    instance.depth_policy,
                                    section.cull_policy,
                                    section.winding,
                                )
                            })
                            .collect::<Vec<_>>()
                            .join(",")
                    })
                    .unwrap_or_default();
                let texture_receipt = self
                    .mesh_texture_assets
                    .get(&self
                        .mesh_assets
                        .get(&instance.mesh_key)
                        .and_then(|asset| asset.sections.first())
                        .map(|section| section.texture_id)
                        .unwrap_or_default())
                    .map(|texture| {
                        let alpha_min = texture.rgba.chunks_exact(4).map(|pixel| pixel[3]).min().unwrap_or(0);
                        let alpha_max = texture.rgba.chunks_exact(4).map(|pixel| pixel[3]).max().unwrap_or(0);
                        let alpha_nonzero = texture.rgba.chunks_exact(4).filter(|pixel| pixel[3] != 0).count();
                        format!(
                            "\"texture_width\":{},\"texture_height\":{},\"texture_bytes\":{},\"texture_hash\":\"{:08x}\",\"texture_alpha_min\":{},\"texture_alpha_max\":{},\"texture_alpha_nonzero\":{},",
                            texture.width,
                            texture.height,
                            texture.rgba.len(),
                            xxh32(&texture.rgba, 0x5a4f4d42),
                            alpha_min,
                            alpha_max,
                            alpha_nonzero,
                        )
                    })
                    .unwrap_or_default();
                records.push(format!(
                    concat!(
                        "{{\"mesh_key\":{},\"mesh_generation\":{},",
                        "\"section_index\":{},\"color_argb\":{},",
                        "\"entity_identity\":\"{}\",",
                        "\"color_rgba\":[{},{},{},{}],\"depth_policy\":{},",
                        "\"cull_policy\":{},\"winding\":{},",
                        "\"translation\":[{},{},{}],{}\"section_semantics\":[{}]}}"
                    ),
                    instance.mesh_key,
                    instance.mesh_generation,
                    instance.mesh_section_index,
                    instance.color_argb,
                    json_escape(entity_identity),
                    color[0],
                    color[1],
                    color[2],
                    color[3],
                    instance.depth_policy,
                    instance.cull_policy,
                    instance.winding,
                    instance.transform[12],
                    instance.transform[13],
                    instance.transform[14],
                    texture_receipt,
                    section_semantics,
                ));
            }
        }
        format!(
            concat!(
                "{{\"instances\":{},\"instance_record_bytes\":{},",
                "\"records\":[{}]}}"
            ),
            instances,
            TERRAIN_SOURCE_INSTANCE_BYTES,
            records.join(","),
        )
    }
}

/// Converts only fully classified generic material records into Rust-owned
/// source primitives. This is deliberately kept before source-plan admission:
/// successful staging never means a pack program ran, and an unspecified
/// producer cannot be guessed into a selected source frame.
/// Bounded semantic receipt for source-material work. It deliberately records
/// only producer-owned identity and UV-space classification, never a backend
/// resource handle or shader binding slot.
fn source_material_semantics_json(frame: &WorldPrimitiveFrame) -> String {
    let mut atlas_quads = 0u64;
    let mut local_quads = 0u64;
    let mut unsupported_quads = 0u64;
    let mut textured_quads = 0u64;
    let mut particle_quads = 0u64;
    let mut weather_quads = 0u64;
    let mut cloud_quads = 0u64;
    let mut records = BTreeMap::<(u32, u32, u32, u32), u64>::new();
    for quad in &frame.material_quads {
        if !matches!(
            quad.source_program,
            WORLD_MATERIAL_SOURCE_TEXTURED
                | WORLD_MATERIAL_SOURCE_ENTITY_MODEL
                | WORLD_MATERIAL_SOURCE_PARTICLES
                | WORLD_MATERIAL_SOURCE_WEATHER
                | WORLD_MATERIAL_SOURCE_CLOUDS
        ) {
            continue;
        }
        match quad.source_program {
            WORLD_MATERIAL_SOURCE_TEXTURED => textured_quads += 1,
            WORLD_MATERIAL_SOURCE_ENTITY_MODEL => textured_quads += 1,
            WORLD_MATERIAL_SOURCE_PARTICLES => particle_quads += 1,
            WORLD_MATERIAL_SOURCE_WEATHER => weather_quads += 1,
            WORLD_MATERIAL_SOURCE_CLOUDS => cloud_quads += 1,
            _ => unreachable!("source-material family was filtered above"),
        }
        match quad.source_uv_space {
            WORLD_MATERIAL_SOURCE_UV_MINECRAFT_BLOCK_ATLAS => atlas_quads += 1,
            WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE => local_quads += 1,
            _ => unsupported_quads += 1,
        }
        *records
            .entry((
                quad.source_program,
                quad.material_id,
                quad.texture_id,
                quad.source_uv_space,
            ))
            .or_default() += 1;
    }
    let records = records
        .into_iter()
        .take(16)
        .map(|((source_program, material_id, texture_id, uv_space), quads)| {
            format!(
                "{{\"source_program\":{source_program},\"material_id\":{material_id},\"texture_id\":{texture_id},\"uv_space\":{uv_space},\"quads\":{quads}}}"
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "{{\"textured_quads\":{textured_quads},\"particle_quads\":{particle_quads},\"weather_quads\":{weather_quads},\"cloud_quads\":{cloud_quads},\"atlas_quads\":{atlas_quads},\"local_quads\":{local_quads},\"unsupported_quads\":{unsupported_quads},\"records\":[{records}]}}"
    )
}

/// Bounded per-writer execution receipt paired with
/// `source_material_semantics_json`. Producer gates use this only to prove
/// that the corresponding Rust-owned source writer executed; it contains no
/// pipeline, descriptor, or backend identity.
fn source_material_execution_json(stats: &WorldPrimitiveSubmitStats) -> String {
    let cloud_face_disposition = if stats.source_cloud_faces_suppressed {
        "suppressed"
    } else if stats.source_cloud_quad_count > 0 {
        "draw"
    } else {
        "not-present"
    };
    format!(
        concat!(
            "{{\"textured\":{{\"batches\":{},\"quads\":{},\"draws\":{},\"vertices\":{},\"entity_model_quads\":{}}},",
            "\"weather\":{{\"batches\":{},\"quads\":{},\"draws\":{},\"vertices\":{}}},",
            "\"clouds\":{{\"batches\":{},\"quads\":{},\"draws\":{},\"vertices\":{},\"suppressed_quads\":{},\"face_disposition\":\"{}\",\"fullscreen_cloud_stages\":{}}}}}"
        ),
        stats.source_textured_material_batch_count,
        stats.source_textured_material_quad_count,
        stats.source_textured_material_draw_count,
        stats.source_textured_material_vertex_count,
        stats.source_entity_model_quad_count,
        stats.source_weather_batch_count,
        stats.source_weather_quad_count,
        stats.source_weather_draw_count,
        stats.source_weather_vertex_count,
        stats.source_cloud_batch_count,
        stats.source_cloud_quad_count,
        stats.source_cloud_draw_count,
        stats.source_cloud_vertex_count,
        stats.source_cloud_suppressed_quad_count,
        cloud_face_disposition,
        stats.source_cloud_fullscreen_stage_count,
    )
}

/// Bounded GUI execution receipt for selected-source captures. This exposes
/// only semantic GUI work that the Rust frontend accepted into the final owned
/// overlay target; it contains no backend image or binding identity.
fn gui_execution_json(stats: &GuiSubmitStats) -> String {
    format!(
        concat!(
            "{{\"sprites\":{},\"affine_quads\":{},\"sprite_batches\":{},",
            "\"cache_hits\":{},\"cache_misses\":{},\"resource_creates\":{},",
            "\"command_ops\":{}}}"
        ),
        stats.sprite_count,
        stats.affine_quad_count,
        stats.sprite_batch_count,
        stats.cache_hits,
        stats.cache_misses,
        stats.resource_creates,
        stats.command_ops,
    )
}

/// Bounded world-text receipt. Unlike generic semantic collection counters,
/// this is emitted only after the Rust frontend has planned its actual draws.
fn world_text_execution_json(stats: &WorldPrimitiveSubmitStats) -> String {
    let first_ndc_bounds = stats
        .world_text_first_ndc_bounds
        .map(|bounds| {
            format!(
                "[{:.6},{:.6},{:.6},{:.6}]",
                bounds[0], bounds[1], bounds[2], bounds[3]
            )
        })
        .unwrap_or_else(|| "null".to_owned());
    let first_ndc_corners = stats
        .world_text_first_ndc_corners
        .map(|corners| {
            format!(
                "[[{:.6},{:.6}],[{:.6},{:.6}],[{:.6},{:.6}],[{:.6},{:.6}]]",
                corners[0][0],
                corners[0][1],
                corners[1][0],
                corners[1][1],
                corners[2][0],
                corners[2][1],
                corners[3][0],
                corners[3][1],
            )
        })
        .unwrap_or_else(|| "null".to_owned());
    let ndc_bounds_sample = stats
        .world_text_ndc_bounds_sample
        .iter()
        .map(|bounds| {
            format!(
                "[{:.6},{:.6},{:.6},{:.6}]",
                bounds[0], bounds[1], bounds[2], bounds[3]
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "{{\"quads\":{},\"batches\":{},\"draws\":{},\"clip_xy_visible_quads\":{},\"first_ndc_bounds\":{first_ndc_bounds},\"first_ndc_corners\":{first_ndc_corners},\"ndc_bounds_sample\":[{ndc_bounds_sample}]}}",
        stats.world_text_quad_count,
        stats.world_text_batch_count,
        stats.world_text_draw_count,
        stats.world_text_clip_xy_visible_quad_count,
    )
}

fn stage_source_material_primitives(
    frame: &WorldPrimitiveFrame,
) -> GalResult<Vec<TexturedMaterialSourcePrimitive>> {
    stage_source_material_primitives_for_indices(frame, 0..frame.material_quads.len())
}

fn stage_source_material_primitives_for_indices(
    frame: &WorldPrimitiveFrame,
    indices: impl IntoIterator<Item = usize>,
) -> GalResult<Vec<TexturedMaterialSourcePrimitive>> {
    let mut staged = Vec::new();
    for index in indices {
        let quad = frame.material_quads.get(index).ok_or_else(|| {
            GalError::invalid_argument(format!(
                "source material primitive selection references missing quad {index}"
            ))
        })?;
        let winding = match quad.winding {
            WORLD_WINDING_CCW => TexturedMaterialWinding::CounterClockwise,
            WORLD_WINDING_CW => TexturedMaterialWinding::Clockwise,
            value => {
                return Err(GalError::invalid_argument(format!(
                    "world material quad {index} has unknown source winding {value}"
                )));
            }
        };
        let texture_coordinates = match quad.source_uv_space {
            WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE => {
                TexturedMaterialTextureCoordinates::LocalTexture
            }
            WORLD_MATERIAL_SOURCE_UV_MINECRAFT_BLOCK_ATLAS => {
                TexturedMaterialTextureCoordinates::MinecraftBlockAtlas
            }
            value => {
                return Err(GalError::invalid_argument(format!(
                    "world material quad {index} has unknown source UV space {value}"
                )));
            }
        };
        match quad.source_program {
            WORLD_MATERIAL_SOURCE_TEXTURED
            | WORLD_MATERIAL_SOURCE_ENTITY_MODEL
            | WORLD_MATERIAL_SOURCE_PARTICLES
            | WORLD_MATERIAL_SOURCE_WEATHER
            | WORLD_MATERIAL_SOURCE_CLOUDS => {
                staged.push(stage_textured_material_primitive_with_vertex_modulation(
                    layered_material_vertices(quad),
                    quad.uvs,
                    quad.vertex_color_argb,
                    quad.vertex_packed_light,
                    texture_coordinates,
                    winding,
                )?)
            }
            WORLD_MATERIAL_SOURCE_UNSPECIFIED => {
                return Err(GalError::unsupported_feature(format!(
                    "world material quad {index} is not classified for a source-derived material program"
                )));
            }
            value => {
                return Err(GalError::invalid_argument(format!(
                    "world material quad {index} has unknown source program {value}"
                )));
            }
        }
    }
    Ok(staged)
}

fn mesh_batches(
    frame: &WorldPrimitiveFrame,
    frontend: &WorldPrimitiveFrontend,
    color_format: ColorFormat,
    g_buffer: bool,
    allow_optical: bool,
) -> GalResult<Vec<MeshBatch>> {
    // Preserve first-seen batch order for deterministic submission, but use a
    // hash index for membership.  The previous ordered tree made terrain
    // streaming cost scale as O(instances * log batches); a settled world can
    // contain thousands of section instances and many compatible ranges.
    // Ordering is represented by `batches`, so this changes lookup complexity
    // without changing semantic draw order or pipeline grouping.
    let mut batches: Vec<MeshBatch> = Vec::new();
    let mut key_to_batch = HashMap::<MeshResourceKey, usize>::new();
    // `WORLD_MESH_SECTION_ALL` is common for streamed terrain.  The section
    // coalescing pass depends only on the immutable mesh asset and the small
    // set of instance policies that participate in its resource keys, so do
    // it once per policy tuple instead of once per visible instance.  Keep
    // the cached ranges in their original section order; callers still append
    // them in first-seen instance order below.
    let mut compatible_ranges_cache =
        HashMap::<(u64, u64, u32, u32, ColorFormat, bool, bool), Vec<MeshSectionRange>>::new();
    for (index, instance) in frame.mesh_instances.iter().enumerate() {
        if instance.flags & WORLD_MESH_INSTANCE_FLAG_OUTLINE_ONLY != 0 {
            // Outline-only instances remain in the frame for the dedicated
            // mask/post-effect planner, but never enter the regular material
            // batch where they would reveal an invisible entity body.
            continue;
        }
        let asset = frontend
            .mesh_assets
            .get(&instance.mesh_key)
            .ok_or_else(|| {
                GalError::invalid_argument(format!(
                    "world mesh instance references unknown mesh key {}",
                    instance.mesh_key
                ))
            })?;
        if asset.sections.iter().any(|section| {
            matches!(
                section.material_mode,
                WORLD_MATERIAL_MODE_OPTICAL_STENCIL_WRITE
                    | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_TEST
            )
        }) && (!allow_optical || !frame.first_person.enabled)
        {
            return Err(GalError::unsupported_feature(
                "optical stencil mesh sections require the enabled Rust-owned hand target",
            ));
        }
        if instance.mesh_generation != asset_generation_for_key(instance.mesh_key, asset)? {
            return Err(GalError::invalid_argument(format!(
                "world mesh instance generation {} does not match mesh {} generation",
                instance.mesh_generation, instance.mesh_key
            )));
        }
        if instance.flags & WORLD_MESH_INSTANCE_FLAG_CAMERA_SORTED_QUADS != 0 {
            translucent_order::append_batches(instance, asset, index, color_format, g_buffer, &mut batches)?;
            continue;
        }
        if instance.mesh_section_index == WORLD_MESH_SECTION_ALL {
            let cache_key = (
                instance.mesh_key,
                instance.mesh_generation,
                instance.stratum,
                instance.depth_policy,
                color_format,
                g_buffer,
                instance.item_foil.is_some(),
            );
            let ranges = if let Some(ranges) = compatible_ranges_cache.get(&cache_key) {
                ranges
            } else {
                let ranges =
                    compatible_mesh_section_ranges(instance, asset, color_format, g_buffer)?;
                compatible_ranges_cache.insert(cache_key, ranges);
                compatible_ranges_cache
                    .get(&cache_key)
                    .expect("just-inserted compatible mesh section ranges")
            };
            for range in ranges.iter().copied() {
                push_mesh_batch(
                    &mut batches,
                    &mut key_to_batch,
                    range.key,
                    range.index_offset,
                    range.index_count,
                    index,
                )?;
            }
        } else {
            let section = asset
                .sections
                .get(instance.mesh_section_index as usize)
                .ok_or_else(|| {
                    GalError::invalid_argument("world mesh instance references missing section")
                })?;
            let key = mesh_key_for_section(
                instance,
                section,
                instance.mesh_section_index,
                instance.cull_policy,
                asset.mesh_generation,
                color_format,
                g_buffer,
            );
            push_mesh_batch(
                &mut batches,
                &mut key_to_batch,
                key,
                section.index_offset as u64,
                section.index_count,
                index,
            )?;
        }
    }
    // Java's implicit render-type state machine submits solid and cutout
    // terrain before the back-to-front translucent stream.  The explicit
    // frontend receives semantic instances from independently scheduled
    // producers, so first arrival cannot be allowed to choose that phase
    // order.  Keep the original order inside each phase (which preserves the
    // copied translucent sort order), while making the cross-phase contract
    // explicit for both Rust backends.
    batches.sort_by_key(|batch| mesh_material_render_phase(batch.key.material_mode));
    trace_static_terrain_mesh_batch(frame, frontend, &batches);
    Ok(batches)
}

fn mesh_material_render_phase(material_mode: u32) -> u8 {
    match material_mode {
        WORLD_MATERIAL_MODE_OPAQUE => 0,
        WORLD_MATERIAL_MODE_CUTOUT
        | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_WRITE
        | WORLD_MATERIAL_MODE_OPTICAL_STENCIL_TEST => 1,
        WORLD_MATERIAL_MODE_GLINT => 2,
        WORLD_MATERIAL_MODE_TRANSLUCENT | WORLD_MATERIAL_MODE_TRANSLUCENT_CUTOUT => 3,
        // Validation rejects unknown modes before pipeline construction. Keep
        // them at the end here so an invalid semantic record can never push a
        // valid transparent range ahead of opaque terrain before that error.
        _ => u8::MAX,
    }
}

// Test-only, opt-in trace for static translucent terrain batches after frame
// instance expansion and before any GAL command or backend resource binding.
// A caller can pin a semantic mesh key; otherwise the first matching batch is
// sampled in detail while bounded projected-bounds summaries retain enough
// coverage to identify a differently transformed translucent section.
fn trace_static_terrain_mesh_batch(
    frame: &WorldPrimitiveFrame,
    frontend: &WorldPrimitiveFrontend,
    batches: &[MeshBatch],
) {
    let Some(root) = std::env::var_os("MATTMC_STATIC_TERRAIN_BATCH_TRACE_DIR") else {
        return;
    };
    let requested_mesh_key = std::env::var("MATTMC_STATIC_TERRAIN_BATCH_TRACE_MESH_KEY")
        .ok()
        .and_then(|value| u64::from_str_radix(value.trim_start_matches("0x"), 16).ok());
    let trace_all_materials = matches!(
        std::env::var("MATTMC_STATIC_TERRAIN_BATCH_TRACE_ALL_MATERIALS").as_deref(),
        Ok("1") | Ok("true") | Ok("TRUE")
    );
    let translucent_batches = batches
        .iter()
        .filter(|batch| batch.key.material_mode == WORLD_MATERIAL_MODE_TRANSLUCENT)
        .collect::<Vec<_>>();
    // An explicit semantic key is a bounded diagnostic request and may name
    // opaque, cutout, or translucent terrain. The unselected inventory stays
    // translucent-only so ordinary captures retain their narrow scope.
    let candidates = if requested_mesh_key.is_some() || trace_all_materials {
        batches.iter().collect::<Vec<_>>()
    } else {
        translucent_batches.clone()
    };
    let Some(batch) = candidates.iter().copied().find(|batch| {
        if let Some(mesh_key) = requested_mesh_key {
            return batch.key.mesh_key == mesh_key;
        }
        // The frame also contains first-person/entity mesh instances. Their
        // copied local textures are valid but are not static-terrain evidence;
        // static terrain owns no entity identity in the semantic asset table.
        frontend
            .mesh_assets
            .get(&batch.key.mesh_key)
            .is_some_and(|asset| asset.entity_identity.is_empty())
    }) else {
        return;
    };
    let summary_candidates = if trace_all_materials {
        candidates.as_slice()
    } else {
        translucent_batches.as_slice()
    };
    let batch_summaries = summary_candidates
        .iter()
        .take(128)
        .filter_map(|candidate| {
            static_terrain_batch_projected_bounds(frame, frontend, candidate).map(|bounds| {
                format!(
                    concat!(
                        "{{\"meshKey\":\"{:016x}\",\"meshGeneration\":{},",
                        "\"textureId\":{},\"materialId\":{},",
                        "\"indexOffset\":{},\"indexCount\":{},\"instances\":{},",
                        "\"ndcBounds\":[{:.6},{:.6},{:.6},{:.6}]}}"
                    ),
                    candidate.key.mesh_key,
                    frontend
                        .mesh_assets
                        .get(&candidate.key.mesh_key)
                        .map(|asset| asset.mesh_generation)
                        .unwrap_or_default(),
                    candidate.key.texture_id,
                    candidate.key.material_id,
                    candidate.index_offset,
                    candidate.index_count,
                    candidate.indices.len(),
                    bounds[0],
                    bounds[1],
                    bounds[2],
                    bounds[3],
                )
            })
        })
        .collect::<Vec<_>>();
    let mesh_key = batch.key.mesh_key;
    let Some(asset) = frontend.mesh_assets.get(&mesh_key) else {
        return;
    };
    let Some(instance_index) = batch.indices.first().copied() else {
        return;
    };
    let Some(instance) = frame.mesh_instances.get(instance_index) else {
        return;
    };
    let index_stride = index_stride(asset.index_type) as usize;
    let start = batch.index_offset as usize;
    let sample_count = usize::try_from(batch.index_count).unwrap_or(0).min(12);
    let mut samples = Vec::new();
    for ordinal in 0..sample_count {
        let Some(byte_index) = ordinal
            .checked_mul(index_stride)
            .and_then(|offset| start.checked_add(offset))
        else {
            break;
        };
        let index = match mesh_index_value(
            &asset.index_bytes,
            asset.index_type,
            byte_index / index_stride,
        ) {
            Ok(index) => index,
            Err(_) => break,
        };
        let Some(vertex_offset) = usize::try_from(index)
            .ok()
            .and_then(|index| index.checked_mul(WORLD_MESH_GPU_VERTEX_BYTES))
        else {
            break;
        };
        let Some(vertex_bytes) = asset
            .vertex_bytes
            .get(vertex_offset..vertex_offset + WORLD_MESH_GPU_VERTEX_BYTES)
        else {
            break;
        };
        let position: [f32; 3] = std::array::from_fn(|component| {
            let offset = component * 4;
            f32::from_ne_bytes(
                vertex_bytes[offset..offset + 4]
                    .try_into()
                    .expect("fixed packed world mesh position lane"),
            )
        });
        let f32_lane = |offset: usize| {
            f32::from_ne_bytes(
                vertex_bytes[offset..offset + 4]
                    .try_into()
                    .expect("fixed packed world mesh f32 lane"),
            )
        };
        // These lanes are the direct-terrain shader inputs for a submitted
        // draw: raw UV, modulation colour, light, material policy, and atlas
        // UV. The bounded receipt diagnoses semantic data without exposing
        // any backend-private state.
        let raw_uv = [f32_lane(12), f32_lane(28)];
        let color = [f32_lane(16), f32_lane(20), f32_lane(24), f32_lane(44)];
        let packed_light = [f32_lane(48), f32_lane(52)];
        // `packed_mesh_vertices` stores the semantic material byte in the
        // fixed shader ABI as an f32. Decode that lane as the shader does;
        // interpreting its IEEE-754 bytes as a u32 made the receipt report
        // `1065353216` for the perfectly valid material value `1`.
        let material_bits = f32_lane(60).clamp(0.0, 255.0) as u32;
        let shader_atlas_uv = [f32_lane(64), f32_lane(68)];
        let model = transform_column_major_vec4(
            instance.transform,
            [position[0], position[1], position[2], 1.0],
        );
        let view = transform_column_major_vec4(frame.view_matrix, model);
        let clip = transform_column_major_vec4(frame.projection_matrix, view);
        let ndc = if clip[3].abs() > f32::EPSILON {
            [clip[0] / clip[3], clip[1] / clip[3], clip[2] / clip[3]]
        } else {
            [f32::NAN; 3]
        };
        samples.push(format!(
            concat!(
                "{{\"ordinal\":{ordinal},\"vertexIndex\":{index},",
                "\"local\":[{lx:.6},{ly:.6},{lz:.6}],",
                "\"model\":[{mx:.6},{my:.6},{mz:.6},{mw:.6}],",
                "\"view\":[{vx:.6},{vy:.6},{vz:.6},{vw:.6}],",
                "\"clip\":[{cx:.6},{cy:.6},{cz:.6},{cw:.6}],",
                "\"ndc\":[{nx:.6},{ny:.6},{nz:.6}],",
                "\"rawUv\":[{raw_u:.6},{raw_v:.6}],",
                "\"shaderAtlasUv\":[{atlas_u:.6},{atlas_v:.6}],",
                "\"color\":[{color_r:.6},{color_g:.6},{color_b:.6},{color_a:.6}],",
                "\"packedLight\":[{block_light:.6},{sky_light:.6}],",
                "\"terrainMaterialBits\":{material_bits}}}"
            ),
            ordinal = ordinal,
            index = index,
            lx = position[0],
            ly = position[1],
            lz = position[2],
            mx = model[0],
            my = model[1],
            mz = model[2],
            mw = model[3],
            vx = view[0],
            vy = view[1],
            vz = view[2],
            vw = view[3],
            cx = clip[0],
            cy = clip[1],
            cz = clip[2],
            cw = clip[3],
            nx = ndc[0],
            ny = ndc[1],
            nz = ndc[2],
            raw_u = raw_uv[0],
            raw_v = raw_uv[1],
            atlas_u = shader_atlas_uv[0],
            atlas_v = shader_atlas_uv[1],
            color_r = color[0],
            color_g = color[1],
            color_b = color[2],
            color_a = color[3],
            block_light = packed_light[0],
            sky_light = packed_light[1],
            material_bits = material_bits,
        ));
    }
    let selection = if requested_mesh_key.is_some() {
        "requested-mesh-key"
    } else if trace_all_materials {
        "first-non-entity-static-terrain-any-material"
    } else {
        "first-non-entity-static-translucent"
    };
    let payload = format!(
        concat!(
            "{{\"schema\":\"mattmc-static-terrain-batch-trace-v1\",",
            "\"selection\":\"{}\",\"frameId\":{},\"meshKey\":\"{:016x}\",\"meshGeneration\":{},",
            "\"indexType\":\"{:?}\",\"batchIndexOffset\":{},\"batchIndexCount\":{},",
            "\"batchInstances\":{},\"instanceIndex\":{},\"instanceColorArgb\":{},",
            "\"instanceColorRgba\":[{:.6},{:.6},{:.6},{:.6}],\"instanceTransform\":{},",
            "\"viewMatrix\":{},\"projectionMatrix\":{},\"samples\":[{}],",
            "\"cameraSortedQuads\":{},\"meshIndexCount\":{},",
            "\"orderedMeshRangesComplete\":{},\"orderedMeshRanges\":[{}],\"textureMipLevels\":{}}}\n"
        ),
        selection,
        frame.frame_id,
        mesh_key,
        asset.mesh_generation,
        asset.index_type,
        batch.index_offset,
        batch.index_count,
        batch.indices.len(),
        instance_index,
        instance.color_argb,
        argb_to_rgba(instance.color_argb)[0],
        argb_to_rgba(instance.color_argb)[1],
        argb_to_rgba(instance.color_argb)[2],
        argb_to_rgba(instance.color_argb)[3],
        matrix4_json_array(instance.transform),
        matrix4_json_array(frame.view_matrix),
        matrix4_json_array(frame.projection_matrix),
        samples.join(","),
        instance.flags & WORLD_MESH_INSTANCE_FLAG_CAMERA_SORTED_QUADS != 0,
        asset.index_bytes.len() / index_stride,
        batches.iter().filter(|candidate| candidate.key.mesh_key == mesh_key).count() <= 4096,
        batches.iter().filter(|candidate| candidate.key.mesh_key == mesh_key)
            .take(4096).map(|candidate| format!("[{},{}]", candidate.index_offset, candidate.index_count))
            .collect::<Vec<_>>().join(","),
        frontend.mesh_texture_resources.get(&batch.key.texture_id).map_or(0, |resource| resource.mip_levels),
    );
    let payload = payload.replacen(
        "\"samples\":[",
        &format!(
            "\"batchSummaries\":[{}],\"samples\":[",
            batch_summaries.join(",")
        ),
        1,
    );
    let root = PathBuf::from(root);
    if std::fs::create_dir_all(&root).is_ok() {
        let _ = std::fs::write(root.join("static_terrain_batch_trace.json"), payload);
    }
}

fn static_terrain_batch_projected_bounds(
    frame: &WorldPrimitiveFrame,
    frontend: &WorldPrimitiveFrontend,
    batch: &MeshBatch,
) -> Option<[f32; 4]> {
    let asset = frontend.mesh_assets.get(&batch.key.mesh_key)?;
    let instance_index = *batch.indices.first()?;
    let instance = frame.mesh_instances.get(instance_index)?;
    let index_stride = index_stride(asset.index_type) as usize;
    let start = usize::try_from(batch.index_offset).ok()?;
    let count = usize::try_from(batch.index_count).ok()?.min(4_096);
    let mut bounds = [
        f32::INFINITY,
        f32::INFINITY,
        f32::NEG_INFINITY,
        f32::NEG_INFINITY,
    ];
    let mut found = false;
    for ordinal in 0..count {
        let byte_index = ordinal.checked_mul(index_stride)?.checked_add(start)?;
        let index = mesh_index_value(
            &asset.index_bytes,
            asset.index_type,
            byte_index / index_stride,
        )
        .ok()?;
        let vertex_offset = usize::try_from(index)
            .ok()?
            .checked_mul(WORLD_MESH_GPU_VERTEX_BYTES)?;
        let position_bytes = asset.vertex_bytes.get(vertex_offset..vertex_offset + 12)?;
        let position: [f32; 3] = std::array::from_fn(|component| {
            let offset = component * 4;
            f32::from_ne_bytes(
                position_bytes[offset..offset + 4]
                    .try_into()
                    .expect("fixed packed world mesh position lane"),
            )
        });
        let model = transform_column_major_vec4(
            instance.transform,
            [position[0], position[1], position[2], 1.0],
        );
        let view = transform_column_major_vec4(frame.view_matrix, model);
        let clip = transform_column_major_vec4(frame.projection_matrix, view);
        if !clip[3].is_finite() || clip[3].abs() <= f32::EPSILON {
            continue;
        }
        let x = clip[0] / clip[3];
        let y = clip[1] / clip[3];
        if !x.is_finite() || !y.is_finite() {
            continue;
        }
        bounds[0] = bounds[0].min(x);
        bounds[1] = bounds[1].min(y);
        bounds[2] = bounds[2].max(x);
        bounds[3] = bounds[3].max(y);
        found = true;
    }
    found.then_some(bounds)
}

#[derive(Clone, Copy)]
struct MeshSectionRange {
    key: MeshResourceKey,
    index_offset: u64,
    index_count: u32,
}

fn compatible_mesh_section_ranges(
    instance: &WorldMeshInstanceRequest,
    asset: &MeshAssetStore,
    color_format: ColorFormat,
    g_buffer: bool,
) -> GalResult<Vec<MeshSectionRange>> {
    let mut ranges = Vec::new();
    let Some(first) = asset.sections.first() else {
        return Ok(ranges);
    };
    let mut current_key = mesh_key_for_section(
        instance,
        first,
        0,
        first.cull_policy,
        asset.mesh_generation,
        color_format,
        g_buffer,
    );
    let mut current_offset = first.index_offset as u64;
    let mut current_count = first.index_count;
    let mut previous = first;
    for (section_index, section) in asset.sections.iter().enumerate().skip(1) {
        let key = mesh_key_for_section(
            instance,
            section,
            section_index as u32,
            section.cull_policy,
            asset.mesh_generation,
            color_format,
            g_buffer,
        );
        if mesh_sections_can_coalesce(&current_key, &key, previous, section, asset.index_type)
            && current_count
                .checked_add(section.index_count)
                .ok_or_else(|| {
                    GalError::invalid_argument("world mesh range index count overflow")
                })?
                <= u32::MAX
        {
            current_count += section.index_count;
        } else {
            ranges.push(MeshSectionRange {
                key: current_key,
                index_offset: current_offset,
                index_count: current_count,
            });
            current_key = key;
            current_offset = section.index_offset as u64;
            current_count = section.index_count;
        }
        previous = section;
    }
    ranges.push(MeshSectionRange {
        key: current_key,
        index_offset: current_offset,
        index_count: current_count,
    });
    Ok(ranges)
}

fn mesh_sections_can_coalesce(
    current_key: &MeshResourceKey,
    next_key: &MeshResourceKey,
    current_section: &WorldMeshSection,
    next_section: &WorldMeshSection,
    index_type: IndexType,
) -> bool {
    let mut compatible_next = *current_key;
    compatible_next.section_index = next_key.section_index;
    compatible_next == *next_key
        && contiguous_index_range(current_section, next_section, index_type)
}

fn contiguous_index_range(
    current_section: &WorldMeshSection,
    next_section: &WorldMeshSection,
    index_type: IndexType,
) -> bool {
    let Some(current_byte_len) =
        (current_section.index_count as u64).checked_mul(index_stride(index_type))
    else {
        return false;
    };
    current_section.index_offset as u64 + current_byte_len == next_section.index_offset as u64
}

fn index_stride(index_type: IndexType) -> u64 {
    match index_type {
        IndexType::U16 => 2,
        IndexType::U32 => 4,
    }
}

fn push_mesh_batch(
    batches: &mut Vec<MeshBatch>,
    key_to_batch: &mut HashMap<MeshResourceKey, usize>,
    key: MeshResourceKey,
    index_offset: u64,
    index_count: u32,
    instance_index: usize,
) -> GalResult<()> {
    // A translucent section's producer order is its back-to-front order.
    // Unlike opaque terrain, two equal resource keys separated by another
    // translucent section are not interchangeable: merging them would move
    // the later draw in front of that intervening section. Coalesce only
    // immediately adjacent equal translucent records, retaining the exact
    // semantic command stream while still avoiding redundant instance draws.
    if material_mode_uses_alpha_blending(key.material_mode) || key.standard_item_foil {
        if let Some(batch) = batches.last_mut().filter(|batch| batch.key == key) {
            if batch.index_offset != index_offset || batch.index_count != index_count {
                return Err(GalError::invalid_argument(
                    "adjacent translucent world mesh records use incompatible index ranges",
                ));
            }
            batch.indices.push(instance_index);
        } else {
            batches.push(MeshBatch {
                key,
                index_offset,
                index_count,
                indices: vec![instance_index],
            });
        }
        return Ok(());
    }
    if let Some(batch_index) = key_to_batch.get(&key).copied() {
        let batch = &mut batches[batch_index];
        if batch.index_offset != index_offset || batch.index_count != index_count {
            return Err(GalError::invalid_argument(
                "world mesh batch key maps to incompatible index range",
            ));
        }
        batch.indices.push(instance_index);
    } else {
        let batch_index = batches.len();
        key_to_batch.insert(key, batch_index);
        batches.push(MeshBatch {
            key,
            index_offset,
            index_count,
            indices: vec![instance_index],
        });
    }
    Ok(())
}

fn mesh_key_for_section(
    instance: &WorldMeshInstanceRequest,
    section: &WorldMeshSection,
    section_index: u32,
    cull_policy: u32,
    resource_generation: u64,
    color_format: ColorFormat,
    g_buffer: bool,
) -> MeshResourceKey {
    MeshResourceKey {
        g_buffer,
        standard_item_foil: instance.item_foil.is_some(),
        stratum: instance.stratum,
        mesh_key: instance.mesh_key,
        mesh_generation: resource_generation,
        section_index,
        material_id: section.material_id,
        texture_id: section.texture_id,
        material_mode: section.material_mode,
        winding: section.winding,
        depth_policy: instance.depth_policy,
        cull_policy,
        color_format,
    }
}

fn mesh_pipeline_key(key: MeshResourceKey) -> GalResult<MeshPipelineResourceKey> {
    let terrain_program = if key.standard_item_foil {
        if key.material_mode != WORLD_MATERIAL_MODE_GLINT {
            return Err(GalError::invalid_argument("standard foil binding requires glint material"));
        }
        minimal_direct_standard_item_foil_program()
    } else {
        terrain_program_for_mode(key.material_mode, key.g_buffer)?
    };
    Ok(MeshPipelineResourceKey {
        g_buffer: key.g_buffer,
        material_mode: key.material_mode,
        winding: key.winding,
        depth_policy: key.depth_policy,
        cull_policy: key.cull_policy,
        color_format: key.color_format,
        shader_program_identity: terrain_program.identity,
        shader_resource_layout: None,
    })
}

fn source_mesh_resource_key(
    mesh: MeshResourceKey,
    candidate: &TerrainSourceProgramCandidate,
) -> SourceMeshResourceKey {
    SourceMeshResourceKey {
        mesh,
        shader_program_identity: candidate.program.identity.clone(),
        shader_resource_layout: candidate.binding.map(|binding| binding.resource_layout),
        shader_resource_generation: candidate
            .binding
            .map(|binding| binding.resource_generation)
            .unwrap_or(0),
    }
}

fn mesh_pipeline_layouts(
    mesh_material_layout: Handle,
    shader_resource_layout: Option<Handle>,
) -> GalResult<Vec<Handle>> {
    let mut layouts = vec![mesh_material_layout];
    if let Some(shader_layout) = shader_resource_layout {
        if shader_layout == mesh_material_layout {
            return Err(GalError::invalid_argument(
                "shader-pack resource layout must be distinct from the mesh/material layout",
            ));
        }
        layouts.push(shader_layout);
    }
    Ok(layouts)
}

fn depth_compare_for_policy(depth_policy: u32) -> GalResult<Option<CompareOp>> {
    match depth_policy {
        WORLD_DEPTH_POLICY_DISABLED => Ok(None),
        WORLD_DEPTH_POLICY_TEST_WRITE | WORLD_DEPTH_POLICY_TEST_NO_WRITE => {
            Ok(Some(CompareOp::LessOrEqual))
        }
        _ => Err(GalError::ffi(
            StatusCode::UnknownEnum,
            format!("unknown world mesh depth policy {depth_policy}"),
        )),
    }
}

fn effective_cull_mode_for_winding(policy: u32, winding: u32) -> GalResult<CullMode> {
    match (policy, winding) {
        (WORLD_CULL_NONE, WORLD_WINDING_CCW | WORLD_WINDING_CW) => Ok(CullMode::None),
        (WORLD_CULL_BACK, WORLD_WINDING_CCW) => Ok(CullMode::Back),
        (WORLD_CULL_FRONT, WORLD_WINDING_CCW) => Ok(CullMode::Front),
        (WORLD_CULL_BACK, WORLD_WINDING_CW) => Ok(CullMode::Front),
        (WORLD_CULL_FRONT, WORLD_WINDING_CW) => Ok(CullMode::Back),
        (_, WORLD_WINDING_CCW | WORLD_WINDING_CW) => Err(GalError::ffi(
            StatusCode::UnknownEnum,
            format!("unknown world mesh cull policy {policy}"),
        )),
        _ => Err(GalError::ffi(
            StatusCode::UnknownEnum,
            format!("unknown world mesh winding {winding}"),
        )),
    }
}

/// Material quads use one canonical vertex payload.  The explicit winding
/// declaration is realized by the immutable index buffer, matching Frozen's
/// cloud shader vertex selection without smuggling a per-face branch into the
/// Rust shader.  Raster culling remains the copied pipeline policy.
fn material_quad_indices_for_winding(winding: u32) -> GalResult<[u32; 6]> {
    match winding {
        WORLD_WINDING_CCW => Ok([0, 1, 2, 2, 3, 0]),
        // Frozen's nearby inside-cloud faces select `3 - quadVertex` for the
        // ordinary sequential QUADS index stream.  This is that exact indexed
        // triangle expansion: [3, 2, 1, 1, 0, 3].
        WORLD_WINDING_CW => Ok([3, 2, 1, 1, 0, 3]),
        _ => Err(GalError::ffi(
            StatusCode::UnknownEnum,
            format!("unknown world material winding {winding}"),
        )),
    }
}

/// One capture process may opt into a bounded source-raster isolation probe.
/// The setting is deliberately private to the source-derived diagnostic route;
/// normal gameplay never reads it and cannot inherit relaxed raster state.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SelectedSourceRasterProbe {
    None,
    NoCull,
    DepthDisabled,
    BlendDisabled,
    InvertFrontFace,
}

fn selected_source_raster_probe() -> GalResult<SelectedSourceRasterProbe> {
    selected_source_raster_probe_from(
        std::env::var("MATTMC_RUST_SELECTED_SOURCE_RASTER_PROBE")
            .ok()
            .as_deref(),
    )
}

fn selected_source_raster_probe_from(value: Option<&str>) -> GalResult<SelectedSourceRasterProbe> {
    match value.map(str::trim) {
        None | Some("") => Ok(SelectedSourceRasterProbe::None),
        Some("no-cull") => Ok(SelectedSourceRasterProbe::NoCull),
        Some("depth-disabled") => Ok(SelectedSourceRasterProbe::DepthDisabled),
        Some("blend-disabled") => Ok(SelectedSourceRasterProbe::BlendDisabled),
        Some("invert-front-face") => Ok(SelectedSourceRasterProbe::InvertFrontFace),
        Some(other) => Err(GalError::invalid_argument(format!(
            "unknown selected-source raster probe '{other}'; expected no-cull, depth-disabled, blend-disabled, or invert-front-face"
        ))),
    }
}

/// Produces the generic material raster state from explicit semantic policy.
/// A probe is process-local capture instrumentation; absent it, this is the
/// production state for every material, including clouds.
fn generic_material_raster_state(
    source_program: u32,
    material_mode: u32,
    depth_policy: u32,
    cull_policy: u32,
) -> GalResult<(CullMode, FrontFace, BlendMode, Option<CompareOp>)> {
    // A capture probe is deliberately limited to the cloud family under
    // investigation.  Other generic material producers share this backend
    // helper, and letting their pixels respond would make a cloud experiment
    // inconclusive rather than proving the selected cloud draw's state.
    let probe = if source_program == WORLD_MATERIAL_SOURCE_CLOUDS {
        selected_source_raster_probe()?
    } else {
        SelectedSourceRasterProbe::None
    };
    generic_material_raster_state_for(probe, material_mode, depth_policy, cull_policy)
}

fn generic_material_raster_state_for(
    probe: SelectedSourceRasterProbe,
    material_mode: u32,
    depth_policy: u32,
    cull_policy: u32,
) -> GalResult<(CullMode, FrontFace, BlendMode, Option<CompareOp>)> {
    let mut cull_mode = cull_mode_from_policy(cull_policy)?;
    let mut front_face = FrontFace::CounterClockwise;
    let mut blend = if material_mode == WORLD_MATERIAL_MODE_GLINT {
        BlendMode::Glint
    } else if material_mode_uses_alpha_blending(material_mode) {
        BlendMode::Alpha
    } else {
        BlendMode::Disabled
    };
    let mut depth_compare = if material_mode == WORLD_MATERIAL_MODE_GLINT {
        Some(CompareOp::Equal)
    } else {
        match depth_policy {
            WORLD_DEPTH_POLICY_DISABLED => None,
            WORLD_DEPTH_POLICY_TEST_WRITE | WORLD_DEPTH_POLICY_TEST_NO_WRITE => {
                Some(CompareOp::LessOrEqual)
            }
            _ => {
                return Err(GalError::ffi(
                    StatusCode::UnknownEnum,
                    format!("unknown world material depth policy {depth_policy}"),
                ));
            }
        }
    };
    match probe {
        SelectedSourceRasterProbe::None | SelectedSourceRasterProbe::InvertFrontFace => {}
        SelectedSourceRasterProbe::NoCull => cull_mode = CullMode::None,
        SelectedSourceRasterProbe::DepthDisabled => depth_compare = None,
        SelectedSourceRasterProbe::BlendDisabled => blend = BlendMode::Disabled,
    }
    front_face = selected_source_raster_probe_front_face_for(probe, front_face)?;
    Ok((cull_mode, front_face, blend, depth_compare))
}

pub(super) fn selected_source_raster_probe_cull_mode() -> GalResult<CullMode> {
    match selected_source_raster_probe()? {
        SelectedSourceRasterProbe::NoCull => Ok(CullMode::None),
        SelectedSourceRasterProbe::None
        | SelectedSourceRasterProbe::DepthDisabled
        | SelectedSourceRasterProbe::BlendDisabled
        | SelectedSourceRasterProbe::InvertFrontFace => Ok(CullMode::Back),
    }
}

pub(super) fn selected_source_raster_probe_front_face(normal: FrontFace) -> GalResult<FrontFace> {
    selected_source_raster_probe_front_face_for(selected_source_raster_probe()?, normal)
}

fn selected_source_raster_probe_front_face_for(
    probe: SelectedSourceRasterProbe,
    normal: FrontFace,
) -> GalResult<FrontFace> {
    match probe {
        SelectedSourceRasterProbe::InvertFrontFace => Ok(match normal {
            FrontFace::CounterClockwise => FrontFace::Clockwise,
            FrontFace::Clockwise => FrontFace::CounterClockwise,
        }),
        SelectedSourceRasterProbe::None
        | SelectedSourceRasterProbe::NoCull
        | SelectedSourceRasterProbe::DepthDisabled
        | SelectedSourceRasterProbe::BlendDisabled => Ok(normal),
    }
}

fn asset_generation_for_key(_mesh_key: u64, asset: &MeshAssetStore) -> GalResult<u64> {
    if asset.sections.is_empty() {
        return Err(GalError::invalid_argument(
            "world mesh asset has no sections",
        ));
    }
    Ok(asset.mesh_generation)
}

fn create_material_data_slot(
    gal: &mut VulkanicGal,
    label: &str,
    resource_layout: Handle,
    texture_view: Handle,
    sampler: Handle,
) -> GalResult<MaterialDataSlot> {
    let uniform_buffer = gal.create_buffer(BufferDesc {
        label: format!("{label}.material-data"),
        size: WORLD_MATERIAL_UNIFORM_BYTES,
        memory: MemoryDomain::Upload,
        usages: vec![
            BufferUsage::Storage,
            BufferUsage::TransferDst,
            BufferUsage::HostWrite,
        ],
    })?;
    let resource_set = match gal.create_resource_set(ResourceSetDesc {
        label: format!("{label}.resource-set"),
        layout: resource_layout,
        bindings: vec![
            ResourceBinding {
                binding: 0,
                array_index: 0,
                resource: uniform_buffer,
                kind: ResourceBindingKind::StorageBuffer,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
            ResourceBinding {
                binding: 1,
                array_index: 0,
                resource: texture_view,
                kind: ResourceBindingKind::SampledTexture,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
            ResourceBinding {
                binding: 2,
                array_index: 0,
                resource: sampler,
                kind: ResourceBindingKind::Sampler,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
        ],
    }) {
        Ok(resource_set) => resource_set,
        Err(error) => {
            let _ = gal.destroy(uniform_buffer);
            return Err(error);
        }
    };
    Ok(MaterialDataSlot {
        uniform_buffer,
        resource_set,
    })
}

fn create_mesh_resource_set(
    gal: &mut VulkanicGal,
    label: &str,
    resource_layout: Handle,
    vertex_buffer: Handle,
    vertex_range: u64,
    instance_buffer: Handle,
    texture_view: Handle,
    sampler: Handle,
    standard_foil: bool,
) -> GalResult<Handle> {
    gal.create_resource_set(ResourceSetDesc {
        label: format!("{label}.resource-set"),
        layout: resource_layout,
        bindings: vec![
            ResourceBinding {
                binding: 0,
                array_index: 0,
                resource: vertex_buffer,
                kind: ResourceBindingKind::StorageBuffer,
                access: AccessFlags::READ,
                dynamic_offsets: vec![0],
                buffer_range: Some(vertex_range),
            },
            ResourceBinding {
                binding: 1,
                array_index: 0,
                resource: instance_buffer,
                kind: ResourceBindingKind::StorageBuffer,
                access: AccessFlags::READ,
                dynamic_offsets: vec![0],
                buffer_range: Some(WORLD_MESH_INSTANCE_STREAM_BINDING_RANGE_BYTES),
            },
            ResourceBinding {
                binding: 2,
                array_index: 0,
                resource: texture_view,
                kind: ResourceBindingKind::SampledTexture,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
            ResourceBinding {
                binding: 3,
                array_index: 0,
                resource: sampler,
                kind: ResourceBindingKind::Sampler,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
        ].into_iter().chain(standard_foil.then_some(ResourceBinding {
            binding: 4,
            array_index: 0,
            resource: instance_buffer,
            kind: ResourceBindingKind::StorageBuffer,
            access: AccessFlags::READ,
            dynamic_offsets: vec![0],
            buffer_range: Some((WORLD_MAX_MESH_INSTANCES * 48) as u64),
        })).collect(),
    })
}

fn create_entity_outline_resource_set(
    gal: &mut VulkanicGal,
    label: &str,
    resource_layout: Handle,
    vertex_buffer: Handle,
    instance_buffer: Handle,
    instance_range: u64,
    texture_view: Handle,
    sampler: Handle,
) -> GalResult<Handle> {
    if instance_range == 0 {
        return Err(GalError::invalid_argument(
            "entity outline resource set requires a non-empty instance range",
        ));
    }
    gal.create_resource_set(ResourceSetDesc {
        label: format!("{label}.resource-set"),
        layout: resource_layout,
        bindings: vec![
            ResourceBinding {
                binding: 0,
                array_index: 0,
                resource: vertex_buffer,
                kind: ResourceBindingKind::StorageBuffer,
                access: AccessFlags::READ,
                dynamic_offsets: vec![0],
                buffer_range: None,
            },
            ResourceBinding {
                binding: 1,
                array_index: 0,
                resource: instance_buffer,
                kind: ResourceBindingKind::StorageBuffer,
                access: AccessFlags::READ,
                dynamic_offsets: vec![0],
                buffer_range: Some(instance_range),
            },
            // The outline shader does not sample material data, but the
            // shared mesh layout keeps these descriptors present so this set
            // remains compatible with the explicit mesh pipeline cache.
            ResourceBinding {
                binding: 2,
                array_index: 0,
                resource: texture_view,
                kind: ResourceBindingKind::SampledTexture,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
            ResourceBinding {
                binding: 3,
                array_index: 0,
                resource: sampler,
                kind: ResourceBindingKind::Sampler,
                access: AccessFlags::READ,
                dynamic_offsets: Vec::new(),
                buffer_range: None,
            },
        ],
    })
}

