    #[test]
    fn distant_horizons_opaque_depth_snapshot_is_scheduled_once_after_all_sections() {
        let schedules = (0..3)
            .map(|index| distant_horizons_opaque_depth_schedule(index, 3))
            .collect::<Vec<_>>();
        assert_eq!(
            vec![
                TextureUsageState::Undefined,
                TextureUsageState::ShaderRead,
                TextureUsageState::ShaderRead,
            ],
            schedules
                .iter()
                .map(|schedule| schedule.depth_before)
                .collect::<Vec<_>>(),
            "each later opaque section must resume the shared live depth image"
        );
        assert_eq!(
            vec![
                Some(TextureUsageState::ShaderRead),
                Some(TextureUsageState::ShaderRead),
                None,
            ],
            schedules
                .iter()
                .map(|schedule| schedule.depth_after)
                .collect::<Vec<_>>(),
            "only the final opaque writer may leave depth ready for the snapshot"
        );
        assert_eq!(
            1,
            schedules
                .iter()
                .filter(|schedule| schedule.snapshot_after_draw)
                .count(),
            "the DH depth history must be copied once for the complete opaque phase"
        );
    }

    #[test]
    fn source_command_partition_keeps_complete_pass_segments_together() {
        let operations = vec![
            CommandOp::Draw {
                vertices: 3,
                instances: 1,
            },
            CommandOp::EndPass,
            CommandOp::Draw {
                vertices: 3,
                instances: 1,
            },
            CommandOp::EndPass,
            CommandOp::Draw {
                vertices: 3,
                instances: 1,
            },
            CommandOp::EndPass,
        ];
        let lists = WorldPrimitiveFrontend::partition_command_lists_at_pass_boundaries(
            "source-test",
            operations.clone(),
            4,
        )
        .unwrap();

        assert_eq!(lists.len(), 2);
        assert_eq!(lists[0].operations.len(), 4);
        assert_eq!(lists[1].operations.len(), 2);
        assert!(lists.iter().all(|list| list.operations.len() <= 4));
        assert_eq!(
            lists
                .into_iter()
                .flat_map(|list| list.operations)
                .collect::<Vec<_>>(),
            operations
        );
    }

