    #[test]
    fn hand_source_targets_preserve_world_color_and_reserve_a_fresh_depth_domain() {
        let source = complete_bundled_pack_source_for_test();
        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        frontend
            .apply_shader_pack_source_update(ShaderPackSourceUpdate {
                pack_name: source.name().to_string(),
                generation: source.generation(),
                files: source.files(),
            })
            .unwrap();
        frontend
            .ensure_shader_runtime(&mut gal, source.generation())
            .unwrap();
        frontend.observe_shader_pack_source_candidate_for_scope(TerrainProgramScope::Overworld);
        let program = frontend
            .shader_runtime
            .as_ref()
            .unwrap()
            .prepared_lowered_hand_source_program()
            .unwrap()
            .expect("the bundled hand source must prepare before any hand route is admitted");
        let extent = Extent3d {
            width: 160,
            height: 90,
            depth: 1,
        };
        let color_targets = frontend
            .shader_runtime
            .as_mut()
            .unwrap()
            .stage_source_color_targets(&mut gal, 11, extent)
            .unwrap()
            .expect("prepared hand source requires owned named color targets");
        let clear_values = ShaderPackColorBootstrapClearValues {
            fog_color: ClearColor {
                r: 0.1,
                g: 0.2,
                b: 0.3,
                a: 1.0,
            },
        };
        let first = frontend
            .stage_hand_source_color_pass_targets(
                &mut gal,
                11,
                1,
                extent,
                &program,
                &color_targets,
                clear_values,
            )
            .unwrap()
            .clone();
        let cached = frontend
            .stage_hand_source_color_pass_targets(
                &mut gal,
                11,
                1,
                extent,
                &program,
                &color_targets,
                clear_values,
            )
            .unwrap()
            .clone();
        assert_eq!(TerrainSourceColorPassPhase::Hands, first.phase);
        assert_eq!(first.target, cached.target);
        assert_eq!(first.pass, cached.pass);
        assert_eq!(first.depth_texture, cached.depth_texture);
        assert_eq!(first.depth_view, cached.depth_view);
        assert_eq!(
            1,
            frontend.hand_source_depth_targets.len(),
            "the private hand depth attachment must be cached independently from world depth"
        );
        assert_eq!(
            1,
            frontend.source_terrain_color_pass_targets.len(),
            "first-person targets must cache by semantic world/pack/depth identity"
        );
        assert_eq!(
            program.named_output_color_slots(),
            first
                .color_attachments
                .iter()
                .map(|attachment| (attachment.output, attachment.source_slot))
                .collect::<Vec<_>>(),
            "hand output roles must be resolved from the selected pack rather than attachment positions"
        );
        assert!(
            !frontend.candidate_lowered_source_execution_enabled,
            "target staging alone must not admit selected-source gameplay execution"
        );

        // A graph-generation change is enough to make the private depth
        // attachment incompatible. Keep the named color generation itself
        // unchanged here: replacing it before its submission outcome is known
        // must remain rejected by the shader runtime.
        let next_graph = frontend
            .stage_hand_source_color_pass_targets(
                &mut gal,
                11,
                2,
                extent,
                &program,
                &color_targets,
                clear_values,
            )
            .unwrap()
            .clone();
        assert_ne!(first.depth_texture, next_graph.depth_texture);
        assert_ne!(first.depth_view, next_graph.depth_view);
        assert_eq!(
            1,
            frontend.hand_source_depth_targets.len(),
            "a graph change must retire the incompatible private hand depth generation"
        );
        assert_eq!(
            1,
            frontend.source_terrain_color_pass_targets.len(),
            "the hand target wrapper must retire before its incompatible depth view"
        );
        frontend.destroy_source_terrain_color_pass_targets(&mut gal);
        assert!(frontend.hand_source_depth_targets.is_empty());
        assert!(frontend.source_terrain_color_pass_targets.is_empty());
    }

