    pub(crate) fn mesh_asset(
        mesh_key: u64,
        generation: u64,
        index_type: IndexType,
    ) -> WorldMeshAsset {
        let vertices = vec![
            WorldMeshVertex {
                position: [-0.5, -0.5, -1.0],
                uv: [0.0, 0.0],
                shader_atlas_uv: [0.25, 0.25],
                shader_block_id: 10232,
                shader_material_type: -1,
                terrain_material_bits: 0,
                mid_block_packed: 0,
                color_argb: 0xffff_ffff,
                normal_packed: 0,
                light: 0,
            },
            WorldMeshVertex {
                position: [0.5, -0.5, -1.0],
                uv: [1.0, 0.0],
                shader_atlas_uv: [0.5, 0.25],
                shader_block_id: 10232,
                shader_material_type: -1,
                terrain_material_bits: 0,
                mid_block_packed: 0,
                color_argb: 0xffff_ffff,
                normal_packed: 0,
                light: 0,
            },
            WorldMeshVertex {
                position: [0.5, 0.5, -1.0],
                uv: [1.0, 1.0],
                shader_atlas_uv: [0.5, 0.5],
                shader_block_id: 10232,
                shader_material_type: -1,
                terrain_material_bits: 0,
                mid_block_packed: 0,
                color_argb: 0xffff_ffff,
                normal_packed: 0,
                light: 0,
            },
            WorldMeshVertex {
                position: [-0.5, 0.5, -1.0],
                uv: [0.0, 1.0],
                shader_atlas_uv: [0.25, 0.5],
                shader_block_id: 10232,
                shader_material_type: -1,
                terrain_material_bits: 0,
                mid_block_packed: 0,
                color_argb: 0xffff_ffff,
                normal_packed: 0,
                light: 0,
            },
        ];
        let index_bytes = match index_type {
            IndexType::U16 => vec![0, 0, 1, 0, 2, 0, 2, 0, 3, 0, 0, 0],
            IndexType::U32 => vec![
                0, 0, 0, 0, 1, 0, 0, 0, 2, 0, 0, 0, 2, 0, 0, 0, 3, 0, 0, 0, 0, 0, 0, 0,
            ],
        };
        WorldMeshAsset {
            mesh_key,
            mesh_generation: generation,
            vertex_layout_version: WORLD_MESH_VERTEX_LAYOUT_V2,
            index_type,
            vertices,
            index_bytes,
            sections: vec![WorldMeshSection {
                material_id: WORLD_MATERIAL_ID_OPAQUE_TEXTURED,
                texture_id: WORLD_MATERIAL_TEXTURE_STONE,
                material_mode: WORLD_MATERIAL_MODE_OPAQUE,
                cull_policy: WORLD_CULL_BACK,
                winding: WORLD_WINDING_CCW,
                index_offset: 0,
                index_count: 6,
            }],
            entity_identity: String::new(),
        }
    }

    #[test]
    fn source_entity_mesh_preparation_uses_local_uvs_and_canonical_identity() {
        let mut mesh = mesh_asset(0xe771_7e57, 4, IndexType::U16);
        mesh.entity_identity = "minecraft:arrow".to_string();
        mesh.sections[0].material_mode = WORLD_MATERIAL_MODE_CUTOUT;
        mesh.vertices[0].uv = [0.10, 0.20];
        mesh.vertices[1].uv = [0.70, 0.20];
        mesh.vertices[2].uv = [0.70, 0.80];
        mesh.vertices[3].uv = [0.10, 0.80];
        mesh.vertices[0].shader_atlas_uv = [0.90, 0.90];

        let prepared = prepare_source_entity_mesh_asset(&mesh).unwrap();
        assert_eq!("minecraft:arrow", prepared.entity_identity);
        assert_eq!(4 * TERRAIN_SOURCE_VERTEX_BYTES, prepared.vertex_bytes.len());
        assert_eq!(6 * std::mem::size_of::<u32>(), prepared.index_bytes.len());
        assert_eq!(
            vec![0, 1, 2, 2, 3, 0],
            prepared
                .index_bytes
                .chunks_exact(4)
                .map(|bytes| u32::from_ne_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>()
        );
        let lane = |vertex: usize, offset: usize| -> [f32; 4] {
            let start = vertex * TERRAIN_SOURCE_VERTEX_BYTES + offset;
            std::array::from_fn(|component| {
                f32::from_ne_bytes(
                    prepared.vertex_bytes[start + component * 4..start + (component + 1) * 4]
                        .try_into()
                        .unwrap(),
                )
            })
        };
        assert_eq!([0.10, 0.20, 0.0, 0.0], lane(0, 48));
        assert_eq!([0.40, 0.50, 0.0, 1.0], lane(0, 80));
    }

    #[test]
    fn source_entity_mesh_preparation_rejects_missing_identity_but_retains_explicit_alpha_modes() {
        let missing = mesh_asset(0xe771_7001, 1, IndexType::U16);
        let missing_error = prepare_source_entity_mesh_asset(&missing).unwrap_err();
        assert!(
            missing_error
                .to_string()
                .contains("canonical entity identity")
        );

        let mut translucent = mesh_asset(0xe771_7002, 1, IndexType::U16);
        translucent.entity_identity = "minecraft:arrow".to_string();
        translucent.sections[0].material_mode = WORLD_MATERIAL_MODE_TRANSLUCENT;
        assert_eq!(
            WORLD_MATERIAL_MODE_TRANSLUCENT,
            prepare_source_entity_mesh_asset(&translucent)
                .expect("the selected entity writer must retain explicit alpha semantics")
                .sections[0]
                .material_mode
        );

        let mut glint = mesh_asset(0xe771_7004, 1, IndexType::U16);
        glint.entity_identity = "minecraft:arrow".to_string();
        glint.sections[0].material_mode = WORLD_MATERIAL_MODE_GLINT;
        assert_eq!(
            WORLD_MATERIAL_MODE_GLINT,
            prepare_source_entity_mesh_asset(&glint)
                .expect("vanilla foil must remain an explicit Rust-owned entity material")
                .sections[0]
                .material_mode
        );

        let mut invalid_identity = mesh_asset(0xe771_7003, 1, IndexType::U16);
        invalid_identity.entity_identity = "Minecraft:Arrow".to_string();
        let identity_error = prepare_source_entity_mesh_asset(&invalid_identity).unwrap_err();
        assert!(
            identity_error
                .to_string()
                .contains("canonical entity identity")
        );
    }

    #[test]
    fn source_entity_mesh_preparation_is_frame_owned_and_generation_bound() {
        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        let mut asset = mesh_asset(0xe771_ca5e, 3, IndexType::U16);
        asset.entity_identity = "minecraft:arrow".to_string();
        asset.sections[0].material_id = WORLD_MATERIAL_ID_CUTOUT_TEXTURED;
        asset.sections[0].material_mode = WORLD_MATERIAL_MODE_CUTOUT;
        frontend
            .apply_world_mesh_asset_update(&mut gal, 1, vec![asset], Vec::new())
            .unwrap();

        let first = frontend.source_entity_mesh_asset(0xe771_ca5e, 3).unwrap();
        let second = frontend.source_entity_mesh_asset(0xe771_ca5e, 3).unwrap();
        assert!(
            !Arc::ptr_eq(&first, &second),
            "expanded source entities must be owned by their selected frames, not retained by the world asset cache"
        );
        assert_eq!(first.vertex_bytes, second.vertex_bytes);
        assert_eq!(first.index_bytes, second.index_bytes);
        assert_eq!("minecraft:arrow", first.entity_identity);
        assert!(matches!(
            frontend.mesh_assets.get(&0xe771_ca5e).unwrap().source_input,
            Some(SourceMeshSemanticInput::Entity(_))
        ));
        assert!(
            frontend
                .source_entity_mesh_asset(0xe771_ca5e, 4)
                .unwrap_err()
                .to_string()
                .contains("does not match cached generation")
        );
    }

