    fn entity_source_for_test() -> ShaderPackSource {
        ShaderPackSource::new(
            "source-entity-frame-test",
            17,
            vec![
                ShaderSourceFile::new(
                    "world0/gbuffers_entities.vsh",
                    "#version 130\nvoid main() { vec4 p = gl_Vertex; vec2 light = GetLightMapCoordinates(); vec3 normal = gl_Normal; vec4 color = gl_Color; gl_Position = ftransform(); }",
                ),
                ShaderSourceFile::new(
                    "world0/gbuffers_entities.fsh",
                    "#version 130\nuniform sampler2D tex;\nuniform int entityId;\nuniform int blockEntityId;\nuniform vec4 entityColor;\nvoid DoLighting() {}\nvoid main() { vec4 color = texture2D(tex, texCoord); color *= glColor; color.rgb = mix(color.rgb, entityColor.rgb, entityColor.a); if (blockEntityId < -1) discard; DoLighting(); gl_FragData[0] = color; gl_FragData[1] = color; /* DRAWBUFFERS:06 */ }",
                ),
                ShaderSourceFile::new("entity.properties", "entity.50076=boat\n"),
                ShaderSourceFile::new(TERRAIN_RESOURCE_BINDINGS_PATH, "tex=material_atlas\n"),
            ],
        )
        .unwrap()
    }

    fn prepared_entity_source_program_for_test() -> LoweredEntitySourceProgram {
        let source = entity_source_for_test();
        let contract = derive_entity_contract(&source, TerrainProgramScope::Overworld).unwrap();
        let lowered = lower_entity_source_pair(&source, &contract).unwrap();
        let declarations = TerrainSourceResourceBindings::from_source(&source).unwrap();
        let bindings = bind_entity_source_resources(&lowered, &declarations).unwrap();
        prepare_lowered_entity_source_program(&contract, &lowered, &bindings).unwrap()
    }

    #[test]
    fn source_entity_frame_uses_the_active_pack_entity_render_stage_only_when_declared() {
        let source = ShaderPackSource::new(
            "source-entity-render-stage-test",
            17,
            vec![
                ShaderSourceFile::new(
                    "world0/gbuffers_entities.vsh",
                    "#version 130\nuniform int renderStage;\nvoid main() { vec4 p = gl_Vertex; vec2 light = GetLightMapCoordinates(); vec3 normal = gl_Normal; vec4 color = gl_Color; gl_Position = ftransform(); }",
                ),
                ShaderSourceFile::new(
                    "world0/gbuffers_entities.fsh",
                    "#version 130\nuniform sampler2D tex;\nuniform int entityId;\nuniform int renderStage;\nuniform vec4 entityColor;\nvoid DoLighting() {}\nvoid main() { vec4 color = texture2D(tex, texCoord); color *= glColor; color.rgb = mix(color.rgb, entityColor.rgb, entityColor.a); if (renderStage < 0) discard; DoLighting(); gl_FragData[0] = color; gl_FragData[1] = color; /* DRAWBUFFERS:06 */ }",
                ),
                ShaderSourceFile::new("entity.properties", "entity.50076=boat\n"),
                ShaderSourceFile::new(TERRAIN_RESOURCE_BINDINGS_PATH, "tex=material_atlas\n"),
            ],
        )
        .unwrap();
        let contract = derive_entity_contract(&source, TerrainProgramScope::Overworld).unwrap();
        let lowered = lower_entity_source_pair(&source, &contract).unwrap();
        let declarations = TerrainSourceResourceBindings::from_source(&source).unwrap();
        let bindings = bind_entity_source_resources(&lowered, &declarations).unwrap();
        let program =
            prepare_lowered_entity_source_program(&contract, &lowered, &bindings).unwrap();

        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        frontend
            .apply_shader_pack_source_update(ShaderPackSourceUpdate {
                pack_name: "source-entity-render-stage-test".to_string(),
                generation: 17,
                files: vec![ShaderSourceFile::new(
                    RUNTIME_ENVIRONMENT_PATH,
                    "MC_RENDER_STAGE_ENTITIES=23\n",
                )],
            })
            .unwrap();
        let mut asset = mesh_asset(0xe771_5a6e, 1, IndexType::U16);
        asset.entity_identity = "minecraft:boat".to_string();
        frontend
            .apply_world_mesh_asset_update(&mut gal, 1, vec![asset], Vec::new())
            .unwrap();
        let mut source_frame = frame(Vec::new());
        let mut instance = mesh_instance(0xe771_5a6e, 1);
        instance.stratum = WORLD_STRATUM_ENTITY_MESH;
        source_frame.mesh_instances.push(instance);

        let prepared = frontend
            .prepare_source_entity_frames(&program, &source_frame)
            .unwrap();
        assert_eq!(1, prepared.len());
        let render_stage_offset = program
            .scalar_uniform_requirements
            .fields()
            .iter()
            .find(|requirement| {
                requirement.semantic == Some(TerrainSourceUniformSemantic::RenderStage)
            })
            .expect("selected entity source must retain its referenced renderStage uniform")
            .field
            .offset() as usize;
        assert_eq!(
            23,
            i32::from_ne_bytes(
                prepared[0].scalar_uniforms
                    [render_stage_offset..render_stage_offset + std::mem::size_of::<i32>()]
                    .try_into()
                    .unwrap(),
            ),
            "entity renderStage must be sourced from the active pack generation",
        );
    }

    #[test]
    fn source_entity_frame_supplies_pack_global_atlas_size_from_owned_terrain_atlas() {
        let source = ShaderPackSource::new(
            "source-entity-atlas-size-test",
            19,
            vec![
                ShaderSourceFile::new(
                    "world0/gbuffers_entities.vsh",
                    "#version 130\nvoid main() { vec4 p = gl_Vertex; vec2 light = GetLightMapCoordinates(); vec3 normal = gl_Normal; vec4 color = gl_Color; gl_Position = ftransform(); }",
                ),
                ShaderSourceFile::new(
                    "world0/gbuffers_entities.fsh",
                    "#version 130\nuniform sampler2D tex;\nuniform ivec2 atlasSize;\nuniform int entityId;\nuniform vec4 entityColor;\nvoid DoLighting() {}\nvoid main() { vec4 color = texture2D(tex, texCoord); color *= glColor; color.rgb = mix(color.rgb, entityColor.rgb, entityColor.a); if (atlasSize.x < 1) discard; DoLighting(); gl_FragData[0] = color; gl_FragData[1] = color; /* DRAWBUFFERS:06 */ }",
                ),
                ShaderSourceFile::new("entity.properties", "entity.50076=boat\n"),
                ShaderSourceFile::new(TERRAIN_RESOURCE_BINDINGS_PATH, "tex=material_atlas\n"),
            ],
        )
        .unwrap();
        let contract = derive_entity_contract(&source, TerrainProgramScope::Overworld).unwrap();
        let lowered = lower_entity_source_pair(&source, &contract).unwrap();
        let declarations = TerrainSourceResourceBindings::from_source(&source).unwrap();
        let bindings = bind_entity_source_resources(&lowered, &declarations).unwrap();
        let program =
            prepare_lowered_entity_source_program(&contract, &lowered, &bindings).unwrap();

        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        let mut asset = mesh_asset(0xe771_a715, 1, IndexType::U16);
        asset.entity_identity = "minecraft:boat".to_string();
        frontend
            .apply_world_mesh_asset_update(
                &mut gal,
                1,
                vec![asset],
                vec![WorldMeshTextureAssetPayload {
                    texture_id: WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
                    png_bytes: material_scene_png(0),
                    mip_png_bytes: Vec::new(),
                    frame_width: 0,
                    frame_height: 0,
                    frame_count: 1,
                    frame_ticks: 1,
                    animation_flags: 0,
                    frame_row_size: 0,
                    interpolation_policy: 0,
                    animation_frames: Vec::new(),
                    coordinate_origin: 0,
                    sampling: None,
                    requested_mip_levels: 0,
                }],
            )
            .unwrap();
        let mut source_frame = frame(Vec::new());
        let mut instance = mesh_instance(0xe771_a715, 1);
        instance.stratum = WORLD_STRATUM_ENTITY_MESH;
        source_frame.mesh_instances.push(instance);

        let prepared = frontend
            .prepare_source_entity_frames(&program, &source_frame)
            .unwrap();
        let atlas_offset = program
            .scalar_uniform_requirements
            .fields()
            .iter()
            .find(|requirement| {
                requirement.semantic == Some(TerrainSourceUniformSemantic::MaterialAtlasSize)
            })
            .expect("selected entity source must retain its referenced atlasSize uniform")
            .field
            .offset() as usize;
        assert_eq!(
            [8, 8],
            [
                i32::from_ne_bytes(
                    prepared[0].scalar_uniforms[atlas_offset..atlas_offset + 4]
                        .try_into()
                        .unwrap(),
                ),
                i32::from_ne_bytes(
                    prepared[0].scalar_uniforms[atlas_offset + 4..atlas_offset + 8]
                        .try_into()
                        .unwrap(),
                ),
            ],
            "entity source atlasSize must come from the owned terrain atlas, not its local texture",
        );
    }

    #[test]
    fn source_entity_frame_groups_only_compatible_rust_resolved_entity_semantics() {
        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        let mut asset = mesh_asset(0xe771_1701, 3, IndexType::U16);
        asset.entity_identity = "minecraft:boat".to_string();
        asset.sections[0].material_id = WORLD_MATERIAL_ID_CUTOUT_TEXTURED;
        asset.sections[0].material_mode = WORLD_MATERIAL_MODE_CUTOUT;
        frontend
            .apply_world_mesh_asset_update(&mut gal, 1, vec![asset], Vec::new())
            .unwrap();

        let mut source_frame = frame(Vec::new());
        let mut first = mesh_instance(0xe771_1701, 3);
        first.stratum = WORLD_STRATUM_ENTITY_MESH;
        first.entity_color_argb = 0x8040_80ff;
        first.block_entity_id = 42;
        let mut second = first.clone();
        second.transform[12] = 3.0;
        source_frame.mesh_instances = vec![first, second];

        let prepared = frontend
            .prepare_source_entity_frames(&prepared_entity_source_program_for_test(), &source_frame)
            .unwrap();
        assert_eq!(1, prepared.len());
        let draw = &prepared[0];
        assert_eq!(source_frame.frame_id, draw.frame_id);
        assert_eq!("minecraft:boat", draw.entity_identity);
        assert_eq!(50_076, draw.entity_id);
        assert_eq!(17, draw.entity_id_generation);
        assert_eq!(
            [64.0 / 255.0, 128.0 / 255.0, 1.0, 128.0 / 255.0],
            draw.entity_color
        );
        assert_eq!(
            2 * TERRAIN_SOURCE_INSTANCE_BYTES,
            draw.instance_transforms.len()
        );
        assert_eq!(128, draw.legacy_texture_transforms.len());
        assert!(!draw.scalar_uniforms.is_empty());
        assert_eq!(WORLD_MATERIAL_MODE_CUTOUT, draw.material_mode);
        let program = prepared_entity_source_program_for_test();
        let block_entity_offset = program
            .scalar_uniform_requirements
            .fields()
            .iter()
            .find(|requirement| {
                requirement.semantic == Some(TerrainSourceUniformSemantic::BlockEntityId)
            })
            .expect("selected entity source must retain blockEntityId")
            .field
            .offset() as usize;
        assert_eq!(
            42,
            i32::from_ne_bytes(
                draw.scalar_uniforms[block_entity_offset..block_entity_offset + 4]
                    .try_into()
                    .unwrap()
            )
        );

        let geometry_key = frontend
            .ensure_lowered_source_entity_geometry_resources(&mut gal, &program, draw)
            .unwrap();
        assert_eq!(1, frontend.lowered_source_terrain_geometry_resources.len());
        let upload = frontend
            .pending_lowered_source_terrain_geometry_uploads
            .get(&geometry_key)
            .expect("first entity geometry preparation must queue one owned upload");
        assert!(matches!(
            upload.first(),
            Some(CommandOp::HostWriteBuffer { .. })
        ));
        assert_eq!(
            geometry_key,
            frontend
                .ensure_lowered_source_entity_geometry_resources(&mut gal, &program, draw)
                .unwrap()
        );
        assert_eq!(
            1,
            frontend
                .pending_lowered_source_terrain_geometry_uploads
                .len(),
            "reusing a mesh/program generation must not duplicate entity geometry uploads"
        );
        let (_, frame_data_key, stream) = frontend
            .ensure_lowered_source_entity_data_resources(&mut gal, &program, draw)
            .unwrap();
        assert_eq!(
            1,
            frontend.lowered_source_terrain_frame_data_resources.len()
        );
        assert_eq!(stream.buffer, frame_data_key.stream_buffer);
        let transaction = frontend
            .pending_source_terrain_frame_transactions
            .get(&source_frame.frame_id)
            .expect("entity set-zero preparation must join the owned frame transaction");
        assert_eq!(stream.buffer, transaction.stream_buffer);
        assert!(transaction.operations.iter().any(|operation| matches!(
            operation,
            CommandOp::HostWriteBuffer { buffer, offset, .. }
                if *buffer == stream.buffer && *offset == stream.instance_offset
        )));

        assert!(
            frontend
                .prepare_candidate_source_entity_frames(&source_frame)
                .unwrap_err()
                .to_string()
                .contains("requires a discovered Rust shader runtime")
        );

        source_frame.mesh_instances[0].entity_id = 7;
        assert!(
            frontend
                .prepare_source_entity_frames(
                    &prepared_entity_source_program_for_test(),
                    &source_frame
                )
                .unwrap_err()
                .to_string()
                .contains("Java-supplied shader-pack entity IDs")
        );

        source_frame.mesh_instances[0].entity_id = 0;
        source_frame.mesh_instances[0].block_entity_id = -2;
        assert!(
            frontend
                .prepare_source_entity_frames(
                    &prepared_entity_source_program_for_test(),
                    &source_frame
                )
                .unwrap_err()
                .to_string()
                .contains("invalid block-entity IDs")
        );
    }

    #[test]
    fn source_entity_accepts_mesh_owned_local_texture_and_retires_replacements() {
        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        let texture_id = 0x6213_0047;
        let mut mesh = mesh_asset(0xe771_4401, 3, IndexType::U16);
        mesh.entity_identity = "minecraft:arrow".to_string();
        mesh.sections[0].texture_id = texture_id;
        mesh.sections[0].material_id = WORLD_MATERIAL_ID_CUTOUT_TEXTURED;
        mesh.sections[0].material_mode = WORLD_MATERIAL_MODE_CUTOUT;
        frontend
            .apply_world_mesh_asset_update(
                &mut gal,
                7,
                vec![mesh],
                vec![WorldMeshTextureAssetPayload {
                    texture_id,
                    png_bytes: material_scene_png(0),
                    mip_png_bytes: Vec::new(),
                    frame_width: 0,
                    frame_height: 0,
                    frame_count: 1,
                    frame_ticks: 1,
                    animation_flags: 0,
                    frame_row_size: 0,
                    interpolation_policy: 0,
                    animation_frames: Vec::new(),
                    coordinate_origin: 0,
                    sampling: None,
                    requested_mip_levels: 0,
                }],
            )
            .unwrap();
        let base = TerrainSourceOwnedResourceSet::new(
            TerrainSourceResourceAvailabilitySet::new(17, 3, []).unwrap(),
            [],
        )
        .unwrap();
        let program = prepared_entity_source_program_for_test();
        let (resources, local_identity) = frontend
            .source_resources_for_entity_local_material(&mut gal, &program, &base, texture_id, 44)
            .unwrap();
        assert_eq!((texture_id, 7), local_identity);
        assert!(
            resources
                .combined_sampler_for(TerrainSourceResourceRole::MaterialTexture)
                .is_some()
        );
        assert!(
            frontend
                .source_material_texture_resources
                .contains_key(&texture_id)
        );

        frontend
            .apply_world_mesh_asset_update(
                &mut gal,
                8,
                Vec::new(),
                vec![WorldMeshTextureAssetPayload {
                    texture_id,
                    png_bytes: material_scene_png(1),
                    mip_png_bytes: Vec::new(),
                    frame_width: 0,
                    frame_height: 0,
                    frame_count: 1,
                    frame_ticks: 1,
                    animation_flags: 0,
                    frame_row_size: 0,
                    interpolation_policy: 0,
                    animation_frames: Vec::new(),
                    coordinate_origin: 0,
                    sampling: None,
                    requested_mip_levels: 0,
                }],
            )
            .unwrap();
        assert!(frontend.source_material_texture_resources.is_empty());
        let (_, replaced_identity) = frontend
            .source_resources_for_entity_local_material(&mut gal, &program, &base, texture_id, 45)
            .unwrap();
        assert_eq!((texture_id, 8), replaced_identity);
        assert_eq!(
            1,
            frontend
                .lowered_textured_material_source_local_texture_resources
                .len(),
            "a replacement must not retain an old entity-local sampler binding"
        );
    }

