    #[test]
    fn source_terrain_preparation_preserves_translucent_sections_for_a_distinct_pass() {
        let mut mesh = mesh_asset(0x7a1f, 1, IndexType::U16);
        mesh.sections[0].material_id = WORLD_MATERIAL_ID_WATER_TRANSLUCENT;
        mesh.sections[0].texture_id = WORLD_MATERIAL_TEXTURE_WATER_FLOW;
        mesh.sections[0].material_mode = WORLD_MATERIAL_MODE_TRANSLUCENT;
        for vertex in &mut mesh.vertices {
            vertex.shader_material_type = 2;
            vertex.normal_packed = pack_normal_i8([0.0, 0.0, 1.0]);
        }

        let prepared = prepare_source_terrain_mesh_asset(&mesh).unwrap();
        assert_eq!(6 * std::mem::size_of::<u32>(), prepared.index_bytes.len());
        assert_eq!(
            SourceTerrainMeshSection {
                material_id: WORLD_MATERIAL_ID_WATER_TRANSLUCENT,
                texture_id: WORLD_MATERIAL_TEXTURE_WATER_FLOW,
                material_mode: WORLD_MATERIAL_MODE_TRANSLUCENT,
                cull_policy: WORLD_CULL_BACK,
                winding: WORLD_WINDING_CCW,
                index_offset: 0,
                index_count: 6,
            },
            prepared.sections[0],
            "source preparation must retain water identity for its later, distinct source pass"
        );

        for vertex in &mut mesh.vertices {
            vertex.shader_material_type = 1;
        }
        let error = prepare_source_terrain_mesh_asset(&mesh).unwrap_err();
        assert!(error.to_string().contains("rejects shader material type 1"));

        mesh.sections[0].material_mode = WORLD_MATERIAL_MODE_CUTOUT;
        for vertex in &mut mesh.vertices {
            vertex.shader_material_type = 2;
        }
        let error = prepare_source_terrain_mesh_asset(&mesh).unwrap_err();
        assert!(error.to_string().contains("rejects shader material type 2"));
    }

