    #[test]
    fn world_mesh_stream_growth_rebinds_cached_mesh_resource_sets() {
        let mut asset = mesh_asset(188, 1, IndexType::U16);
        asset.index_bytes.extend_from_slice(&[0, 0, 2, 0, 3, 0]);
        asset.sections.push(WorldMeshSection {
            material_id: WORLD_MATERIAL_ID_OPAQUE_TEXTURED,
            texture_id: WORLD_MATERIAL_TEXTURE_WHITE_WOOL,
            material_mode: WORLD_MATERIAL_MODE_OPAQUE,
            cull_policy: WORLD_CULL_BACK,
            winding: WORLD_WINDING_CCW,
            index_offset: 12,
            index_count: 3,
        });
        validate_mesh_asset(&asset).unwrap();

        let mut gal = gal();
        let target = frame_target(&mut gal, 1, 128, 128);
        let mut frontend = WorldPrimitiveFrontend::default();
        frontend
            .apply_world_mesh_asset_update(&mut gal, 1, vec![asset], Vec::new())
            .unwrap();

        let mut first = frame(Vec::new());
        let mut first_instance = mesh_instance(188, 1);
        first_instance.mesh_section_index = WORLD_MESH_SECTION_ALL;
        first.mesh_instances.push(first_instance);
        frontend
            .append_frame_ops(&mut gal, 1, target, first)
            .unwrap();
        let first_sets = frontend
            .mesh_resources
            .values()
            .map(|resources| resources.resource_set)
            .collect::<BTreeSet<_>>();
        assert!(!first_sets.is_empty());

        let mut second = frame(Vec::new());
        for index in 0..12 {
            let mut instance = mesh_instance(188, 1);
            instance.mesh_section_index = WORLD_MESH_SECTION_ALL;
            instance.transform[12] = index as f32;
            second.mesh_instances.push(instance);
        }
        frontend
            .append_frame_ops(&mut gal, 1, target, second)
            .unwrap();
        let rebound_sets = frontend
            .mesh_resources
            .values()
            .map(|resources| resources.resource_set)
            .collect::<BTreeSet<_>>();

        assert!(
            first_sets.is_disjoint(&rebound_sets),
            "growing the instance stream must rebuild every descriptor set that binds it"
        );
        assert_eq!(
            1,
            frontend.mesh_instance_stream_slots.len(),
            "stream growth must retire superseded capacities instead of retaining them"
        );
    }

