    #[test]
    fn material_asset_update_cancels_unsubmitted_source_local_texture_uploads() {
        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        let texture_id = WORLD_MATERIAL_TEXTURE_WEATHER_RAIN;
        frontend
            .apply_world_material_asset_update(
                &mut gal,
                1,
                vec![WorldMaterialAssetPayload {
                    texture_id,
                    png_bytes: material_scene_png(0),
                }],
            )
            .expect("the initial weather texture generation must install");
        frontend
            .ensure_source_local_material_texture_resources(&mut gal, texture_id, 91)
            .expect("the source frame must be able to stage its first local texture upload");
        assert!(
            frontend
                .source_material_texture_resources
                .contains_key(&texture_id)
        );
        assert!(
            frontend
                .pending_source_material_texture_uploads
                .contains_key(&91)
        );

        frontend
            .apply_world_material_asset_update(
                &mut gal,
                2,
                vec![WorldMaterialAssetPayload {
                    texture_id,
                    png_bytes: material_scene_png(1),
                }],
            )
            .expect("a newer material generation must atomically replace the staged asset");

        assert!(
            frontend.source_material_texture_resources.is_empty(),
            "an unsubmitted old-generation local texture must not survive the replacement"
        );
        assert!(
            frontend.pending_source_material_texture_uploads.is_empty(),
            "old-generation source upload operations must not be eligible for a later frame"
        );
        assert!(
            frontend
                .pending_source_terrain_frame_transactions
                .is_empty(),
            "the replacement must leave no stale source-frame transaction behind"
        );
    }

    #[test]
    fn oversized_source_texture_is_rejected_before_native_resource_creation() {
        let mut gal = gal();
        let mut frontend = WorldPrimitiveFrontend::default();
        let resident_id = WORLD_MATERIAL_TEXTURE_WEATHER_RAIN;
        let requested_id = WORLD_MATERIAL_TEXTURE_WEATHER_SNOW;
        frontend
            .apply_world_material_asset_update(
                &mut gal,
                1,
                vec![WorldMaterialAssetPayload {
                    texture_id: requested_id,
                    png_bytes: material_scene_png(0),
                }],
            )
            .expect("the requested source texture asset must be installed");
        let fake = |seed| MeshTextureResources {
            upload_buffer: Handle::new(HandleKind::Buffer, seed, 1).unwrap(),
            texture: Handle::new(HandleKind::Texture, seed + 1, 1).unwrap(),
            sampler: Handle::new(HandleKind::Sampler, seed + 2, 1).unwrap(),
            view: Handle::new(HandleKind::TextureView, seed + 3, 1).unwrap(),
            width: 65_535,
            height: 65_535,
            mip_levels: 1,
        };
        frontend
            .source_material_texture_resources
            .insert(resident_id, fake(100));
        let error = frontend
            .ensure_source_local_material_texture_resources(&mut gal, requested_id, 91)
            .expect_err("source texture admission must fail at the aggregate byte budget");
        assert!(
            error
                .to_string()
                .contains("source texture residency budget")
        );
        assert!(
            frontend
                .source_material_texture_resources
                .contains_key(&resident_id)
        );
        assert!(
            !frontend
                .source_material_texture_resources
                .contains_key(&requested_id)
        );
    }

    #[test]
    fn shared_runtime_material_scene_matches_opengl_and_vulkan_when_available() {
        let vulkan = match run_runtime_material_scene(RuntimeBackend::Vulkan, 160, 112) {
            Ok(report) => report,
            Err(error) => {
                assert_environment_gap(&error, "Vulkan");
                return;
            }
        };
        let opengl = match run_runtime_material_scene(RuntimeBackend::OpenGl, 160, 112) {
            Ok(report) => report,
            Err(error) => {
                eprintln!("OpenGL material runtime conformance unavailable: {error}");
                assert_environment_gap(&error, "OpenGL");
                return;
            }
        };

        assert_eq!(vulkan.semantic_hash, opengl.semantic_hash);
        assert_eq!(vulkan.initial_hash, vulkan.rollback_hash);
        assert_eq!(opengl.initial_hash, opengl.rollback_hash);
        assert_ne!(vulkan.initial_hash, vulkan.reloaded_hash);
        assert_ne!(opengl.initial_hash, opengl.reloaded_hash);
        assert_material_feature_parity(&vulkan, &opengl);
        assert!(vulkan.initial_stats.material_quad_count >= 8);
        assert!(vulkan.initial_stats.material_batch_count >= 5);
        assert!(vulkan.initial_stats.material_draw_count >= 5);
        assert!(vulkan.initial_stats.material_cache_misses >= 5);
        assert!(vulkan.rollback_stats.material_cache_hits >= 5);
        assert_eq!(
            vulkan.initial_stats.material_quad_count,
            opengl.initial_stats.material_quad_count
        );
        assert_eq!(
            vulkan.initial_stats.material_batch_count,
            opengl.initial_stats.material_batch_count
        );
        assert_eq!(
            vulkan.initial_stats.material_draw_count,
            opengl.initial_stats.material_draw_count
        );
        assert!(vulkan.resize_hash != 0);
        assert!(opengl.resize_hash != 0);
        write_material_comparison_report(&vulkan, &opengl).unwrap();
    }

    #[test]
    fn rust_owned_shader_pack_mesh_scene_matches_opengl_and_vulkan_when_available() {
        let vulkan = match run_runtime_shader_mesh_scene(RuntimeBackend::Vulkan, 192, 128) {
            Ok(report) => report,
            Err(error) => {
                assert_environment_gap(&error, "Vulkan");
                return;
            }
        };
        let opengl = match run_runtime_shader_mesh_scene(RuntimeBackend::OpenGl, 192, 128) {
            Ok(report) => report,
            Err(error) => {
                eprintln!("OpenGL shader-pack mesh conformance unavailable: {error}");
                assert_environment_gap(&error, "OpenGL");
                return;
            }
        };

        assert_eq!(vulkan.semantic_hash, opengl.semantic_hash);
        assert_eq!(5, vulkan.frame_hashes.len());
        assert_eq!(5, opengl.frame_hashes.len());
        assert_eq!(vulkan.rollback_hash, vulkan.frame_hashes[0]);
        assert_eq!(opengl.rollback_hash, opengl.frame_hashes[0]);
        assert!(vulkan.reload_hash != 0);
        assert!(opengl.reload_hash != 0);
        assert_shader_mesh_feature_parity(&vulkan, &opengl);
        assert!(
            vulkan
                .stats
                .iter()
                .all(|stats| stats.mesh_instance_count >= 3)
        );
        assert!(vulkan.stats.iter().all(|stats| stats.mesh_draw_count >= 3));
        assert!(vulkan.stats[0].mesh_cache_misses >= 3);
        assert!(vulkan.stats[1].mesh_cache_hits >= 3);
        assert!(opengl.stats[0].mesh_cache_misses >= 3);
        assert!(opengl.stats[1].mesh_cache_hits >= 3);
        write_shader_mesh_comparison_report(&vulkan, &opengl).unwrap();
        if rust_tracy_enabled_for_test() {
            std::thread::sleep(std::time::Duration::from_millis(750));
            let _ = run_runtime_shader_mesh_scene(RuntimeBackend::Vulkan, 192, 128);
            let _ = run_runtime_shader_mesh_scene(RuntimeBackend::OpenGl, 192, 128);
            std::thread::sleep(std::time::Duration::from_millis(750));
        }
    }

    #[test]
    fn indexed_mesh_shared_atlas_regions_reach_the_expected_gpu_texels_on_both_backends() {
        let vulkan = match run_indexed_mesh_shared_atlas_scene(RuntimeBackend::Vulkan) {
            Ok(samples) => samples,
            Err(error) => {
                assert_environment_gap(&error, "Vulkan");
                return;
            }
        };
        let opengl = match run_indexed_mesh_shared_atlas_scene(RuntimeBackend::OpenGl) {
            Ok(samples) => samples,
            Err(error) => {
                eprintln!("OpenGL indexed-mesh atlas conformance unavailable: {error}");
                assert_environment_gap(&error, "OpenGL");
                return;
            }
        };

        let expected = [
            [236, 30, 26, 255],
            [24, 218, 54, 255],
            [35, 70, 232, 255],
            [228, 202, 38, 255],
        ];
        for (index, (actual, expected)) in vulkan.iter().zip(expected.iter()).enumerate() {
            assert_rgba_near(
                *actual,
                *expected,
                3,
                &format!("Vulkan atlas region {index}"),
            );
        }
        for (index, (actual, expected)) in opengl.iter().zip(expected.iter()).enumerate() {
            assert_rgba_near(
                *actual,
                *expected,
                3,
                &format!("OpenGL atlas region {index}"),
            );
        }
        assert_eq!(
            vulkan, opengl,
            "shared atlas samples must agree across backends"
        );
    }

    #[test]
    fn indexed_entity_mesh_lighting_tracks_the_explicit_instance_pose() {
        let samples = run_indexed_mesh_shared_atlas_scene_with_pose(RuntimeBackend::Vulkan, true)
            .expect("Vulkan transformed-normal regression requires actual GPU rendering");
        // Independent vanilla two-light equation for authored +X normals
        // rotated through 0,90,180,270 degrees. Geometry remains front-facing.
        let directional = 0.2f32 / (0.2f32*0.2 + 1.0 + 0.7*0.7).sqrt();
        let factors = [0.4 + 0.6*directional, 1.0, 0.4 + 0.6*directional, 0.4];
        let colors = [[236u8,30,26,255], [24,218,54,255], [35,70,232,255], [228,202,38,255]];
        for index in 0..4 {
            let mut expected = colors[index];
            for channel in &mut expected[..3] {
                *channel = (*channel as f32 * factors[index]).round() as u8;
            }
            assert_rgba_near(samples[index], expected, 3, "explicit pose normal lighting");
        }
    }

    fn rust_tracy_enabled_for_test() -> bool {
        std::env::var("MATTMC_RUST_TRACY")
            .map(|value| value == "1" || value.eq_ignore_ascii_case("true"))
            .unwrap_or(false)
    }

    #[test]
    fn semantic_background_clear_is_first_frame_operation() {
        let mut gal = gal();
        let target = frame_target(&mut gal, 1, 128, 128);
        let mut frontend = WorldPrimitiveFrontend::default();
        let frame = frame(Vec::new());
        let (ops, stats) = frontend
            .append_frame_ops(&mut gal, 1, target, frame)
            .unwrap();

        assert_eq!(1, stats.background_clear_count);
        assert_eq!(0, stats.background_diagnostic_fallback_count);
        assert_eq!(
            WORLD_BACKGROUND_SKY_OVERWORLD as u64,
            stats.background_sky_type
        );
        assert_eq!(0xff102844, stats.background_color_argb);
        assert!(matches!(ops.first(), Some(CommandOp::Barrier(_))));
        let Some(CommandOp::BeginPass { colors, .. }) = ops.get(1) else {
            panic!("background clear should begin the first pass after the depth barrier");
        };
        let clear = colors[0].clear_color.expect("background clear color");
        assert!((clear.r - (0x10 as f32 / 255.0)).abs() < 0.001);
        assert!((clear.g - (0x28 as f32 / 255.0)).abs() < 0.001);
        assert!((clear.b - (0x44 as f32 / 255.0)).abs() < 0.001);
    }

