    fn selected_source_terrain_capture_starts_from_shader_read() {
        assert_eq!(
            TextureUsageState::ShaderRead,
            selected_source_terrain_capture_before_state()
        );
    }

    #[test]
    fn selected_source_capture_requires_the_requested_frame_and_correlation() {
        let request = GameplayAttachmentCaptureRequest {
            frame_id: 41,
            correlation_id: 7,
            deterministic_rendered_frame_index: 12,
            source_selected_capture: false,
            source_selected_pending: false,
            required_entity_mesh: false,
        };
        assert!(selected_source_capture_request_matches(41, 7, request));
        assert!(!selected_source_capture_request_matches(42, 7, request));
        assert!(!selected_source_capture_request_matches(41, 8, request));
    }

    #[test]
    fn gameplay_attachment_capture_request_requires_complete_nonzero_identity() {
        let root = std::env::temp_dir().join(format!(
            "mattmc-gameplay-attachment-request-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let path = root.join("requested-frame.properties");
        std::fs::write(
            &path,
            "gameplay_frame_id=41\ncorrelation_id=7\ndeterministic_rendered_frame_index=12\n",
        )
        .unwrap();
        assert_eq!(
            GameplayAttachmentCaptureRequest {
                frame_id: 41,
                correlation_id: 7,
                deterministic_rendered_frame_index: 12,
                source_selected_capture: false,
                source_selected_pending: false,
                required_entity_mesh: false,
            },
            GameplayAttachmentCaptureRequest::read(&path).unwrap()
        );
        std::fs::write(&path, "gameplay_frame_id=41\ncorrelation_id=7\n").unwrap();
        assert!(
            GameplayAttachmentCaptureRequest::read(&path)
                .unwrap_err()
                .to_string()
                .contains("deterministic_rendered_frame_index")
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn gameplay_attachment_capture_request_preserves_entity_requirement_across_promotion() {
        let root = std::env::temp_dir().join(format!(
            "mattmc-gameplay-entity-attachment-request-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&root).unwrap();
        let path = root.join("requested-frame.properties");
        std::fs::write(
            &path,
            "gameplay_frame_id=41\ncorrelation_id=7\ndeterministic_rendered_frame_index=12\nsource_selected_capture=1\nsource_selected_pending=1\nrequired_entity_mesh=1\n",
        )
        .unwrap();
        let request = GameplayAttachmentCaptureRequest::read(&path).unwrap();
        assert!(request.required_entity_mesh);
        let promoted = GameplayAttachmentCaptureRequest {
            frame_id: 44,
            correlation_id: 9,
            deterministic_rendered_frame_index: 15,
            source_selected_capture: true,
            source_selected_pending: false,
            required_entity_mesh: request.required_entity_mesh,
        };
        promoted.write_atomic(&path).unwrap();
        assert_eq!(
            GameplayAttachmentCaptureRequest::read(&path).unwrap(),
            promoted
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn diagnostic_png_row_normalization_matches_top_origin_game_captures() {
        let mut pixels = vec![
            1, 0, 0, 255, 2, 0, 0, 255, // bottom row from Vulkan readback
            3, 0, 0, 255, 4, 0, 0, 255, // top row from Vulkan readback
        ];
        flip_rgba_rows_in_place(&mut pixels, 2, 2).unwrap();
        assert_eq!(
            vec![
                3, 0, 0, 255, 4, 0, 0, 255, // top PNG row
                1, 0, 0, 255, 2, 0, 0, 255, // bottom PNG row
            ],
            pixels
        );
    }

