    #[test]
    fn source_gui_target_validation_admits_only_declared_owned_intermediates() {
        let overlay = Handle::new(super::super::handles::HandleKind::RenderTarget, 1, 1)
            .expect("overlay handle");
        let owned_raster = Handle::new(super::super::handles::HandleKind::RenderTarget, 2, 1)
            .expect("owned GUI raster handle");
        let undeclared = Handle::new(super::super::handles::HandleKind::RenderTarget, 3, 1)
            .expect("undeclared target handle");
        let pass =
            Handle::new(super::super::handles::HandleKind::RenderPass, 1, 1).expect("pass handle");
        let owned_ops = vec![
            CommandOp::BeginPass {
                pass,
                target: owned_raster,
                colors: Vec::new(),
                depth_stencil: None,
            },
            CommandOp::Draw {
                vertices: 3,
                instances: 1,
            },
            CommandOp::EndPass,
            CommandOp::BeginPass {
                pass,
                target: overlay,
                colors: Vec::new(),
                depth_stencil: None,
            },
            CommandOp::Draw {
                vertices: 3,
                instances: 1,
            },
            CommandOp::EndPass,
        ];
        WorldPrimitiveFrontend::validate_source_gui_ops(&owned_ops, overlay, &[owned_raster])
            .expect("declared Rust-owned GUI raster target remains valid");

        let error = WorldPrimitiveFrontend::validate_source_gui_ops(
            &[
                CommandOp::BeginPass {
                    pass,
                    target: undeclared,
                    colors: Vec::new(),
                    depth_stencil: None,
                },
                CommandOp::Draw {
                    vertices: 3,
                    instances: 1,
                },
            ],
            overlay,
            &[owned_raster],
        )
        .expect_err("undeclared target must not enter a selected source frame");
        assert!(error.to_string().contains("undeclared target"));

        let missing_draw = WorldPrimitiveFrontend::validate_source_gui_ops(
            &[CommandOp::BeginPass {
                pass,
                target: overlay,
                colors: Vec::new(),
                depth_stencil: None,
            }],
            overlay,
            &[],
        )
        .expect_err("a GUI render pass without a Rust draw must fail closed");
        assert!(
            missing_draw
                .to_string()
                .contains("GUI command list opened a render pass without a Rust draw")
        );
    }

